import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum OrionState {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  SLEEPING = 'SLEEPING',
  ACTIVE = 'ACTIVE', // Speaking/Outputting
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
}

export interface EyeConfig {
  width: number;
  height: number;
  gap: number;
  glowIntensity: number;
}

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message } from "../types";

// Initialize the client strictly with process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  imagePart?: string // Base64 string if an image is attached
): Promise<string> => {
  try {
    // Convert app history to GenAI Content format
    // We filter out system messages from the history array as we pass system instruction via config
    const contents: Content[] = history
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    // Add the new message
    const newParts: Part[] = [];

    if (imagePart) {
      newParts.push({
        inlineData: {
          mimeType: 'image/jpeg', // Assuming jpeg for simplicity, or detect from input
          data: imagePart,
        },
      });
    }

    newParts.push({ text: userMessage });

    contents.push({
      role: 'user',
      parts: newParts,
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7, // Balanced for precision but allowing natural phrasing
        maxOutputTokens: 1000,
      },
    });

    if (response.text) {
      return response.text;
    }

    return "Sinal recebido. Sem dados."; // Fallback consistent with persona
  } catch (error) {
    console.error("Orion System Error:", error);
    return "Erro de processamento. Sistema instável."; // Minimalist error
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  // Internal state for organic blinking independent of main state
  const [isBlinking, setIsBlinking] = useState(false);

  useEffect(() => {
    // Organic blink loop
    let timeoutId: NodeJS.Timeout;

    const blink = () => {
      if (state === OrionState.SLEEPING) return; // Don't blink if sleeping

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 150); // Blink duration

      // Random next blink between 2s and 8s
      const nextBlink = Math.random() * 6000 + 2000;
      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 2000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  // Determine styles based on state
  const getEyeStyles = () => {
    const baseStyle = "bg-white rounded-2xl transition-all duration-700 ease-in-out relative";

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-6",
          eye: `${baseStyle} w-24 h-24 shadow-[0_0_40px_rgba(255,255,255,0.8)] animate-pulse`,
        };
      case OrionState.ACTIVE: // Speaking
        return {
          container: "gap-5",
          eye: `${baseStyle} w-22 h-22 shadow-[0_0_30px_rgba(255,255,255,0.6)]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${baseStyle} w-20 h-1 opacity-20 shadow-none`, // Closed eyes
        };
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${baseStyle} w-20 h-20 shadow-[0_0_20px_rgba(255,255,255,0.4)]`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50' : '';

  return (
    <div className="flex flex-col items-center justify-center w-full h-64 select-none">
      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all duration-700 ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>

      {/* Underline */}
      <div 
        className={`mt-12 h-[1px] bg-white/20 transition-all duration-1000 ease-in-out ${
          state === OrionState.SLEEPING ? 'w-0 opacity-0' : 'w-48 opacity-100'
        }`}
      />
    </div>
  );
};

export default OrionEyes;

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';

interface TerminalOutputProps {
  messages: Message[];
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ messages }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  if (messages.length === 0) return null;

  return (
    <div className="flex-1 w-full max-w-2xl overflow-y-auto px-6 py-4 space-y-6 mask-image-linear-gradient">
      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]`}
          style={{ animationFillMode: 'forwards' }}
        >
          <div 
            className={`max-w-[85%] font-mono text-sm leading-relaxed ${
              msg.role === 'user' 
                ? 'text-zinc-500 text-right' 
                : 'text-zinc-300 text-left'
            }`}
          >
             {msg.role === 'model' && <span className="mr-2 text-zinc-600 select-none">::</span>}
             {msg.content}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default TerminalOutput;

import React, { useState, useRef } from 'react';

interface ChatInputProps {
  onSend: (text: string, file?: File) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSend, disabled }) => {
  const [text, setText] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if ((!text.trim() && !fileInputRef.current?.files?.length) || disabled) return;

    const file = fileInputRef.current?.files?.[0];
    onSend(text, file);
    setText('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e as any);
    }
  };

  return (
    <div className="w-full max-w-xl mx-auto p-6">
      <form onSubmit={handleSubmit} className="relative group">
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          onChange={() => {
             // Optional: Visual indicator that file is selected
             // For minimalist design, we might just rely on the user knowing they attached it
             // or change the input border slightly.
          }}
        />

        <div 
          className={`relative flex items-center border-b transition-colors duration-500 ${
            isFocused ? 'border-white/40' : 'border-white/10'
          }`}
        >
            <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="p-2 text-zinc-600 hover:text-zinc-300 transition-colors"
                title="Anexar dados"
                disabled={disabled}
            >
               <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"></path></svg>
            </button>

            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={handleKeyDown}
              onFocus={() => setIsFocused(true)}
              onBlur={() => setIsFocused(false)}
              disabled={disabled}
              rows={1}
              placeholder="..."
              className="w-full bg-transparent text-zinc-300 font-mono text-sm p-3 focus:outline-none resize-none overflow-hidden placeholder-zinc-800"
              style={{ minHeight: '44px' }}
            />

            <button 
              type="submit"
              disabled={disabled || (!text.trim() && !fileInputRef.current?.files?.length)}
              className="p-2 text-zinc-600 hover:text-zinc-300 transition-colors disabled:opacity-0"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>
            </button>
        </div>
      </form>
    </div>
  );
};

export default ChatInput;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import TerminalOutput from './components/TerminalOutput';
import ChatInput from './components/ChatInput';
import { Message, OrionState } from './types';
import { sendMessageToOrion } from './services/geminiService';

const INACTIVITY_TIMEOUT_MS = 30000; // 30 seconds to sleep

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);
  const [messages, setMessages] = useState<Message[]>([]);
  const inactivityTimer = useRef<NodeJS.Timeout | null>(null);

  // Helper to convert file to base64
  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const result = reader.result as string;
        // Remove 'data:*/*;base64,' prefix
        const base64 = result.split(',')[1];
        resolve(base64);
      };
      reader.onerror = error => reject(error);
    });
  };

  const resetInactivityTimer = useCallback(() => {
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);

    // Only set sleep timer if not currently processing
    if (orionState !== OrionState.PROCESSING) {
      if (orionState === OrionState.SLEEPING) {
        setOrionState(OrionState.IDLE);
      }

      inactivityTimer.current = setTimeout(() => {
        setOrionState(OrionState.SLEEPING);
      }, INACTIVITY_TIMEOUT_MS);
    }
  }, [orionState]);

  // Initial setup and mouse movement tracking to wake up Orion
  useEffect(() => {
    const handleActivity = () => resetInactivityTimer();

    window.addEventListener('mousemove', handleActivity);
    window.addEventListener('keydown', handleActivity);

    resetInactivityTimer();

    return () => {
      window.removeEventListener('mousemove', handleActivity);
      window.removeEventListener('keydown', handleActivity);
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    };
  }, [resetInactivityTimer]);

  const handleSendMessage = async (text: string, file?: File) => {
    // 1. Update State to Processing
    setOrionState(OrionState.PROCESSING);
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);

    // 2. Add User Message to UI
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: file ? `[Arquivo Enviado] ${text}` : text,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      // 3. Process File if exists
      let imageBase64: string | undefined;
      if (file) {
        imageBase64 = await fileToBase64(file);
      }

      // 4. Call Gemini Service
      const responseText = await sendMessageToOrion(newHistory, text, imageBase64);

      // 5. Add System Response
      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      // 6. Brief "Active/Speaking" state before going back to Idle
      setOrionState(OrionState.ACTIVE);
      setTimeout(() => {
        setOrionState(OrionState.IDLE);
        resetInactivityTimer();
      }, 1500);

    } catch (error) {
      console.error("Interaction failed", error);
      setOrionState(OrionState.IDLE);
      resetInactivityTimer();
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative selection:bg-white/20 selection:text-white">

      {/* Visual Presence Area (Top) */}
      <div className="flex-none pt-20 pb-10 w-full flex justify-center z-10">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area (Middle - Scrollable) */}
      <div className="flex-1 w-full flex flex-col items-center justify-end overflow-hidden mb-4 z-10">
        <TerminalOutput messages={messages} />
      </div>

      {/* Input Area (Bottom - Sticky) */}
      <div className="flex-none w-full pb-8 z-20 bg-gradient-to-t from-[#050505] to-transparent">
        <ChatInput 
          onSend={handleSendMessage} 
          disabled={orionState === OrionState.PROCESSING} 
        />
      </div>

      {/* Subtle Background Noise/Grain (Optional Aesthetic) */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

