export enum OrionState {
  IDLE = 'IDLE', // Standard open state
  FOCUSED = 'FOCUSED', // Input active, user typing
  FOCUSED_EMPTY = 'FOCUSED_EMPTY', // Input active but empty (blinking)
  PROCESSING = 'PROCESSING', // Thinking
  ACTIVE = 'ACTIVE', // Speaking/Outputting
  PRE_SLEEP = 'PRE_SLEEP', // Transition: Rapid blinking before sleep
  SQUINTING = 'SQUINTING', // Transition: Eyes pressed/heavy
  SLEEPING = 'SLEEPING', // Fully closed
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
}

export interface LogEntry {
  timestamp: string;
  type: 'USER_INPUT' | 'SYSTEM_RESPONSE' | 'STATE_CHANGE' | 'SYSTEM_ERROR';
  data: any;
}

import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur
}) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      // Don't organic blink during specific animation states
      if (state === OrionState.SLEEPING || state === OrionState.SQUINTING) return;

      // If FOCUSED_EMPTY, blinking is handled by a separate interval/logic or faster rate
      // But we can reuse this if we adjust timing.

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 150);

      // Random next blink
      const nextBlink = state === OrionState.PRE_SLEEP 
        ? 300 + Math.random() * 400 // Fast blinking for pre-sleep
        : state === OrionState.FOCUSED_EMPTY
          ? 1000 + Math.random() * 1000 // Moderate blinking when waiting for input
          : 2000 + Math.random() * 6000; // Normal blinking

      timeoutId = setTimeout(blink, nextBlink);
    };

    // Start loop
    timeoutId = setTimeout(blink, 500);

    return () => clearTimeout(timeoutId);
  }, [state]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  // Calculate styles based on state
  const getEyeStyles = () => {
    const baseStyle = "bg-white transition-all ease-in-out relative";
    // Using inline styles for specific height animations to be smoother

    switch (state) {
      case OrionState.PROCESSING:
