           eye: `${baseStyle} w-20 h-20 rounded-2xl shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-300`,
        };
      case OrionState.FOCUSED:
      case OrionState.FOCUSED_EMPTY:
        return {
          container: "gap-5",
          eye: `${baseStyle} w-20 h-20 rounded-2xl shadow-[0_0_25px_rgba(255,255,255,0.5)] duration-300`,
        };
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${baseStyle} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-700`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-75' : '';

  return (
