    const blink = () => {
      // Don't organic blink during specific animation states
      if (state === OrionState.SLEEPING || state === OrionState.SQUINTING || state === OrionState.PROCESSING) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 150);

      // Blink rate depends on state
      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        // "Piscar os olhos algumas vezes" - Faster blinking before sleep
        nextBlink = 500 + Math.random() * 1000;
      } else if (state === OrionState.FOCUSED_EMPTY) {
        // "Demonstrar tédio" - Moderate/Lazy blinking
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED) {
