import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur
}) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      // Don't organic blink during specific animation states
      if (state === OrionState.SLEEPING || state === OrionState.SQUINTING || state === OrionState.PROCESSING) return;

      // Determine blink duration (how long eyes stay closed)
      // If PRE_SLEEP (Tired), eyes close for longer (slow blink)
      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      // Determine time until next blink
      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        // Tired: Blinks might be irregular or slightly slower frequency to show "fighting"
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        // "Piscando os olhos como um humano" - Natural random intervals
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        // IDLE
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    // Start loop
    timeoutId = setTimeout(blink, 1000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  // Calculate styles based on state
  const getEyeStyles = () => {
    const baseStyle = "bg-white transition-all ease-in-out relative";

    switch (state) {
      case OrionState.PROCESSING:
        // "um salto com os olhos e girar no ar e voltar para a posição inicial girando ainda"
        return {
          container: "gap-6 animate-jump-spin",
          eye: `${baseStyle} w-20 h-20 rounded-full shadow-[0_0_40px_rgba(255,255,255,0.9)]`,
        };
      case OrionState.ACTIVE: // Speaking/Active
        return {
          container: "gap-5",
          eye: `${baseStyle} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: // "Olhos pressionados / fechando aos poucos"
        return {
          container: "gap-6",
          eye: `${baseStyle} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[3000ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${baseStyle} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: // "Tired" look - slightly droopy?
        return {
           container: "gap-5",
           eye: `${baseStyle} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        // Standard "Open" / Human-like
        return {
          container: "gap-5",
          eye: `${baseStyle} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-200' : '';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none pt-12 pb-6">
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-40px) rotate(180deg) scale(1.1); }
          40% { transform: translateY(-10px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-5px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        .animate-jump-spin {
          animation: jump-spin 2s ease-in-out infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>

      {/* Input Line Area */}
      <div className="mt-20 w-full max-w-md flex flex-col items-center justify-center relative group">

        {/* Invisible Input */}
        <input
          ref={inputRef}
          type="text"
          value={inputValue}
          onChange={(e) => onInputChange(e.target.value)}
          onFocus={onInputFocus}
          onBlur={onInputBlur}
          onKeyDown={handleKeyDown}
          disabled={state === OrionState.PROCESSING}
          className="absolute inset-0 w-full h-full opacity-0 cursor-text z-10"
        />

        {/* Visual Line - "Linha com um tom cinza medio" */}
        <div 
          className={`
            h-[2px] transition-all duration-700 ease-in-out relative
            ${state === OrionState.SLEEPING ? 'w-0 opacity-0 bg-zinc-800' : 'w-24 opacity-60 bg-zinc-600'}
            ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? '!w-full max-w-[300px] !opacity-100 !bg-zinc-400 shadow-[0_0_10px_rgba(255,255,255,0.2)]' : ''}
            ${state === OrionState.PROCESSING ? 'w-12 opacity-50 bg-white animate-pulse' : ''}
          `}
        />

        {/* Helper text / Typing mirror */}
        <div className={`
          mt-4 h-6 font-mono text-xs tracking-widest text-zinc-500 transition-opacity duration-300
          ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0'}
        `}>
          {inputValue}
          <span className="animate-pulse">_</span>
        </div>

      </div>
    </div>
  );
};

