        logEvent('STATE_CHANGE', { to: 'SLEEPING' });
      }, 3000); 

    }, 4000); 
  }, [orionState]);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    cancelSleepSequence();
    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
    logEvent('STATE_CHANGE', { to: 'FOCUSED (Human Blink)' });
  };

  const handleInputBlur = () => {
    // Trigger sleep sequence when leaving input
    if (orionState !== OrionState.PROCESSING) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING) return;

    const currentText = inputValue;
    setInputValue(''); // Clear immediately
    cancelSleepSequence();

    // "gerando uma resposta - um salto com os olhos e girar no ar"
    setOrionState(OrionState.PROCESSING);

    // Log User Input
    logEvent('USER_INPUT', { content: currentText });

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const responseText = await sendMessageToOrion(newHistory, currentText);

      // Log System Response
      logEvent('SYSTEM_RESPONSE', { content: responseText });

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      setOrionState(OrionState.ACTIVE);

      // "terminou de gerar a resposta - voltar ao estado inicial dos olhos e manter piscando dentro da conversa"
      setTimeout(() => {
        // Assume active engagement if chat just happened, but wait for input blur to sleep
        setOrionState(OrionState.IDLE);
      }, 1500);

    } catch (error) {
      logEvent('SYSTEM_ERROR', error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden">

      {/* Orion Component (Eyes + Input) */}
      <div className="flex-none w-full z-20 mt-10">
        <OrionEyes 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
        />
      </div>

      {/* Chat Area - "Toda essa areá aqui ira apareecr apenas quando eu realizar a primeira pergunta" */}
      <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden mt-4 mb-10 z-10">
        <TerminalOutput messages={messages} />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

export enum OrionState {
  IDLE = 'IDLE', // Standard open state
  FOCUSED = 'FOCUSED', // Input active, user typing
  FOCUSED_EMPTY = 'FOCUSED_EMPTY', // Input active but empty (blinking)
  PROCESSING = 'PROCESSING', // Thinking
  ACTIVE = 'ACTIVE', // Speaking/Outputting
  PRE_SLEEP = 'PRE_SLEEP', // Transition: Rapid blinking before sleep
  SQUINTING = 'SQUINTING', // Transition: Eyes pressed/heavy
  SLEEPING = 'SLEEPING', // Fully closed
  AWAITING_PERMISSION = 'AWAITING_PERMISSION', // Waiting for user confirmation
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
}

export interface LogEntry {
  timestamp: string;
  type: 'USER_INPUT' | 'SYSTEM_RESPONSE' | 'STATE_CHANGE' | 'SYSTEM_ERROR';
  data: any;
}

export interface PendingAction {
  description: string;
  originalResponse: string;
}

// Simulated System Notification
export interface SysNotification {
  id: string;
  title: string;
  details: string;
  timestamp: number;
  read: boolean;
}

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message, SysNotification } from "../types";

// Initialize the client strictly with process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Mock function to get battery (safe wrapper)
const getBatteryInfo = async () => {
  try {
    // @ts-ignore - navigator.getBattery is not standard in all TS lib definitions yet
    if (navigator.getBattery) {
      // @ts-ignore
      const battery = await navigator.getBattery();
      return `${Math.round(battery.level * 100)}%${battery.charging ? ' (Carregando)' : ''}`;
    }
  } catch (e) {
    return "Indisponível (Sensor restrito)";
  }
  return "Alimentação AC / Desconhecido";
};

// Function to gather "System Senses"
const getSystemContext = async (activeNotifications: SysNotification[]): Promise<string> => {
  const now = new Date();
  const nav = window.navigator;
  const battery = await getBatteryInfo();

  // Filter unread notifications to "feed" to Orion's subconscious
  const unread = activeNotifications.filter(n => !n.read);
  const notificationContext = unread.length > 0 
    ? `ALERTA SENSORIAL: Você detecta ${unread.length} notificações pendentes no sistema: ${unread.map(n => `[${n.title}]`).join(', ')}. (Lembre-se: Só mencione se perguntado).` 
    : "SENSORIAL: Nenhuma notificação pendente.";

  return `
[DADOS DE TELEMETRIA EM TEMPO REAL]
HORA: ${now.toLocaleTimeString()}
DATA: ${now.toLocaleDateString()}
ENERGIA: ${battery}
CONEXÃO: ${nav.onLine ? "Estável (Online)" : "Instável (Offline)"}
PLATAFORMA: ${nav.platform}
RESOLUÇÃO: ${window.screen.width}x${window.screen.height}
MEMÓRIA: ${(nav as any).deviceMemory || '?'} GB
CORES: ${nav.hardwareConcurrency || '?'}
${notificationContext}
`;
};

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  notifications: SysNotification[],
  imagePart?: string 
): Promise<string> => {
  try {
    // Inject system context into the very first message or as a system prelude
    const systemContextString = await getSystemContext(notifications);

    // Convert app history to GenAI Content format
    let contents: Content[] = history
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    if (contents.length > 0 && contents[0].role === 'model') {
       contents.shift();
    }

    const finalUserMessageText = `
${systemContextString}

INPUT DO USUÁRIO:
${userMessage}
`;

    const newParts: Part[] = [];

    if (imagePart) {
      newParts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: imagePart,
        },
      });
    }

    newParts.push({ text: finalUserMessageText });

    contents.push({
      role: 'user',
      parts: newParts,
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7, 
        maxOutputTokens: 1000, 
      },
    });

    if (response.text) {
      return response.text;
    }

    return "Conexão neural instável. Dados perdidos."; 
  } catch (error) {
    console.error("Orion System Error:", error);
    return "Erro crítico nos subsistemas de linguagem."; 
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'init-0',
      role: 'model',
      content: 'Interface neural acoplada. Aguardando input.',
      timestamp: Date.now(),
    }
  ]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // --- Notification Simulation Logic ---
  useEffect(() => {
    // Every 45 seconds, small chance to generate a fake system notification
    const interval = setInterval(() => {
      if (Math.random() > 0.7) { // 30% chance
        const possibleEvents = [
          { title: "Uso de CPU Elevado", details: "Processo 'Chrome' consumindo 85%" },
          { title: "Atualização de Segurança", details: "Patch v2.4 pendente" },
          { title: "Rede Instável", details: "Latência acima de 200ms" },
          { title: "Bateria Otimizada", details: "Modo de economia ativado" }
        ];
        const event = possibleEvents[Math.floor(Math.random() * possibleEvents.length)];

        const newNotif: SysNotification = {
          id: Date.now().toString(),
          title: event.title,
          details: event.details,
          timestamp: Date.now(),
          read: false
        };

        setNotifications(prev => [...prev, newNotif]);
        console.log("[ORION SENSORS] Detecetd event:", event.title);
      }
    }, 45000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    // Don't sleep if waiting for permission
    if (orionState === OrionState.AWAITING_PERMISSION) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (orionState === OrionState.AWAITING_PERMISSION) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (orionState === OrionState.AWAITING_PERMISSION) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, [orionState]);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    // Check for Permission Request Tag: [[REQUEST_PERMISSION: action]]
    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const match = responseText.match(permissionRegex);

    if (match) {
      const actionDescription = match[1];
      const cleanText = responseText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });
      setOrionState(OrionState.AWAITING_PERMISSION);

      return cleanText;
    }

    return responseText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();
    setOrionState(OrionState.PROCESSING);

    // Mark notifications as read if the user is asking about them (simple heuristic: if message contains 'status' or 'notific')
    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      // Pass notifications context
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      // Only return to normal state if NOT waiting for permission
      if (!cleanResponse.includes('REQUEST_PERMISSION') && !pendingAction) {
         setOrionState(OrionState.ACTIVE);
         setTimeout(() => {
             // Check again, race condition safety
             setOrionState(prev => prev === OrionState.AWAITING_PERMISSION ? prev : OrionState.IDLE);
         }, 1500);
      } else {
         // It was set inside processOrionResponse, but double check
         setOrionState(OrionState.AWAITING_PERMISSION);
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    // Reset UI
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    // Add decision to history automatically
    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    // Don't show the technical system message in UI? Or maybe show it as a user action? 
    // Let's show it to be clear.
    setMessages(newHistory);

    // Send back to Orion
    sendMessageToOrion(newHistory, decisionText, notifications).then(response => {
       const clean = processOrionResponse(response);
       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: clean,
         timestamp: Date.now()
       }]);
       setOrionState(OrionState.IDLE);
    });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden">

      {/* Orion Component (Eyes + Input + Permission UI) */}
      <div className="flex-none w-full z-20 mt-10">
        <OrionEyes 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Chat Area */}
      <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden mt-4 mb-10 z-10">
        <TerminalOutput messages={messages} />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { OrionState, PendingAction } from '../types';

interface OrionEyesProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide
}) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      // Don't organic blink during specific animation states or when waiting for permission (stare)
      if (state === OrionState.SLEEPING || state === OrionState.SQUINTING || state === OrionState.PROCESSING || state === OrionState.AWAITING_PERMISSION) return;

      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 1000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  // Calculate styles based on state
  const getEyeStyles = () => {
    // Base eye style
    let baseStyle = "transition-all ease-in-out relative";
    let bgClass = "bg-white"; // Default white eyes

    // Change eye color for permission request (Amber/Orange)
    if (state === OrionState.AWAITING_PERMISSION) {
      bgClass = "bg-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.6)]";
    }

    const eyeBase = `${baseStyle} ${bgClass}`;

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-6 animate-jump-spin",
          eye: `${eyeBase} w-20 h-20 rounded-full shadow-[0_0_40px_rgba(255,255,255,0.9)]`,
        };
      case OrionState.AWAITING_PERMISSION:
         // Staring, pulsing slightly, amber
        return {
          container: "gap-8",
          eye: `${eyeBase} w-24 h-24 rounded-lg animate-pulse-slow`,
        }
      case OrionState.ACTIVE: 
        return {
          container: "gap-5",
          eye: `${eyeBase} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: 
        return {
          container: "gap-6",
          eye: `${eyeBase} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[3000ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${eyeBase} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: 
        return {
           container: "gap-5",
           eye: `${eyeBase} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-200' : '';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none pt-12 pb-6">
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-40px) rotate(180deg) scale(1.1); }
          40% { transform: translateY(-10px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-5px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        .animate-jump-spin {
          animation: jump-spin 2s ease-in-out infinite;
        }
        .animate-pulse-slow {
           animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>

      {/* Input / Permission Area */}
      <div className="mt-20 w-full max-w-md flex flex-col items-center justify-center relative group min-h-[60px]">

        {state === OrionState.AWAITING_PERMISSION && pendingAction ? (
           <div className="flex flex-col items-center w-full animate-[fadeIn_0.3s_ease-out]">
              <div className="text-amber-500 font-mono text-xs tracking-widest mb-4 uppercase text-center max-w-xs">
                 Permissão Requerida: {pendingAction.description}
