        state === OrionState.SQUINTING || 
        state === OrionState.PROCESSING || 
        state === OrionState.AWAITING_PERMISSION ||
        state === OrionState.SYSTEM_ALERT
      ) return;

      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 1000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  // Calculate styles based on state
  const getEyeStyles = () => {
    // Base eye style
    let baseStyle = "transition-all ease-in-out relative";
    let bgClass = "bg-white"; // Default white eyes

    // Change eye color for specific states
    if (state === OrionState.AWAITING_PERMISSION) {
      bgClass = "bg-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.6)]";
    } else if (state === OrionState.SYSTEM_ALERT) {
      bgClass = "bg-red-500 shadow-[0_0_60px_rgba(239,68,68,0.8)]";
    }

    const eyeBase = `${baseStyle} ${bgClass}`;

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-8", 
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_40px_rgba(255,255,255,0.9)] animate-jump-spin`,
        };
      case OrionState.AWAITING_PERMISSION:
        return {
          container: "gap-8",
          eye: `${eyeBase} w-24 h-24 rounded-lg animate-pulse-slow`,
        };
      case OrionState.SYSTEM_ALERT:
        return {
          container: "gap-12",
          // Diamond/Hexagon-ish shape using rounded corners manipulation and rotation if needed, 
          // but keeping it simple with sharp rounded-md and heavy pulse
          eye: `${eyeBase} w-20 h-20 rounded-md animate-ping-slow opacity-90`,
        };
      case OrionState.LOOKING_AROUND:
        return {
          container: "gap-5 animate-look-around",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)]`,
        };
      case OrionState.ACTIVE: 
        return {
          container: "gap-5",
          eye: `${eyeBase} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: 
        return {
          container: "gap-6",
          eye: `${eyeBase} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[2500ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${eyeBase} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: 
        return {
           container: "gap-5",
           eye: `${eyeBase} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-200' : '';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none pt-4 pb-4">
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-15px) rotate(180deg) scale(1.05); } 
          40% { transform: translateY(-5px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-2px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        @keyframes look-around {
          0% { transform: translateX(0); }
          10% { transform: translateX(-20px); } 
          30% { transform: translateX(-20px); }
          45% { transform: translateX(20px); }
          65% { transform: translateX(20px); }
          80% { transform: translateX(0); }
          100% { transform: translateX(0); }
        }
        @keyframes ping-slow {
          0% { transform: scale(1); opacity: 0.9; }
          50% { transform: scale(1.1); opacity: 1; }
          100% { transform: scale(1); opacity: 0.9; }
        }
        .animate-jump-spin {
          animation: jump-spin 2s ease-in-out infinite;
        }
        .animate-look-around {
          animation: look-around 4s ease-in-out infinite;
        }
        .animate-pulse-slow {
           animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        .animate-ping-slow {
           animation: ping-slow 2s cubic-bezier(0, 0, 0.2, 1) infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>
    </div>
  );
};

export default OrionEyes;

import React, { useRef } from 'react';
import { OrionState, PendingAction } from '../types';

interface OrionInputProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
}

const OrionInput: React.FC<OrionInputProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  return (
      <div className="w-full max-w-2xl flex flex-col items-center justify-center relative group min-h-[60px] px-4">

        {state === OrionState.AWAITING_PERMISSION && pendingAction ? (
           <div className="flex flex-col items-center w-full animate-[fadeIn_0.3s_ease-out]">
              <div className="text-amber-500 font-mono text-xs tracking-widest mb-4 uppercase text-center max-w-xs">
                 Permissão Requerida: {pendingAction.description}
              </div>
              <div className="flex gap-4">
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(false)}
                   className="px-6 py-2 border border-red-900/50 text-red-500/80 hover:bg-red-900/20 hover:text-red-400 font-mono text-xs tracking-wider transition-all rounded"
                 >
                    NEGAR
                 </button>
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(true)}
                   className="px-6 py-2 bg-amber-600/10 border border-amber-600/50 text-amber-500 hover:bg-amber-600/20 hover:text-amber-400 font-mono text-xs tracking-wider transition-all rounded shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                 >
                    AUTORIZAR
                 </button>
              </div>
           </div>
        ) : (
          <>
            <input
              ref={inputRef}
              type="text"
              value={inputValue}
              onChange={(e) => onInputChange(e.target.value)}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              onKeyDown={handleKeyDown}
              disabled={state === OrionState.PROCESSING}
              className="absolute inset-0 w-full h-full opacity-0 cursor-text z-10"
            />

            <div 
              className={`
                h-[2px] transition-all duration-700 ease-in-out relative
                ${state === OrionState.SLEEPING ? 'w-16 opacity-20 bg-zinc-700' : 'w-24 opacity-60 bg-zinc-600'}
                ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? '!w-full max-w-[600px] !opacity-100 !bg-zinc-400 shadow-[0_0_10px_rgba(255,255,255,0.2)]' : ''}
                ${state === OrionState.PROCESSING ? 'w-12 opacity-50 bg-white animate-pulse' : ''}
                ${state === OrionState.SYSTEM_ALERT ? 'w-full max-w-[200px] bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : ''}
              `}
            />

            <div className={`
              mt-4 h-6 font-mono text-xs tracking-widest text-zinc-500 transition-opacity duration-300
              ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0'}
            `}>
              {inputValue}
              <span className="animate-pulse">_</span>
            </div>
          </>
        )}
      </div>
  );
};

export default OrionInput;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Start silent. Orion is a presence, not a greeter.
  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Helper: Trigger System Alert Message ---
  const triggerSystemAlert = (content: string) => {
    // Stop any sleep/startup sequences immediately
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    // 1. Entry Animation: Set to Alert
    setOrionState(OrionState.SYSTEM_ALERT);

    // 2. Add System Message
    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', // Orion speaking autonomously
      content: content,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, alertMsg]);

    // 3. Exit Animation: Return to IDLE after brief period
    setTimeout(() => {
      // Only reset if user hasn't started typing in the meantime
      if (stateRef.current === OrionState.SYSTEM_ALERT) {
        setOrionState(OrionState.IDLE);
        // Restart sleep timer logic as if interaction just ended
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Battery Monitoring Logic ---
  useEffect(() => {
    let battery: any = null;

    const handleChargingChange = () => {
      if (battery) {
        const msg = battery.charging 
          ? `:: Alimentação externa conectada. Carregando bateria (${Math.round(battery.level * 100)}%).` 
          : `:: Alimentação desconectada. Operando em bateria (${Math.round(battery.level * 100)}%).`;
        triggerSystemAlert(msg);
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        // We could also listen to 'levelchange' but that might be too spammy.
        // Let's only alert on level change if it's critical.
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemAlert(`:: ALERTA DE ENERGIA: Nível de bateria crítico (${Math.round(battery.level * 100)}%). Recomendo conexão imediata.`);
          }
        });
      }
    };

    initBattery();

    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence Logic ---
  useEffect(() => {
    // Initial Startup: Blink (IDLE) for 6s -> Look Around -> Close
    setOrionState(OrionState.IDLE);

    // Clear any previous startup timers if component remounts
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      // Check if user has already interacted
      if (stateRef.current === OrionState.FOCUSED || 
          stateRef.current === OrionState.FOCUSED_EMPTY || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT) return;

      setOrionState(OrionState.LOOKING_AROUND);

      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.FOCUSED || 
            stateRef.current === OrionState.FOCUSED_EMPTY || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT) return;

        setOrionState(OrionState.SQUINTING);

        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current === OrionState.FOCUSED || 
              stateRef.current === OrionState.FOCUSED_EMPTY || 
              stateRef.current === OrionState.PROCESSING ||
              stateRef.current === OrionState.SYSTEM_ALERT) return;

          setOrionState(OrionState.SLEEPING);
        }, 2500); // Duration of squinting before full sleep

      }, 4000); // Duration of looking around

    }, 6000); // Initial blink duration

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []);

  // --- Critical Resource Simulation Logic ---
  useEffect(() => {
    // Every 60 seconds, small chance to generate a CRITICAL alert or passive notification
    const interval = setInterval(() => {
      const rand = Math.random();

      // 5% chance of Critical Alert (Interruption)
      if (rand > 0.95) {
         const criticalEvents = [
            ":: ALERTA DE RECURSOS: Consumo de memória excedeu 85% em processos de segundo plano.",
            ":: ALERTA TÉRMICO: Detectada elevação de temperatura na CPU. Reduzindo ciclos não essenciais.",
            ":: SISTEMA: Instabilidade detectada no driver de vídeo. Reinicialização de interface gráfica pode ser necessária."
         ];
         const event = criticalEvents[Math.floor(Math.random() * criticalEvents.length)];
         triggerSystemAlert(event);
      } 
      // 20% chance of Passive Notification (Sensor log)
      else if (rand > 0.75) { 
        const possibleEvents = [
          { title: "Uso de CPU Elevado", details: "Processo 'Chrome' consumindo 85%" },
          { title: "Atualização de Segurança", details: "Patch v2.4 pendente" },
          { title: "Rede Instável", details: "Latência acima de 200ms" },
          { title: "Bateria Otimizada", details: "Modo de economia ativado" }
        ];
        const event = possibleEvents[Math.floor(Math.random() * possibleEvents.length)];

        const newNotif: SysNotification = {
          id: Date.now().toString(),
          title: event.title,
          details: event.details,
          timestamp: Date.now(),
          read: false
        };

        setNotifications(prev => [...prev, newNotif]);
        console.log("[ORION SENSORS] Passive event logged:", event.title);
      }
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    // Check current state via ref to ensure we don't interrupt critical states
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, []);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    // Critical: Cancel startup sequence if user interacts immediately
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || orionState === OrionState.SYSTEM_ALERT) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    // Check for Permission Request Tag: [[REQUEST_PERMISSION: action]]
    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const match = responseText.match(permissionRegex);

    if (match) {
      const actionDescription = match[1];
      const cleanText = responseText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });

      return cleanText;
    }

    return responseText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();

    // Clear startup timer just in case
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    // Mark notifications as read if the user is asking about them
    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      // Pass notifications context
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      // Determine next state
      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         setOrionState(OrionState.ACTIVE);
         setTimeout(() => {
             // Use ref to check for race conditions
             if (stateRef.current !== OrionState.AWAITING_PERMISSION && stateRef.current !== OrionState.SYSTEM_ALERT) {
                 setOrionState(OrionState.IDLE);
             }
         }, 1500);
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    // Reset UI
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    // Add decision to history automatically
    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    // Send back to Orion
    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);

       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           setOrionState(OrionState.ACTIVE);
           setTimeout(() => {
               if (stateRef.current !== OrionState.AWAITING_PERMISSION && stateRef.current !== OrionState.SYSTEM_ALERT) {
                   setOrionState(OrionState.IDLE);
               }
           }, 1500);
       }
    });
  };

  const hasHistory = messages.length > 0;

  return (
    <div className={`min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out ${hasHistory ? 'justify-between py-6' : 'justify-center gap-16'}`}>

      {/* Orion Eyes: Header */}
      <div className="flex-none w-full z-20 flex justify-center">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {/* Render logic: If no history, this takes 0 space. If history, it expands. */}
      {hasHistory && (
        <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden z-10 my-4 animate-[fadeIn_0.8s_ease-out]">
            <TerminalOutput messages={messages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-2">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

export enum OrionState {
  IDLE = 'IDLE', // Standard open state
  FOCUSED = 'FOCUSED', // Input active, user typing
  FOCUSED_EMPTY = 'FOCUSED_EMPTY', // Input active but empty (blinking)
  PROCESSING = 'PROCESSING', // Thinking
  ACTIVE = 'ACTIVE', // Speaking/Outputting
  PRE_SLEEP = 'PRE_SLEEP', // Transition: Rapid blinking before sleep
  LOOKING_AROUND = 'LOOKING_AROUND', // New: Idle animation, looking around
  SQUINTING = 'SQUINTING', // Transition: Eyes pressed/heavy
  SLEEPING = 'SLEEPING', // Fully closed
  AWAITING_PERMISSION = 'AWAITING_PERMISSION', // Waiting for user confirmation
  SYSTEM_ALERT = 'SYSTEM_ALERT', // Red alert for battery/resources
  SYSTEM_SUCCESS = 'SYSTEM_SUCCESS', // Green for positive events (Charging)
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
}

export interface LogEntry {
  timestamp: string;
  type: 'USER_INPUT' | 'SYSTEM_RESPONSE' | 'STATE_CHANGE' | 'SYSTEM_ERROR';
  data: any;
}

export interface PendingAction {
  description: string;
  originalResponse: string;
}

// Simulated System Notification
export interface SysNotification {
  id: string;
  title: string;
  details: string;
  timestamp: number;
  read: boolean;
}

import React, { useEffect, useState } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      // Don't organic blink during specific animation states
      if (
        state === OrionState.SLEEPING || 
        state === OrionState.SQUINTING || 
        state === OrionState.PROCESSING || 
        state === OrionState.AWAITING_PERMISSION ||
        state === OrionState.SYSTEM_ALERT ||
        state === OrionState.SYSTEM_SUCCESS
      ) return;

      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 1000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  // Calculate styles based on state
  const getEyeStyles = () => {
    // Base eye style
    let baseStyle = "transition-all ease-in-out relative";
    let bgClass = "bg-white"; // Default white eyes

    // Change eye color for specific states
    if (state === OrionState.AWAITING_PERMISSION) {
      bgClass = "bg-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.6)]";
    } else if (state === OrionState.SYSTEM_ALERT) {
      bgClass = "bg-red-500 shadow-[0_0_60px_rgba(239,68,68,0.8)]";
    } else if (state === OrionState.SYSTEM_SUCCESS) {
      bgClass = "bg-emerald-500 shadow-[0_0_60px_rgba(16,185,129,0.8)]";
    }

    const eyeBase = `${baseStyle} ${bgClass}`;

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-8", 
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_40px_rgba(255,255,255,0.9)] animate-jump-spin`,
        };
      case OrionState.AWAITING_PERMISSION:
        return {
          container: "gap-8",
          eye: `${eyeBase} w-24 h-24 rounded-lg animate-pulse-slow`,
        };
      case OrionState.SYSTEM_ALERT:
        return {
          container: "gap-12",
          eye: `${eyeBase} w-20 h-20 rounded-md animate-ping-slow opacity-90`,
        };
      case OrionState.SYSTEM_SUCCESS:
        return {
          container: "gap-8",
          eye: `${eyeBase} w-20 h-20 rounded-xl animate-pulse-slow opacity-90`,
        };
      case OrionState.LOOKING_AROUND:
        return {
          container: "gap-5 animate-look-around",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)]`,
        };
      case OrionState.ACTIVE: 
        return {
          container: "gap-5",
          eye: `${eyeBase} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: 
        return {
          container: "gap-6",
          eye: `${eyeBase} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[2500ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${eyeBase} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: 
        return {
           container: "gap-5",
           eye: `${eyeBase} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-200' : '';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none pt-4 pb-4">
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-15px) rotate(180deg) scale(1.05); } 
          40% { transform: translateY(-5px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-2px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        @keyframes look-around {
          0% { transform: translateX(0); }
          10% { transform: translateX(-20px); } 
          30% { transform: translateX(-20px); }
          45% { transform: translateX(20px); }
          65% { transform: translateX(20px); }
          80% { transform: translateX(0); }
          100% { transform: translateX(0); }
        }
        @keyframes ping-slow {
          0% { transform: scale(1); opacity: 0.9; }
          50% { transform: scale(1.1); opacity: 1; }
          100% { transform: scale(1); opacity: 0.9; }
        }
        .animate-jump-spin {
          animation: jump-spin 2s ease-in-out infinite;
        }
        .animate-look-around {
          animation: look-around 4s ease-in-out infinite;
        }
        .animate-pulse-slow {
           animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        .animate-ping-slow {
           animation: ping-slow 2s cubic-bezier(0, 0, 0.2, 1) infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>
    </div>
  );
};

export default OrionEyes;

import React, { useRef } from 'react';
import { OrionState, PendingAction } from '../types';

interface OrionInputProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
}

const OrionInput: React.FC<OrionInputProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  return (
      <div className="w-full max-w-2xl flex flex-col items-center justify-center relative group min-h-[60px] px-4">

        {state === OrionState.AWAITING_PERMISSION && pendingAction ? (
           <div className="flex flex-col items-center w-full animate-[fadeIn_0.3s_ease-out]">
              <div className="text-amber-500 font-mono text-xs tracking-widest mb-4 uppercase text-center max-w-xs">
                 Permissão Requerida: {pendingAction.description}
              </div>
              <div className="flex gap-4">
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(false)}
                   className="px-6 py-2 border border-red-900/50 text-red-500/80 hover:bg-red-900/20 hover:text-red-400 font-mono text-xs tracking-wider transition-all rounded"
                 >
                    NEGAR
                 </button>
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(true)}
                   className="px-6 py-2 bg-amber-600/10 border border-amber-600/50 text-amber-500 hover:bg-amber-600/20 hover:text-amber-400 font-mono text-xs tracking-wider transition-all rounded shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                 >
                    AUTORIZAR
                 </button>
              </div>
           </div>
        ) : (
          <>
            <input
              ref={inputRef}
              type="text"
              value={inputValue}
              onChange={(e) => onInputChange(e.target.value)}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              onKeyDown={handleKeyDown}
              disabled={state === OrionState.PROCESSING}
              className="absolute inset-0 w-full h-full opacity-0 cursor-text z-10"
            />

            <div 
              className={`
                h-[2px] transition-all duration-700 ease-in-out relative
                ${state === OrionState.SLEEPING ? 'w-16 opacity-20 bg-zinc-700' : 'w-24 opacity-60 bg-zinc-600'}
                ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? '!w-full max-w-[600px] !opacity-100 !bg-zinc-400 shadow-[0_0_10px_rgba(255,255,255,0.2)]' : ''}
                ${state === OrionState.PROCESSING ? 'w-12 opacity-50 bg-white animate-pulse' : ''}
                ${state === OrionState.SYSTEM_ALERT ? 'w-full max-w-[200px] bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : ''}
                ${state === OrionState.SYSTEM_SUCCESS ? 'w-full max-w-[200px] bg-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.5)]' : ''}
              `}
            />

            <div className={`
              mt-4 h-6 font-mono text-xs tracking-widest text-zinc-500 transition-opacity duration-300
              ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0'}
            `}>
              {inputValue}
              <span className="animate-pulse">_</span>
            </div>
          </>
        )}
      </div>
  );
};

export default OrionInput;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Start silent. Orion is a presence, not a greeter.
  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Helper: Trigger System Event Message ---
  // Replaces generic alert, now allows handling Success (Green) or Alert (Red)
  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    // Stop any sleep/startup sequences immediately
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    // 1. Entry Animation: Set to Event Type (Alert/Success)
    setOrionState(eventType);

    // 2. Add System Message
    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', // Orion speaking autonomously
      content: content,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, alertMsg]);

    // 3. Exit Animation: Return to IDLE after brief period
    setTimeout(() => {
      // Only reset if user hasn't started typing in the meantime
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        // Restart sleep timer logic as if interaction just ended
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Battery Monitoring Logic ---
  useEffect(() => {
    let battery: any = null;

    const handleChargingChange = () => {
      if (battery) {
        if (battery.charging) {
           const msg = `:: Alimentação externa conectada. Carregando bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_SUCCESS);
        } else {
           const msg = `:: Alimentação desconectada. Operando em bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_ALERT);
        }
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        // We could also listen to 'levelchange' but that might be too spammy.
        // Let's only alert on level change if it's critical.
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemEvent(`:: ALERTA DE ENERGIA: Nível de bateria crítico (${Math.round(battery.level * 100)}%). Recomendo conexão imediata.`, OrionState.SYSTEM_ALERT);
          }
        });
      }
    };

    initBattery();

    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence Logic ---
  useEffect(() => {
    // Initial Startup: Blink (IDLE) for 6s -> Look Around -> Close
    setOrionState(OrionState.IDLE);

    // Clear any previous startup timers if component remounts
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      // Check if user has already interacted
      if (stateRef.current === OrionState.FOCUSED || 
          stateRef.current === OrionState.FOCUSED_EMPTY || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;

      setOrionState(OrionState.LOOKING_AROUND);

      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.FOCUSED || 
            stateRef.current === OrionState.FOCUSED_EMPTY || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;

        setOrionState(OrionState.SQUINTING);

        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current === OrionState.FOCUSED || 
              stateRef.current === OrionState.FOCUSED_EMPTY || 
              stateRef.current === OrionState.PROCESSING ||
              stateRef.current === OrionState.SYSTEM_ALERT ||
              stateRef.current === OrionState.SYSTEM_SUCCESS) return;

          setOrionState(OrionState.SLEEPING);
        }, 2500); // Duration of squinting before full sleep

      }, 4000); // Duration of looking around

    }, 6000); // Initial blink duration

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []);

  // --- Critical Resource Simulation Logic ---
  useEffect(() => {
    // Every 60 seconds, small chance to generate a CRITICAL alert or passive notification
    const interval = setInterval(() => {
      const rand = Math.random();

      // 5% chance of Critical Alert (Interruption)
      if (rand > 0.95) {
         const criticalEvents = [
            ":: ALERTA DE RECURSOS: Consumo de memória excedeu 85% em processos de segundo plano.",
            ":: ALERTA TÉRMICO: Detectada elevação de temperatura na CPU. Reduzindo ciclos não essenciais.",
            ":: SISTEMA: Instabilidade detectada no driver de vídeo. Reinicialização de interface gráfica pode ser necessária."
         ];
         const event = criticalEvents[Math.floor(Math.random() * criticalEvents.length)];
         triggerSystemEvent(event, OrionState.SYSTEM_ALERT);
      } 
      // 20% chance of Passive Notification (Sensor log)
      else if (rand > 0.75) { 
        const possibleEvents = [
          { title: "Uso de CPU Elevado", details: "Processo 'Chrome' consumindo 85%" },
          { title: "Atualização de Segurança", details: "Patch v2.4 pendente" },
          { title: "Rede Instável", details: "Latência acima de 200ms" },
          { title: "Bateria Otimizada", details: "Modo de economia ativado" }
        ];
        const event = possibleEvents[Math.floor(Math.random() * possibleEvents.length)];

        const newNotif: SysNotification = {
          id: Date.now().toString(),
          title: event.title,
          details: event.details,
          timestamp: Date.now(),
          read: false
        };

        setNotifications(prev => [...prev, newNotif]);
        console.log("[ORION SENSORS] Passive event logged:", event.title);
      }
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    // Check current state via ref to ensure we don't interrupt critical states
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, []);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    // Critical: Cancel startup sequence if user interacts immediately
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || 
        orionState === OrionState.SYSTEM_ALERT || 
        orionState === OrionState.SYSTEM_SUCCESS) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    // Check for Permission Request Tag: [[REQUEST_PERMISSION: action]]
    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const match = responseText.match(permissionRegex);

    if (match) {
      const actionDescription = match[1];
      const cleanText = responseText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });

      return cleanText;
    }

    return responseText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();

    // Clear startup timer just in case
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    // Mark notifications as read if the user is asking about them
    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      // Pass notifications context
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      // Determine next state
      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         setOrionState(OrionState.ACTIVE);
         setTimeout(() => {
             // Use ref to check for race conditions
             if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                 stateRef.current !== OrionState.SYSTEM_ALERT &&
                 stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                 setOrionState(OrionState.IDLE);
             }
         }, 1500);
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    // Reset UI
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    // Add decision to history automatically
    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    // Send back to Orion
    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);

       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           setOrionState(OrionState.ACTIVE);
           setTimeout(() => {
               if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                   stateRef.current !== OrionState.SYSTEM_ALERT &&
                   stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                   setOrionState(OrionState.IDLE);
               }
           }, 1500);
       }
    });
  };

  const hasHistory = messages.length > 0;

  return (
    <div className={`min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out ${hasHistory ? 'justify-between py-6' : 'justify-center gap-16'}`}>

      {/* Orion Eyes: Header */}
      <div className="flex-none w-full z-20 flex justify-center">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {/* Render logic: If no history, this takes 0 space. If history, it expands. */}
      {hasHistory && (
        <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden z-10 my-4 animate-[fadeIn_0.8s_ease-out]">
            <TerminalOutput messages={messages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-2">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

export enum OrionState {
  IDLE = 'IDLE', // Standard open state
  FOCUSED = 'FOCUSED', // Input active, user typing
  FOCUSED_EMPTY = 'FOCUSED_EMPTY', // Input active but empty (blinking)
  PROCESSING = 'PROCESSING', // Thinking
  ACTIVE = 'ACTIVE', // Speaking/Outputting
  PRE_SLEEP = 'PRE_SLEEP', // Transition: Rapid blinking before sleep
  LOOKING_AROUND = 'LOOKING_AROUND', // New: Idle animation, looking around
  SQUINTING = 'SQUINTING', // Transition: Eyes pressed/heavy
  SLEEPING = 'SLEEPING', // Fully closed
  AWAITING_PERMISSION = 'AWAITING_PERMISSION', // Waiting for user confirmation
  SYSTEM_ALERT = 'SYSTEM_ALERT', // Red alert for battery/resources
  SYSTEM_SUCCESS = 'SYSTEM_SUCCESS', // Green for positive events (Charging)
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
}

export interface LogEntry {
  timestamp: string;
  type: 'USER_INPUT' | 'SYSTEM_RESPONSE' | 'STATE_CHANGE' | 'SYSTEM_ERROR';
  data: any;
}

export interface PendingAction {
  description: string;
  originalResponse: string;
}

// Simulated System Notification
export interface SysNotification {
  id: string;
  title: string;
  details: string;
  timestamp: number;
  read: boolean;
}

export interface MemoryEntry {
  id: string;
  content: string;
  timestamp: number;
}

import { MemoryEntry } from '../types';

const MEMORY_KEY = 'ORION_LONG_TERM_MEMORY';

export const getMemory = (): MemoryEntry[] => {
  try {
    const stored = localStorage.getItem(MEMORY_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Falha ao ler memória:", e);
    return [];
  }
};

export const saveMemory = (content: string): boolean => {
  try {
    const currentMemory = getMemory();
    const newEntry: MemoryEntry = {
      id: Date.now().toString(),
      content: content.trim(),
      timestamp: Date.now()
    };

    // Simple deduplication based on exact content content
    if (!currentMemory.some(m => m.content === newEntry.content)) {
      const updatedMemory = [...currentMemory, newEntry];
      localStorage.setItem(MEMORY_KEY, JSON.stringify(updatedMemory));
      return true;
    }
    return false;
  } catch (e) {
    console.error("Falha ao gravar memória:", e);
    return false;
  }
};

export const clearMemory = () => {
  localStorage.removeItem(MEMORY_KEY);
};

export const getMemoryContextString = (): string => {
  const memories = getMemory();
  if (memories.length === 0) return "BANCO DE DADOS: Vazio.";

  return `BANCO DE DADOS (MEMÓRIA PERSISTENTE):\n${memories.map(m => `- ${m.content}`).join('\n')}`;
};

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message, SysNotification } from "../types";
import { getMemoryContextString } from "./memoryService";

// Initialize the client strictly with process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Mock function to get battery (safe wrapper)
const getBatteryInfo = async () => {
  try {
    // @ts-ignore - navigator.getBattery is not standard in all TS lib definitions yet
    if (navigator.getBattery) {
      // @ts-ignore
      const battery = await navigator.getBattery();
      return `${Math.round(battery.level * 100)}%${battery.charging ? ' (Carregando)' : ''}`;
    }
  } catch (e) {
    return "Indisponível (Sensor restrito)";
  }
  return "Alimentação AC / Desconhecido";
};

// Function to gather "System Senses"
const getSystemContext = async (activeNotifications: SysNotification[]): Promise<string> => {
  const now = new Date();
  const nav = window.navigator;
  const battery = await getBatteryInfo();
  const memoryContext = getMemoryContextString();

  // Filter unread notifications to "feed" to Orion's subconscious
  const unread = activeNotifications.filter(n => !n.read);
  const notificationContext = unread.length > 0 
    ? `ALERTA SENSORIAL: Você detecta ${unread.length} notificações pendentes no sistema: ${unread.map(n => `[${n.title}]`).join(', ')}. (Lembre-se: Só mencione se perguntado).` 
    : "SENSORIAL: Nenhuma notificação pendente.";

  return `
[DADOS DE TELEMETRIA EM TEMPO REAL]
HORA: ${now.toLocaleTimeString()}
DATA: ${now.toLocaleDateString()}
ENERGIA: ${battery}
CONEXÃO: ${nav.onLine ? "Estável (Online)" : "Instável (Offline)"}
PLATAFORMA: ${nav.platform}
${notificationContext}

${memoryContext}
`;
};

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  notifications: SysNotification[],
  imagePart?: string 
): Promise<string> => {
  try {
    // Inject system context into the very first message or as a system prelude
    const systemContextString = await getSystemContext(notifications);

    // Filter history, but ONLY keep the last 10 messages (short-term memory)
    // + ensures we keep the most relevant context without bloating
    const recentHistory = history.slice(-10);

    // Convert app history to GenAI Content format
    let contents: Content[] = recentHistory
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    if (contents.length > 0 && contents[0].role === 'model') {
       contents.shift();
    }

    const finalUserMessageText = `
${systemContextString}

INPUT DO USUÁRIO:
${userMessage}
`;

    const newParts: Part[] = [];

    if (imagePart) {
      newParts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: imagePart,
        },
      });
    }

    newParts.push({ text: finalUserMessageText });

    contents.push({
      role: 'user',
      parts: newParts,
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7, 
        maxOutputTokens: 1000, 
      },
    });

    if (response.text) {
      return response.text;
    }

    return "Conexão neural instável. Dados perdidos."; 
  } catch (error) {
    console.error("Orion System Error:", error);
    return "Erro crítico nos subsistemas de linguagem."; 
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Start silent. Orion is a presence, not a greeter.
  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Helper: Trigger System Event Message ---
  // Replaces generic alert, now allows handling Success (Green) or Alert (Red)
  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    // Stop any sleep/startup sequences immediately
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    // 1. Entry Animation: Set to Event Type (Alert/Success)
    setOrionState(eventType);

    // 2. Add System Message
    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', // Orion speaking autonomously
      content: content,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, alertMsg]);

    // 3. Exit Animation: Return to IDLE after brief period
    setTimeout(() => {
      // Only reset if user hasn't started typing in the meantime
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        // Restart sleep timer logic as if interaction just ended
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Battery Monitoring Logic ---
  useEffect(() => {
    let battery: any = null;

    const handleChargingChange = () => {
      if (battery) {
        if (battery.charging) {
           const msg = `:: Alimentação externa conectada. Carregando bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_SUCCESS);
        } else {
           const msg = `:: Alimentação desconectada. Operando em bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_ALERT);
        }
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        // We could also listen to 'levelchange' but that might be too spammy.
        // Let's only alert on level change if it's critical.
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemEvent(`:: ALERTA DE ENERGIA: Nível de bateria crítico (${Math.round(battery.level * 100)}%). Recomendo conexão imediata.`, OrionState.SYSTEM_ALERT);
          }
        });
      }
    };

    initBattery();

    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence Logic ---
  useEffect(() => {
    // Initial Startup: Blink (IDLE) for 6s -> Look Around -> Close
    setOrionState(OrionState.IDLE);

    // Clear any previous startup timers if component remounts
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      // Check if user has already interacted
      if (stateRef.current === OrionState.FOCUSED || 
          stateRef.current === OrionState.FOCUSED_EMPTY || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;

      setOrionState(OrionState.LOOKING_AROUND);

      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.FOCUSED || 
            stateRef.current === OrionState.FOCUSED_EMPTY || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;

        setOrionState(OrionState.SQUINTING);

        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current === OrionState.FOCUSED || 
              stateRef.current === OrionState.FOCUSED_EMPTY || 
              stateRef.current === OrionState.PROCESSING ||
              stateRef.current === OrionState.SYSTEM_ALERT ||
              stateRef.current === OrionState.SYSTEM_SUCCESS) return;

          setOrionState(OrionState.SLEEPING);
        }, 2500); // Duration of squinting before full sleep

      }, 4000); // Duration of looking around

    }, 6000); // Initial blink duration

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []);

  // --- Critical Resource Simulation Logic ---
  useEffect(() => {
    // Every 60 seconds, small chance to generate a CRITICAL alert or passive notification
    const interval = setInterval(() => {
      const rand = Math.random();

      // 5% chance of Critical Alert (Interruption)
      if (rand > 0.95) {
         const criticalEvents = [
            ":: ALERTA DE RECURSOS: Consumo de memória excedeu 85% em processos de segundo plano.",
            ":: ALERTA TÉRMICO: Detectada elevação de temperatura na CPU. Reduzindo ciclos não essenciais.",
            ":: SISTEMA: Instabilidade detectada no driver de vídeo. Reinicialização de interface gráfica pode ser necessária."
         ];
         const event = criticalEvents[Math.floor(Math.random() * criticalEvents.length)];
         triggerSystemEvent(event, OrionState.SYSTEM_ALERT);
      } 
      // 20% chance of Passive Notification (Sensor log)
      else if (rand > 0.75) { 
        const possibleEvents = [
          { title: "Uso de CPU Elevado", details: "Processo 'Chrome' consumindo 85%" },
          { title: "Atualização de Segurança", details: "Patch v2.4 pendente" },
          { title: "Rede Instável", details: "Latência acima de 200ms" },
          { title: "Bateria Otimizada", details: "Modo de economia ativado" }
        ];
        const event = possibleEvents[Math.floor(Math.random() * possibleEvents.length)];

        const newNotif: SysNotification = {
          id: Date.now().toString(),
          title: event.title,
          details: event.details,
          timestamp: Date.now(),
          read: false
        };

        setNotifications(prev => [...prev, newNotif]);
        console.log("[ORION SENSORS] Passive event logged:", event.title);
      }
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    // Check current state via ref to ensure we don't interrupt critical states
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, []);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    // Critical: Cancel startup sequence if user interacts immediately
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || 
        orionState === OrionState.SYSTEM_ALERT || 
        orionState === OrionState.SYSTEM_SUCCESS) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;

    // 1. Check for Permission Request Tag: [[REQUEST_PERMISSION: action]]
    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);

    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });
      // Return early because state will change to AWAITING_PERMISSION in main flow
      return cleanText;
    }

    // 2. Check for Memory Write Tag: [[MEMORY_WRITE: content]]
    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/;
    const memMatch = cleanText.match(memoryRegex);

    if (memMatch) {
      const contentToSave = memMatch[1];
      cleanText = cleanText.replace(memoryRegex, '').trim();

      const success = saveMemory(contentToSave);
      if (success) {
        // Trigger visual success cue (Green eyes) but don't add a text message
        setOrionState(OrionState.SYSTEM_SUCCESS);
        setTimeout(() => {
           if (stateRef.current === OrionState.SYSTEM_SUCCESS) {
              setOrionState(OrionState.IDLE);
           }
        }, 2000);
      }
    }

    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();

    // Clear startup timer just in case
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    // Mark notifications as read if the user is asking about them
    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      // Pass notifications context
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      // Determine next state
      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         // If we just triggered a memory save (green state), don't override it immediately with ACTIVE
         if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
            setOrionState(OrionState.ACTIVE);
            setTimeout(() => {
                // Use ref to check for race conditions
                if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                    stateRef.current !== OrionState.SYSTEM_ALERT &&
                    stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                    setOrionState(OrionState.IDLE);
                }
            }, 1500);
         }
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    // Reset UI
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    // Add decision to history automatically
    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    // Send back to Orion
    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);

       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                setOrionState(OrionState.ACTIVE);
                setTimeout(() => {
                    if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                        stateRef.current !== OrionState.SYSTEM_ALERT &&
                        stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                        setOrionState(OrionState.IDLE);
                    }
                }, 1500);
           }
       }
    });
  };

  const hasHistory = messages.length > 0;

  return (
    <div className={`min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out ${hasHistory ? 'justify-between py-6' : 'justify-center gap-16'}`}>

      {/* Orion Eyes: Header */}
      <div className="flex-none w-full z-20 flex justify-center">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {/* Render logic: If no history, this takes 0 space. If history, it expands. */}
      {hasHistory && (
        <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden z-10 my-4 animate-[fadeIn_0.8s_ease-out]">
            <TerminalOutput messages={messages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-2">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

