  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onInputSubmit();
    }
  };

  return (
      <div className="w-full max-w-2xl flex flex-col items-center justify-center relative group min-h-[60px] px-4">
