        {state === OrionState.AWAITING_PERMISSION && pendingAction ? (
           <div className="flex flex-col items-center w-full animate-[fadeIn_0.3s_ease-out]">
              <div className="text-amber-500 font-mono text-xs tracking-widest mb-4 uppercase text-center max-w-xs">
                 Permissão Requerida: {pendingAction.description}
              </div>
              <div className="flex gap-4">
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(false)}
                   className="px-6 py-2 border border-red-900/50 text-red-500/80 hover:bg-red-900/20 hover:text-red-400 font-mono text-xs tracking-wider transition-all rounded"
                 >
                    NEGAR
                 </button>
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(true)}
                   className="px-6 py-2 bg-amber-600/10 border border-amber-600/50 text-amber-500 hover:bg-amber-600/20 hover:text-amber-400 font-mono text-xs tracking-wider transition-all rounded shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                 >
                    AUTORIZAR
                 </button>
              </div>
           </div>
        ) : (
          <>
            <input
              ref={inputRef}
              type="text"
              value={inputValue}
              onChange={(e) => onInputChange(e.target.value)}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              onKeyDown={handleKeyDown}
              disabled={state === OrionState.PROCESSING}
              className="absolute inset-0 w-full h-full opacity-0 cursor-text z-10"
            />

            <div 
              className={`
                h-[2px] transition-all duration-700 ease-in-out relative
                ${state === OrionState.SLEEPING ? 'w-16 opacity-20 bg-zinc-700' : 'w-24 opacity-60 bg-zinc-600'}
                ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? '!w-full max-w-[600px] !opacity-100 !bg-zinc-400 shadow-[0_0_10px_rgba(255,255,255,0.2)]' : ''}
                ${state === OrionState.PROCESSING ? 'w-12 opacity-50 bg-white animate-pulse' : ''}
                ${state === OrionState.SYSTEM_ALERT ? 'w-full max-w-[200px] bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : ''}
                ${state === OrionState.SYSTEM_SUCCESS ? 'w-full max-w-[200px] bg-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.5)]' : ''}
              `}
            />

            <div className={`
              mt-4 h-6 font-mono text-xs tracking-widest text-zinc-500 transition-opacity duration-300
              ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0'}
            `}>
              {inputValue}
              <span className="animate-cursor-blink">_</span>
            </div>
          </>
        )}
      </div>
  );
};

export default OrionInput;

import { MemoryEntry, Message } from '../types';

const MEMORY_KEY = 'ORION_LONG_TERM_MEMORY';
const HISTORY_KEY = 'ORION_CHAT_HISTORY';

// --- Long Term Memory (Facts) ---

export const getMemory = (): MemoryEntry[] => {
  try {
    const stored = localStorage.getItem(MEMORY_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Falha ao ler memória:", e);
    return [];
  }
};

export const saveMemory = (content: string): boolean => {
  try {
    const currentMemory = getMemory();
    const newEntry: MemoryEntry = {
      id: Date.now().toString(),
      content: content.trim(),
      timestamp: Date.now()
    };

    // Simple deduplication based on exact content content
    if (!currentMemory.some(m => m.content === newEntry.content)) {
      const updatedMemory = [...currentMemory, newEntry];
      localStorage.setItem(MEMORY_KEY, JSON.stringify(updatedMemory));
      return true;
    }
    return false;
  } catch (e) {
    console.error("Falha ao gravar memória:", e);
    return false;
  }
};

export const clearMemory = () => {
  localStorage.removeItem(MEMORY_KEY);
};

export const getMemoryContextString = (): string => {
  const memories = getMemory();
  if (memories.length === 0) return "BANCO DE DADOS: Vazio.";

  return `BANCO DE DADOS (MEMÓRIA PERSISTENTE):\n${memories.map(m => `- ${m.content}`).join('\n')}`;
};

// --- Session History (Context Preservation) ---

export const getHistory = (): Message[] => {
  try {
    const stored = localStorage.getItem(HISTORY_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Falha ao ler histórico:", e);
    return [];
  }
};

export const saveHistory = (messages: Message[]) => {
  try {
    // Limit to last 50 messages to prevent storage overflow over time
    const historyToSave = messages.slice(-50);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(historyToSave));
  } catch (e) {
    console.error("Falha ao salvar histórico:", e);
  }
};

export const clearHistory = () => {
  localStorage.removeItem(HISTORY_KEY);
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Initialize messages from local storage if available
  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Persistence Logic ---
  // Load history on mount
  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(savedMessages);
    }
  }, []);

  // Save history whenever messages change
  useEffect(() => {
    if (messages.length > 0) {
      saveHistory(messages);
    }
  }, [messages]);


  // --- Helper: Trigger System Event Message ---
  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    // Stop any sleep/startup sequences immediately
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    setOrionState(eventType);

    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', 
      content: content,
      timestamp: Date.now(),
    };

    // Add to messages (which triggers saveHistory)
    setMessages(prev => [...prev, alertMsg]);

    setTimeout(() => {
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Battery Monitoring Logic ---
  useEffect(() => {
    let battery: any = null;

    const handleChargingChange = () => {
      if (battery) {
        if (battery.charging) {
           const msg = `:: Alimentação externa conectada. Carregando bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_SUCCESS);
        } else {
           const msg = `:: Alimentação desconectada. Operando em bateria (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_ALERT);
        }
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemEvent(`:: ALERTA DE ENERGIA: Nível de bateria crítico (${Math.round(battery.level * 100)}%). Recomendo conexão imediata.`, OrionState.SYSTEM_ALERT);
          }
        });
      }
    };

    initBattery();

    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence Logic ---
  useEffect(() => {
    // Only run startup sequence if we have no messages (fresh start)
    // If we reloaded and have history, stay IDLE
    if (messages.length > 0) {
      setOrionState(OrionState.IDLE);
      return;
    }

    setOrionState(OrionState.IDLE);
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      if (stateRef.current !== OrionState.IDLE) return;

      setOrionState(OrionState.LOOKING_AROUND);

      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current !== OrionState.LOOKING_AROUND) return;

        setOrionState(OrionState.SQUINTING);

        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current !== OrionState.SQUINTING) return;
          setOrionState(OrionState.SLEEPING);
        }, 2500); 

      }, 4000); 
    }, 6000); 

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []); // Run once on mount (but logical check prevents re-run if history exists)


  // --- Real & Simulated System Monitoring Logic ---
  useEffect(() => {
    const checkResources = async () => {
      // 1. Check Storage (Real)
      if (navigator.storage && navigator.storage.estimate) {
        try {
          const { usage, quota } = await navigator.storage.estimate();
          if (usage && quota) {
            const percentage = (usage / quota) * 100;
            // High threshold just for demo, usually this is very low on empty apps
            if (percentage > 80) {
              triggerSystemEvent(`:: ALERTA DE ARMAZENAMENTO: Uso local crítico (${percentage.toFixed(1)}%). Limpeza recomendada.`, OrionState.SYSTEM_ALERT);
              return; 
            }
          }
        } catch (e) {
          // Silent fail
        }
      }

      // 2. Check Memory (Chrome specific - Real)
      // @ts-ignore
      if (performance && performance.memory) {
        // @ts-ignore
        const { usedJSHeapSize, jsHeapSizeLimit } = performance.memory;
        const memPercentage = (usedJSHeapSize / jsHeapSizeLimit) * 100;

        if (memPercentage > 85) {
           triggerSystemEvent(`:: ALERTA DE MEMÓRIA: Heap JS excedeu limites operacionais (${memPercentage.toFixed(1)}%). Risco de travamento.`, OrionState.SYSTEM_ALERT);
           return;
        }
      }

      // 3. Simulation (Fallback for "System Presence")
      // Only simulate if no real events triggered and random chance met
      const rand = Math.random();

      // Very rare CPU spike simulation (1% chance every minute)
      if (rand > 0.99) {
         triggerSystemEvent(":: ALERTA DE CPU: Pico de processamento em thread principal. Estabilizando...", OrionState.SYSTEM_ALERT);
      } 
      // Passive logging (Background noise)
      else if (rand > 0.85) { 
        const logEvents = [
          { title: "Garbage Collection", details: "Ciclo de limpeza de memória executado" },
          { title: "Sincronização", details: "Cache local atualizado" },
          { title: "Monitoramento", details: "Verificação de integridade concluída" }
        ];
        const event = logEvents[Math.floor(Math.random() * logEvents.length)];
        // Just log to console or passive notification state, don't interrupt user
        console.log(`[ORION SYSTEM]: ${event.title} - ${event.details}`);
      }
    };

    // Check every 30 seconds
    const interval = setInterval(checkResources, 30000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, []);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || 
        orionState === OrionState.SYSTEM_ALERT || 
        orionState === OrionState.SYSTEM_SUCCESS) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;

    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);

    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });
      return cleanText;
    }

    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/;
    const memMatch = cleanText.match(memoryRegex);

    if (memMatch) {
      const contentToSave = memMatch[1];
      cleanText = cleanText.replace(memoryRegex, '').trim();

      const success = saveMemory(contentToSave);
      if (success) {
        setOrionState(OrionState.SYSTEM_SUCCESS);
        setTimeout(() => {
           if (stateRef.current === OrionState.SYSTEM_SUCCESS) {
              setOrionState(OrionState.IDLE);
           }
        }, 2000);
      }
    }

    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();

    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
            setOrionState(OrionState.ACTIVE);
            setTimeout(() => {
                if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                    stateRef.current !== OrionState.SYSTEM_ALERT &&
                    stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                    setOrionState(OrionState.IDLE);
                }
            }, 1500);
         }
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);

       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                setOrionState(OrionState.ACTIVE);
                setTimeout(() => {
                    if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                        stateRef.current !== OrionState.SYSTEM_ALERT &&
                        stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                        setOrionState(OrionState.IDLE);
                    }
                }, 1500);
           }
       }
    });
  };

  const hasHistory = messages.length > 0;

  return (
    <div className={`min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out ${hasHistory ? 'justify-between py-6' : 'justify-center gap-16'}`}>

      {/* Orion Eyes: Header */}
      <div className="flex-none w-full z-20 flex justify-center">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {hasHistory && (
        <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden z-10 my-4 animate-[fadeIn_0.8s_ease-out]">
            <TerminalOutput messages={messages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-2">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

