import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Initialize messages from local storage if available
  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Persistence Logic ---
  // Load history on mount
  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(savedMessages);
    }
  }, []);

  // Save history whenever messages change
  useEffect(() => {
    if (messages.length > 0) {
      saveHistory(messages);
    }
  }, [messages]);


  // --- Helper: Trigger System Event Message ---
  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    // Stop any sleep/startup sequences immediately
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    setOrionState(eventType);

    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', 
      content: content,
      timestamp: Date.now(),
    };

    // Add to messages (which triggers saveHistory)
    setMessages(prev => [...prev, alertMsg]);

    setTimeout(() => {
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Network Monitoring Logic ---
  useEffect(() => {
    const handleOnline = () => {
      triggerSystemEvent(":: CONEXÃO RESTABELECIDA. SINCRONIZANDO...", OrionState.SYSTEM_SUCCESS);
    };

    const handleOffline = () => {
      triggerSystemEvent(":: ALERTA DE REDE: CONEXÃO PERDIDA. OPERANDO OFFLINE.", OrionState.SYSTEM_ALERT);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- Battery Monitoring Logic ---
  useEffect(() => {
    let battery: any = null;

    const handleChargingChange = () => {
      if (battery) {
        if (battery.charging) {
           const msg = `:: ALIMENTAÇÃO EXTERNA CONECTADA. CARREGANDO (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_SUCCESS);
        } else {
           const msg = `:: ALIMENTAÇÃO DESCONECTADA. OPERANDO EM BATERIA (${Math.round(battery.level * 100)}%).`;
           triggerSystemEvent(msg, OrionState.SYSTEM_ALERT);
        }
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemEvent(`:: ALERTA DE ENERGIA: NÍVEL CRÍTICO (${Math.round(battery.level * 100)}%).`, OrionState.SYSTEM_ALERT);
          }
        });
      }
    };

    initBattery();

    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence Logic ---
  useEffect(() => {
    // Only run startup sequence if we have no messages (fresh start)
    // If we reloaded and have history, stay IDLE
    if (messages.length > 0) {
      setOrionState(OrionState.IDLE);
      return;
    }

    setOrionState(OrionState.IDLE);
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      if (stateRef.current !== OrionState.IDLE) return;

      setOrionState(OrionState.LOOKING_AROUND);

      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current !== OrionState.LOOKING_AROUND) return;

        setOrionState(OrionState.SQUINTING);

        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current !== OrionState.SQUINTING) return;
          setOrionState(OrionState.SLEEPING);
        }, 2500); 

      }, 4000); 
    }, 6000); 

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []); 


  // --- Real & Simulated System Monitoring Logic ---
  useEffect(() => {
    const checkResources = async () => {
      // 1. Check Storage (Real)
      if (navigator.storage && navigator.storage.estimate) {
        try {
          const { usage, quota } = await navigator.storage.estimate();
          if (usage && quota) {
            const percentage = (usage / quota) * 100;
            // High threshold just for demo
            if (percentage > 80) {
              triggerSystemEvent(`:: ALERTA DE ARMAZENAMENTO: USO CRÍTICO (${percentage.toFixed(1)}%).`, OrionState.SYSTEM_ALERT);
              return; 
            }
          }
        } catch (e) {
          // Silent fail
        }
      }

      // 2. Check Memory (Chrome specific - Real)
      // @ts-ignore
      if (performance && performance.memory) {
        // @ts-ignore
        const { usedJSHeapSize, jsHeapSizeLimit } = performance.memory;
        const memPercentage = (usedJSHeapSize / jsHeapSizeLimit) * 100;

        if (memPercentage > 85) {
           triggerSystemEvent(`:: ALERTA DE MEMÓRIA: HEAP JS EXCEDIDO (${memPercentage.toFixed(1)}%).`, OrionState.SYSTEM_ALERT);
           return;
        }
      }

      // 3. Notification Simulation (Background Events)
      // Small chance to generate a system notification
      if (Math.random() > 0.95) {
         const notifTypes = [
             { title: "UPDATE_READY", desc: "Patch de segurança 2.4.1 disponível." },
             { title: "SECURITY_SCAN", desc: "Varredura completa. Nenhuma ameaça." },
             { title: "SYNC_COMPLETE", desc: "Dados locais sincronizados com sucesso." },
             { title: "EXT_DEVICE", desc: "Dispositivo desconhecido detectado na porta lógica 3." }
         ];
         const selected = notifTypes[Math.floor(Math.random() * notifTypes.length)];

         const newNotif: SysNotification = {
             id: Date.now().toString(),
             title: selected.title,
             details: selected.desc,
             timestamp: Date.now(),
             read: false
         };

         setNotifications(prev => [...prev, newNotif]);

         // Discreetly inform user via a system log message (not a full alert)
         setMessages(prev => [...prev, {
             id: Date.now().toString(),
             role: 'system',
             content: `> NOTIFICAÇÃO DE SISTEMA: ${selected.title}`,
             timestamp: Date.now()
         }]);
      }

      // 4. CPU Simulation (Fallback)
      const rand = Math.random();
      if (rand > 0.99) {
         triggerSystemEvent(":: ALERTA DE CPU: PICO DE PROCESSAMENTO. ESTABILIZANDO...", OrionState.SYSTEM_ALERT);
      } 
    };

    // Check every 30 seconds
    const interval = setInterval(checkResources, 30000);

    return () => clearInterval(interval);
  }, []);

  // --- State Management Logic ---
  const startSleepSequence = useCallback(() => {
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, []);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || 
        orionState === OrionState.SYSTEM_ALERT || 
        orionState === OrionState.SYSTEM_SUCCESS) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;

    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);

    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();

      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });
      return cleanText;
    }

    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/;
    const memMatch = cleanText.match(memoryRegex);

    if (memMatch) {
      const contentToSave = memMatch[1];
      cleanText = cleanText.replace(memoryRegex, '').trim();

      const success = saveMemory(contentToSave);
      if (success) {
        setOrionState(OrionState.SYSTEM_SUCCESS);
        setTimeout(() => {
           if (stateRef.current === OrionState.SYSTEM_SUCCESS) {
              setOrionState(OrionState.IDLE);
           }
        }, 2000);
      }
    }

    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();

    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
            setOrionState(OrionState.ACTIVE);
            setTimeout(() => {
                if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                    stateRef.current !== OrionState.SYSTEM_ALERT &&
                    stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                    setOrionState(OrionState.IDLE);
                }
            }, 1500);
         }
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user', // Treat decision as user input in history
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);

       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                setOrionState(OrionState.ACTIVE);
                setTimeout(() => {
                    if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                        stateRef.current !== OrionState.SYSTEM_ALERT &&
                        stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                        setOrionState(OrionState.IDLE);
                    }
                }, 1500);
           }
       }
    });
  };

  const hasHistory = messages.length > 0;

  return (
    <div className={`min-h-screen bg-[#050505] text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out ${hasHistory ? 'justify-between py-6' : 'justify-center gap-16'}`}>

      {/* Orion Eyes: Header */}
      <div className="flex-none w-full z-20 flex justify-center">
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {hasHistory && (
        <div className="flex-1 w-full flex flex-col items-center justify-start overflow-hidden z-10 my-4 animate-[fadeIn_0.8s_ease-out]">
            <TerminalOutput messages={messages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-2">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
        />
      </div>

      {/* Background Noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';

interface TerminalOutputProps {
  messages: Message[];
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ messages }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  if (messages.length === 0) return null;

  return (
    <div className="flex-1 w-full max-w-2xl overflow-y-auto px-6 py-4 space-y-6 mask-image-linear-gradient">
      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex flex-col ${msg.role === 'user' ? 'items-end' : msg.role === 'system' ? 'items-center my-2' : 'items-start'} opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]`}
          style={{ animationFillMode: 'forwards' }}
        >
          <div 
            className={`max-w-[85%] font-mono text-sm leading-relaxed ${
              msg.role === 'user' 
                ? 'text-zinc-500 text-right' 
                : msg.role === 'system'
                ? 'text-emerald-500/50 text-[10px] uppercase tracking-[0.2em] select-none'
                : 'text-zinc-300 text-left'
            }`}
          >
             {msg.role === 'model' && <span className="mr-2 text-zinc-600 select-none">::</span>}
             {msg.content}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default TerminalOutput;

export enum OrionState {
  IDLE = 'IDLE', // Standard open state
  FOCUSED = 'FOCUSED', // Input active, user typing
  FOCUSED_EMPTY = 'FOCUSED_EMPTY', // Input active but empty (blinking)
  PROCESSING = 'PROCESSING', // Thinking
  ACTIVE = 'ACTIVE', // Speaking/Outputting
  PRE_SLEEP = 'PRE_SLEEP', // Transition: Rapid blinking before sleep
  LOOKING_AROUND = 'LOOKING_AROUND', // New: Idle animation, looking around
  SQUINTING = 'SQUINTING', // Transition: Eyes pressed/heavy
  SLEEPING = 'SLEEPING', // Fully closed
  OBSERVING = 'OBSERVING', // New: Deep Dive mode, scaling up and looking around from background
  AWAITING_PERMISSION = 'AWAITING_PERMISSION', // Waiting for user confirmation
  SYSTEM_ALERT = 'SYSTEM_ALERT', // Red alert for battery/resources
  SYSTEM_SUCCESS = 'SYSTEM_SUCCESS', // Green for positive events (Charging)
}

export interface Message {
  id: string;
  role: 'user' | 'system' | 'model';
  content: string;
  timestamp: number;
  isHidden?: boolean; // For filtering notifications
}

export interface LogEntry {
  timestamp: string;
  type: 'USER_INPUT' | 'SYSTEM_RESPONSE' | 'STATE_CHANGE' | 'SYSTEM_ERROR';
  data: any;
}

export interface PendingAction {
  description: string;
  originalResponse: string;
}

// Simulated System Notification
export interface SysNotification {
  id: string;
  title: string;
  details: string;
  timestamp: number;
  read: boolean;
}

export interface MemoryEntry {
  id: string;
  content: string;
  timestamp: number;
}

import React, { useEffect, useState } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      // Don't organic blink during specific animation states
      if (
        state === OrionState.SLEEPING || 
        state === OrionState.SQUINTING || 
        state === OrionState.PROCESSING || 
        state === OrionState.AWAITING_PERMISSION ||
        state === OrionState.SYSTEM_ALERT ||
        state === OrionState.SYSTEM_SUCCESS ||
        state === OrionState.OBSERVING
      ) return;

      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      let nextBlink = 4000;

      if (state === OrionState.PRE_SLEEP) {
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 1000);

    return () => clearTimeout(timeoutId);
  }, [state]);

  // Calculate styles based on state
  const getEyeStyles = () => {
    // Base eye style
    let baseStyle = "transition-all ease-in-out relative";
    let bgClass = "bg-white"; // Default white eyes

    // Change eye color for specific states
    if (state === OrionState.AWAITING_PERMISSION) {
      bgClass = "bg-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.6)]";
    } else if (state === OrionState.SYSTEM_ALERT) {
      bgClass = "bg-red-500 shadow-[0_0_60px_rgba(239,68,68,0.8)]";
    } else if (state === OrionState.SYSTEM_SUCCESS) {
      bgClass = "bg-emerald-500 shadow-[0_0_60px_rgba(16,185,129,0.8)]";
    }

    const eyeBase = `${baseStyle} ${bgClass}`;

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-8", 
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_40px_rgba(255,255,255,0.9)] animate-jump-spin`,
        };
      case OrionState.AWAITING_PERMISSION:
        return {
          container: "gap-8",
          eye: `${eyeBase} w-24 h-24 rounded-lg animate-pulse-slow`,
        };
      case OrionState.SYSTEM_ALERT:
        return {
          container: "gap-12",
          eye: `${eyeBase} w-20 h-20 rounded-md animate-ping-slow opacity-90`,
        };
      case OrionState.SYSTEM_SUCCESS:
        return {
          container: "gap-8",
          eye: `${eyeBase} w-20 h-20 rounded-xl animate-pulse-slow opacity-90`,
        };
      case OrionState.LOOKING_AROUND:
        return {
          container: "gap-5 animate-look-around",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)]`,
        };
      case OrionState.OBSERVING:
        // Background Deep Dive Mode
        return {
          container: "gap-16 animate-approach-search opacity-40",
          eye: `${eyeBase} w-32 h-32 rounded-[2rem] shadow-[0_0_80px_rgba(255,255,255,0.15)]`,
        };
      case OrionState.ACTIVE: 
        return {
          container: "gap-5",
          eye: `${eyeBase} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: 
        return {
          container: "gap-6",
          eye: `${eyeBase} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[2500ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4",
          eye: `${eyeBase} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: 
        return {
           container: "gap-5",
           eye: `${eyeBase} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5",
          eye: `${eyeBase} w-20 h-20 rounded-2xl shadow-[0_0_20px_rgba(255,255,255,0.4)] duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  const blinkClass = isBlinking ? '!h-1 !opacity-50 duration-200' : '';

  return (
    <div className={`flex flex-col items-center justify-center w-full select-none transition-all duration-1000 ${state === OrionState.OBSERVING ? 'h-full scale-125' : 'pt-4 pb-4'}`}>
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-15px) rotate(180deg) scale(1.05); } 
          40% { transform: translateY(-5px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-2px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        @keyframes look-around {
          0% { transform: translateX(0); }
          10% { transform: translateX(-20px); } 
          30% { transform: translateX(-20px); }
          45% { transform: translateX(20px); }
          65% { transform: translateX(20px); }
          80% { transform: translateX(0); }
          100% { transform: translateX(0); }
        }
        @keyframes approach-search {
          0% { transform: scale(0.9) translateX(0); opacity: 0; }
          20% { transform: scale(1.0) translateX(-40px); opacity: 0.2; }
          50% { transform: scale(1.1) translateX(40px); opacity: 0.4; }
          80% { transform: scale(1.2) translateX(-20px); opacity: 0.3; }
          100% { transform: scale(1.25) translateX(0); opacity: 0.4; }
        }
        @keyframes ping-slow {
          0% { transform: scale(1); opacity: 0.9; }
          50% { transform: scale(1.1); opacity: 1; }
          100% { transform: scale(1); opacity: 0.9; }
        }
        .animate-jump-spin {
          animation: jump-spin 2s ease-in-out infinite;
        }
        .animate-look-around {
          animation: look-around 4s ease-in-out infinite;
        }
        .animate-approach-search {
          animation: approach-search 8s ease-in-out infinite alternate;
        }
        .animate-pulse-slow {
           animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        .animate-ping-slow {
           animation: ping-slow 2s cubic-bezier(0, 0, 0.2, 1) infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkClass}`} />
        <div className={`${styles.eye} ${blinkClass}`} />
      </div>
    </div>
  );
};

export default OrionEyes;

