  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
  onToggleFilter?: () => void;
  isFilterActive?: boolean;
}

const OrionInput: React.FC<OrionInputProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide,
  onToggleFilter,
  isFilterActive
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

