              onChange={(e) => onInputChange(e.target.value)}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              onKeyDown={handleKeyDown}
              disabled={state === OrionState.PROCESSING}
              className="absolute inset-0 w-full h-full opacity-0 cursor-text z-20"
              autoComplete="off"
            />

            {/* Linha de status/input */}
            <div 
              className={`
                h-[1px] transition-all duration-700 ease-in-out relative
                ${state === OrionState.SLEEPING ? 'w-16 opacity-20 bg-zinc-400 dark:bg-zinc-700' : 'w-24 opacity-60 bg-zinc-500 dark:bg-zinc-600'}
                ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? '!w-full max-w-[600px] !opacity-100 !bg-zinc-800 dark:!bg-zinc-400 shadow-[0_0_10px_rgba(0,0,0,0.1)] dark:shadow-[0_0_10px_rgba(255,255,255,0.15)]' : ''}
                ${state === OrionState.PROCESSING ? 'w-12 opacity-50 bg-zinc-900 dark:bg-white animate-pulse' : ''}
                ${state === OrionState.SYSTEM_ALERT ? 'w-full max-w-[200px] bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : ''}
              `}
            />

            <div className="flex items-center justify-between w-full max-w-[600px] mt-4 relative">
                {/* Texto Input com cursor personalizado */}
                <div className={`
                  font-mono text-sm tracking-widest text-zinc-800 dark:text-zinc-300 transition-opacity duration-300 flex-1 overflow-hidden
                  ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0'}
                `}>
                  <span className="text-zinc-400 dark:text-zinc-600 mr-2">{'>'}</span>
                  {inputValue}
                  <span className="animate-cursor-terminal inline-block w-2.5 h-4 bg-zinc-800 dark:bg-zinc-400 align-middle ml-0.5"></span>
                </div>

                {/* Botão de Filtro Discreto */}
                <button 
                  onClick={onToggleFilter}
                  className={`
                    ml-4 p-1 rounded transition-all duration-300 z-30
                    ${isFilterActive ? 'text-zinc-600 dark:text-zinc-400 bg-zinc-200 dark:bg-zinc-800/50' : 'text-zinc-400 dark:text-zinc-700 hover:text-zinc-600 dark:hover:text-zinc-500'}
                    ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'opacity-100' : 'opacity-0 pointer-events-none'}
                  `}
                  title="Filtrar Notificações de Sistema"
                >
                   <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                     <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
                   </svg>
                </button>
            </div>
          </>
        )}
      </div>
  );
};

export default OrionInput;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);

  // Initialize messages from local storage if available
  const [messages, setMessages] = useState<Message[]>([]);
  const [filterSystemLogs, setFilterSystemLogs] = useState(false);

  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);

  // Simulated System Notifications
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  // State timers refs
  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Inactivity Logic
  const inactivityTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [isUserInactive, setIsUserInactive] = useState(false);

  // Ref to track state for async operations to avoid stale closures
  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // --- Persistence Logic ---
  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(savedMessages);
    }
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      saveHistory(messages);
    }
  }, [messages]);

  // --- Inactivity & Deep Dive Logic ---
  const isDeepDiveMode = messages.length > 4;

  const resetInactivity = useCallback(() => {
    setIsUserInactive(false);

    // If we were observing, wake up slightly but don't full reset if we are in deep dive
    if (stateRef.current === OrionState.OBSERVING) {
       setOrionState(OrionState.IDLE);
    }

    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);

    // Only set inactivity timer if we are in Deep Dive mode
    if (isDeepDiveMode) {
      inactivityTimer.current = setTimeout(() => {
        setIsUserInactive(true);
        // If not processing/typing, go to OBSERVING
        if (stateRef.current !== OrionState.PROCESSING && 
            stateRef.current !== OrionState.FOCUSED && 
            stateRef.current !== OrionState.FOCUSED_EMPTY) {
            setOrionState(OrionState.OBSERVING);
        }
      }, 5000); // 5 seconds of inactivity
    }
  }, [isDeepDiveMode]);

  useEffect(() => {
    // Attach listeners for inactivity reset
    window.addEventListener('mousemove', resetInactivity);
    window.addEventListener('keydown', resetInactivity);
    window.addEventListener('scroll', resetInactivity);

    resetInactivity(); // Start timer

    return () => {
      window.removeEventListener('mousemove', resetInactivity);
      window.removeEventListener('keydown', resetInactivity);
      window.removeEventListener('scroll', resetInactivity);
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    };
  }, [resetInactivity]);


  // --- Helper: Trigger System Event Message ---
  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    setOrionState(eventType);

    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', 
      content: content,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, alertMsg]);

    setTimeout(() => {
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        startSleepSequence();
      }
    }, 4000);
  };

  // --- Network Monitoring ---
  useEffect(() => {
    const handleOnline = () => triggerSystemEvent(":: CONEXÃO RESTABELECIDA. SINCRONIZANDO...", OrionState.SYSTEM_SUCCESS);
    const handleOffline = () => triggerSystemEvent(":: ALERTA DE REDE: CONEXÃO PERDIDA. OPERANDO OFFLINE.", OrionState.SYSTEM_ALERT);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- Battery Monitoring ---
  useEffect(() => {
    let battery: any = null;
    const handleChargingChange = () => {
      if (battery) {
        if (battery.charging) {
           triggerSystemEvent(`:: ALIMENTAÇÃO EXTERNA CONECTADA. CARREGANDO (${Math.round(battery.level * 100)}%).`, OrionState.SYSTEM_SUCCESS);
        } else {
           triggerSystemEvent(`:: ALIMENTAÇÃO DESCONECTADA. OPERANDO EM BATERIA (${Math.round(battery.level * 100)}%).`, OrionState.SYSTEM_ALERT);
        }
      }
    };

    const initBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        battery = await navigator.getBattery();
        battery.addEventListener('chargingchange', handleChargingChange);
        battery.addEventListener('levelchange', () => {
          if (battery.level <= 0.15 && !battery.charging) {
            triggerSystemEvent(`:: ALERTA DE ENERGIA: NÍVEL CRÍTICO (${Math.round(battery.level * 100)}%).`, OrionState.SYSTEM_ALERT);
          }
        });
      }
    };
    initBattery();
    return () => {
      if (battery) {
        battery.removeEventListener('chargingchange', handleChargingChange);
      }
    };
  }, []);

  // --- Startup Sequence ---
  useEffect(() => {
    if (messages.length > 0) {
      setOrionState(OrionState.IDLE);
      return;
    }

    setOrionState(OrionState.IDLE);
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    startupSequenceTimer.current = setTimeout(() => {
      if (stateRef.current !== OrionState.IDLE) return;
      setOrionState(OrionState.LOOKING_AROUND);
      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current !== OrionState.LOOKING_AROUND) return;
        setOrionState(OrionState.SQUINTING);
        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current !== OrionState.SQUINTING) return;
          setOrionState(OrionState.SLEEPING);
        }, 2500); 
      }, 4000); 
    }, 6000); 

    return () => {
      if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    };
  }, []); 

  // --- System Resource Simulation ---
  useEffect(() => {
    const checkResources = async () => {
      // Only run simulation if not deep in conversation to avoid annoying updates
      if (isDeepDiveMode && Math.random() > 0.3) return;

      if (navigator.storage && navigator.storage.estimate) {
        try {
          const { usage, quota } = await navigator.storage.estimate();
          if (usage && quota && (usage / quota) > 0.8) {
              triggerSystemEvent(`:: ALERTA DE ARMAZENAMENTO: USO CRÍTICO.`, OrionState.SYSTEM_ALERT);
              return; 
          }
        } catch (e) {}
      }

      // @ts-ignore
      if (performance && performance.memory) {
        // @ts-ignore
        const { usedJSHeapSize, jsHeapSizeLimit } = performance.memory;
        if ((usedJSHeapSize / jsHeapSizeLimit) > 0.85) {
           triggerSystemEvent(`:: ALERTA DE MEMÓRIA: HEAP JS EXCEDIDO.`, OrionState.SYSTEM_ALERT);
           return;
        }
      }

      // Notifications
      if (Math.random() > 0.95) {
         const notifTypes = [
             { title: "UPDATE_READY", desc: "Patch 2.4.1 disponível." },
             { title: "SECURITY_SCAN", desc: "Integridade confirmada." },
             { title: "SYNC_COMPLETE", desc: "Sincronização OK." },
             { title: "EXT_DEVICE", desc: "Porta 3: Dispositivo detectado." }
         ];
         const selected = notifTypes[Math.floor(Math.random() * notifTypes.length)];

         const newNotif: SysNotification = {
             id: Date.now().toString(),
             title: selected.title,
             details: selected.desc,
             timestamp: Date.now(),
             read: false
         };

         setNotifications(prev => [...prev, newNotif]);

         setMessages(prev => [...prev, {
             id: Date.now().toString(),
             role: 'system',
             content: `> SYS_NOTIF: ${selected.title}`,
             timestamp: Date.now(),
             isHidden: false // Can be filtered
         }]);
      }
    };

    const interval = setInterval(checkResources, 30000);
    return () => clearInterval(interval);
  }, [isDeepDiveMode]);

  // --- State Management ---
  const startSleepSequence = useCallback(() => {
    if (isDeepDiveMode) return; // Don't sleep normally in deep dive

    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;

    setOrionState(OrionState.PRE_SLEEP);

    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);

    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);

      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 

    }, 4000); 
  }, [isDeepDiveMode]);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    resetInactivity();
    if (startupSequenceTimer.current) {
      clearTimeout(startupSequenceTimer.current);
      startupSequenceTimer.current = null;
    }

    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || 
        orionState === OrionState.SYSTEM_ALERT || 
        orionState === OrionState.SYSTEM_SUCCESS) return;

    if (inputValue.length === 0) {
      setOrionState(OrionState.FOCUSED_EMPTY);
    } else {
      setOrionState(OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    resetInactivity();
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && 
        orionState !== OrionState.AWAITING_PERMISSION &&
        orionState !== OrionState.SYSTEM_ALERT &&
        orionState !== OrionState.SYSTEM_SUCCESS) {
        if (val.length === 0) {
            setOrionState(OrionState.FOCUSED_EMPTY);
        } else {
            setOrionState(OrionState.FOCUSED);
        }
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;

    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);

    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();
      setPendingAction({
        description: actionDescription,
        originalResponse: cleanText
      });
      return cleanText;
    }

    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/;
    const memMatch = cleanText.match(memoryRegex);

    if (memMatch) {
      const contentToSave = memMatch[1];
      cleanText = cleanText.replace(memoryRegex, '').trim();
      if (saveMemory(contentToSave)) {
        setOrionState(OrionState.SYSTEM_SUCCESS);
        setTimeout(() => {
           if (stateRef.current === OrionState.SYSTEM_SUCCESS) setOrionState(OrionState.IDLE);
        }, 2000);
      }
    }
    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;

    resetInactivity();
    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);

    setOrionState(OrionState.PROCESSING);

    if (currentText.toLowerCase().includes('status') || currentText.toLowerCase().includes('notific')) {
      setNotifications(prev => prev.map(n => ({...n, read: true})));
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: currentText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);

      const systemMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: cleanResponse,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, systemMsg]);

      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else {
         if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
            setOrionState(OrionState.ACTIVE);
            setTimeout(() => {
                if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                    stateRef.current !== OrionState.SYSTEM_ALERT &&
                    stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                    setOrionState(OrionState.IDLE);
                }
            }, 1500);
         }
      }

    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;
    resetInactivity();

    const decisionText = allowed 
      ? `[SISTEMA]: Permissão CONCEDIDA para: ${pendingAction.description}. Proceder.` 
      : `[SISTEMA]: Permissão NEGADA para: ${pendingAction.description}. Abortar.`;

    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);

    const decisionMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: decisionText,
      timestamp: Date.now(),
    };

    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);

    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);
       setMessages(prev => [...prev, {
         id: Date.now().toString(),
         role: 'model',
         content: cleanResponse,
         timestamp: Date.now()
       }]);

       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                setOrionState(OrionState.ACTIVE);
                setTimeout(() => {
                    if (stateRef.current !== OrionState.AWAITING_PERMISSION && 
                        stateRef.current !== OrionState.SYSTEM_ALERT &&
                        stateRef.current !== OrionState.SYSTEM_SUCCESS) {
                        setOrionState(OrionState.IDLE);
                    }
                }, 1500);
           }
       }
    });
  };

  const handleToggleFilter = () => {
    setFilterSystemLogs(!filterSystemLogs);
  };

  // Filter messages based on toggle
  const visibleMessages = filterSystemLogs 
    ? messages.filter(m => m.role !== 'system') 
    : messages;

  return (
    <div className={`min-h-screen bg-[#f3f4f6] dark:bg-[#050505] text-gray-800 dark:text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out`}>

      {/* 
         LAYOUT MODE 1: Standard (Eyes Top, Content Center)
         LAYOUT MODE 2: Deep Dive (Eyes Background Fixed, Content Full Scroll)
      */}

      {/* Orion Eyes: Position logic based on Deep Dive */}
      <div className={`
          flex justify-center transition-all duration-1000 ease-in-out z-0
          ${isDeepDiveMode 
            ? 'fixed inset-0 items-center pointer-events-none opacity-20' 
            : 'flex-none w-full relative z-20 pt-10'}
          ${isDeepDiveMode && isUserInactive ? '!opacity-80' : ''} 
      `}>
        <OrionEyes state={orionState} />
      </div>

      {/* Chat Area: Body */}
      {messages.length > 0 && (
        <div className={`
            flex-1 w-full flex flex-col items-center justify-start overflow-hidden my-4 animate-[fadeIn_0.8s_ease-out]
            transition-all duration-1000 z-10
            ${isDeepDiveMode ? 'h-full' : ''}
            ${isDeepDiveMode && isUserInactive ? 'backdrop-blur-sm' : ''}
        `}>
            <TerminalOutput messages={visibleMessages} />
        </div>
      )}

      {/* Input Area: Footer */}
      <div className="flex-none w-full z-20 flex justify-center pb-6 bg-gradient-to-t from-[#f3f4f6] dark:from-[#050505] to-transparent pt-10">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
            onToggleFilter={handleToggleFilter}
            isFilterActive={filterSystemLogs}
        />
      </div>

      {/* Background Noise - Invert filter on light mode to create dark noise */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-[-1] invert dark:invert-0 transition-all duration-1000" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>

    </div>
  );
};

export default App;

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message, SysNotification } from "../types";
import { getMemoryContextString } from "./memoryService";

// Initialize the client strictly with process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Mock function to get battery (safe wrapper)
const getBatteryInfo = async () => {
  try {
    // @ts-ignore - navigator.getBattery is not standard in all TS lib definitions yet
    if (navigator.getBattery) {
      // @ts-ignore
      const battery = await navigator.getBattery();
      return `${Math.round(battery.level * 100)}%${battery.charging ? ' (Carregando)' : ''}`;
    }
  } catch (e) {
    return "Indisponível (Sensor restrito)";
  }
  return "Alimentação AC / Desconhecido";
};

// Function to gather "System Senses"
const getSystemContext = async (activeNotifications: SysNotification[]): Promise<string> => {
  const now = new Date();
  const nav = window.navigator;
  const battery = await getBatteryInfo();
  const memoryContext = getMemoryContextString();

  // Filter unread notifications to "feed" to Orion's subconscious
  const unread = activeNotifications.filter(n => !n.read);
  const notificationContext = unread.length > 0 
    ? `ALERTA SENSORIAL: Você detecta ${unread.length} notificações pendentes no sistema: ${unread.map(n => `[${n.title}]`).join(', ')}. (Lembre-se: Só mencione se perguntado).` 
    : "SENSORIAL: Nenhuma notificação pendente.";

  return `
[DADOS DE TELEMETRIA EM TEMPO REAL]
HORA: ${now.toLocaleTimeString()}
DATA: ${now.toLocaleDateString()}
ENERGIA: ${battery}
CONEXÃO: ${nav.onLine ? "Estável (Online)" : "Instável (Offline)"}
PLATAFORMA: ${nav.platform}
${notificationContext}

${memoryContext}
`;
};

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  notifications: SysNotification[],
  imagePart?: string 
): Promise<string> => {
  try {
    // Inject system context into the very first message or as a system prelude
    const systemContextString = await getSystemContext(notifications);

    // Filter history, but ONLY keep the last 10 messages (short-term memory)
    // + ensures we keep the most relevant context without bloating
    const recentHistory = history.slice(-10);

    // Convert app history to GenAI Content format
    let contents: Content[] = recentHistory
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    if (contents.length > 0 && contents[0].role === 'model') {
       contents.shift();
    }

    const finalUserMessageText = `
${systemContextString}

INPUT DO USUÁRIO:
${userMessage}
`;

    const newParts: Part[] = [];

    if (imagePart) {
      newParts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: imagePart,
        },
      });
    }

    newParts.push({ text: finalUserMessageText });

    contents.push({
      role: 'user',
      parts: newParts,
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.85, 
        maxOutputTokens: 1000, 
      },
    });

    if (response.text) {
      return response.text;
    }

    return "Conexão instável. Tente novamente."; 
  } catch (error) {
    console.error("Orion System Error:", error);
    return "Erro nos subsistemas de linguagem."; 
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, LogEntry, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory, clearHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [filterSystemLogs, setFilterSystemLogs] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
  const [notifications, setNotifications] = useState<SysNotification[]>([]);

  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inactivityTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [isUserInactive, setIsUserInactive] = useState(false);

  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(savedMessages);
    }
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      saveHistory(messages);
    }
  }, [messages]);

  const isDeepDiveMode = messages.length > 4;

  const resetInactivity = useCallback(() => {
    setIsUserInactive(false);
    if (stateRef.current === OrionState.OBSERVING) {
       setOrionState(OrionState.IDLE);
    }
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    if (isDeepDiveMode) {
      inactivityTimer.current = setTimeout(() => {
        setIsUserInactive(true);
        if (stateRef.current !== OrionState.PROCESSING && 
            stateRef.current !== OrionState.FOCUSED && 
            stateRef.current !== OrionState.FOCUSED_EMPTY) {
            setOrionState(OrionState.OBSERVING);
        }
      }, 5000);
    }
  }, [isDeepDiveMode]);

  useEffect(() => {
    window.addEventListener('mousemove', resetInactivity);
    window.addEventListener('keydown', resetInactivity);
    window.addEventListener('scroll', resetInactivity);
    resetInactivity();
    return () => {
      window.removeEventListener('mousemove', resetInactivity);
      window.removeEventListener('keydown', resetInactivity);
      window.removeEventListener('scroll', resetInactivity);
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    };
  }, [resetInactivity]);

  const triggerSystemEvent = (content: string, eventType: OrionState = OrionState.SYSTEM_ALERT) => {
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);
    setOrionState(eventType);
    const alertMsg: Message = {
      id: Date.now().toString(),
      role: 'model', 
      content: content,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, alertMsg]);
    setTimeout(() => {
      if (stateRef.current === eventType) {
        setOrionState(OrionState.IDLE);
        startSleepSequence();
      }
    }, 4000);
  };

  useEffect(() => {
    const handleOnline = () => triggerSystemEvent(":: CONEXÃO RESTABELECIDA.", OrionState.SYSTEM_SUCCESS);
    const handleOffline = () => triggerSystemEvent(":: CONEXÃO PERDIDA.", OrionState.SYSTEM_ALERT);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      setOrionState(OrionState.IDLE);
      return;
    }
    setOrionState(OrionState.IDLE);
    startupSequenceTimer.current = setTimeout(() => {
      if (stateRef.current !== OrionState.IDLE) return;
      setOrionState(OrionState.LOOKING_AROUND);
      startupSequenceTimer.current = setTimeout(() => {
        if (stateRef.current !== OrionState.LOOKING_AROUND) return;
        setOrionState(OrionState.SQUINTING);
        startupSequenceTimer.current = setTimeout(() => {
          if (stateRef.current !== OrionState.SQUINTING) return;
          setOrionState(OrionState.SLEEPING);
        }, 2500); 
      }, 4000); 
    }, 6000); 
    return () => { if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current); };
  }, []); 

  const startSleepSequence = useCallback(() => {
    if (isDeepDiveMode) return;
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS) return;
    setOrionState(OrionState.PRE_SLEEP);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);
    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS) return;
      setOrionState(OrionState.SQUINTING);
      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 
    }, 4000); 
  }, [isDeepDiveMode]);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    resetInactivity();
    if (startupSequenceTimer.current) clearTimeout(startupSequenceTimer.current);
    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || orionState === OrionState.SYSTEM_ALERT || orionState === OrionState.SYSTEM_SUCCESS) return;
    setOrionState(inputValue.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION && orionState !== OrionState.SYSTEM_ALERT && orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    resetInactivity();
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION && orionState !== OrionState.SYSTEM_ALERT && orionState !== OrionState.SYSTEM_SUCCESS) {
        setOrionState(val.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;

    // Handle Reset Signal
    if (cleanText.includes('[[SESSION_RESET]]')) {
      cleanText = cleanText.replace('[[SESSION_RESET]]', '').trim();
      setOrionState(OrionState.SYSTEM_SUCCESS);
      setTimeout(() => {
        setMessages([]);
        clearHistory();
        setOrionState(OrionState.IDLE);
      }, 2000);
    }

    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);
    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();
      setPendingAction({ description: actionDescription, originalResponse: cleanText });
      return cleanText;
    }

    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/;
    const memMatch = cleanText.match(memoryRegex);
    if (memMatch) {
      const contentToSave = memMatch[1];
      cleanText = cleanText.replace(memoryRegex, '').trim();
      if (saveMemory(contentToSave)) {
        if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
           setOrionState(OrionState.SYSTEM_SUCCESS);
           setTimeout(() => { if (stateRef.current === OrionState.SYSTEM_SUCCESS) setOrionState(OrionState.IDLE); }, 2000);
        }
      }
    }
    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;
    resetInactivity();
    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();
    setOrionState(OrionState.PROCESSING);

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);
      const systemMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: cleanResponse, timestamp: Date.now() };
      setMessages(prev => prev.length > 0 ? [...prev, systemMsg] : []); // Safety check for reset

      if (rawResponse.includes('REQUEST_PERMISSION')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
         setOrionState(OrionState.ACTIVE);
         setTimeout(() => { if (stateRef.current === OrionState.ACTIVE) setOrionState(OrionState.IDLE); }, 1500);
      }
    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;
    resetInactivity();
    const decisionText = allowed ? `[AUTORIZADO]: ${pendingAction.description}` : `[NEGADO]: ${pendingAction.description}`;
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);
    const decisionMsg: Message = { id: Date.now().toString(), role: 'user', content: decisionText, timestamp: Date.now() };
    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);
    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);
       setMessages(prev => prev.length > 0 ? [...prev, { id: Date.now().toString(), role: 'model', content: cleanResponse, timestamp: Date.now() }] : []);
       if (rawResponse.includes('REQUEST_PERMISSION')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
           setOrionState(OrionState.ACTIVE);
           setTimeout(() => { if (stateRef.current === OrionState.ACTIVE) setOrionState(OrionState.IDLE); }, 1500);
       }
    });
  };

  const handleToggleFilter = () => setFilterSystemLogs(!filterSystemLogs);
  const visibleMessages = filterSystemLogs ? messages.filter(m => m.role !== 'system') : messages;

  return (
    <div className={`min-h-screen bg-[#f3f4f6] dark:bg-[#050505] text-gray-800 dark:text-gray-200 flex flex-col items-center relative overflow-hidden transition-all duration-1000 ease-in-out`}>
      <div className={`flex justify-center transition-all duration-1000 ease-in-out z-0 ${isDeepDiveMode ? 'fixed inset-0 items-center pointer-events-none opacity-20' : 'flex-none w-full relative z-20 pt-10'} ${isDeepDiveMode && isUserInactive ? '!opacity-80' : ''}`}>
        <OrionEyes state={orionState} />
      </div>
      {messages.length > 0 && (
        <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden my-4 animate-[fadeIn_0.8s_ease-out] transition-all duration-1000 z-10 ${isDeepDiveMode ? 'h-full' : ''} ${isDeepDiveMode && isUserInactive ? 'backdrop-blur-sm' : ''}`}>
            <TerminalOutput messages={visibleMessages} />
        </div>
      )}
      <div className="flex-none w-full z-20 flex justify-center pb-6 bg-gradient-to-t from-[#f3f4f6] dark:from-[#050505] to-transparent pt-10">
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
            onToggleFilter={handleToggleFilter}
            isFilterActive={filterSystemLogs}
        />
      </div>
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-[-1] invert dark:invert-0 transition-all duration-1000" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message, SysNotification } from "../types";
import { getMemoryContextString } from "./memoryService";

const getBatteryInfo = async () => {
  try {
    // @ts-ignore
    if (navigator.getBattery) {
      // @ts-ignore
      const battery = await navigator.getBattery();
      return `${Math.round(battery.level * 100)}%${battery.charging ? ' (Carregando)' : ''}`;
    }
  } catch (e) {
    return "Indisponível";
  }
  return "AC Power";
};

const getSystemContext = async (activeNotifications: SysNotification[]): Promise<string> => {
  const now = new Date();
  const battery = await getBatteryInfo();
  const memoryContext = getMemoryContextString();
  const unread = activeNotifications.filter(n => !n.read);

  return `
[TELEMETRIA DO SISTEMA]
HORA: ${now.toLocaleTimeString()}
DATA: ${now.toLocaleDateString()}
BATERIA: ${battery}
REDE: ${navigator.onLine ? "Online" : "Offline"}
NOTIFICAÇÕES: ${unread.length} pendentes.

${memoryContext}
`;
};

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  notifications: SysNotification[],
  imagePart?: string 
): Promise<string> => {
  try {
    // Re-initialize to ensure fresh key context from process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemContextString = await getSystemContext(notifications);
    const recentHistory = history.slice(-12);

    let contents: Content[] = recentHistory
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    if (contents.length > 0 && contents[0].role === 'model') {
       contents.shift();
    }

    const finalPrompt = `
${systemContextString}
USER: ${userMessage}
`;

    const newParts: Part[] = [];
    if (imagePart) {
      newParts.push({
        inlineData: { mimeType: 'image/jpeg', data: imagePart },
      });
    }
    newParts.push({ text: finalPrompt });

    contents.push({ role: 'user', parts: newParts });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.8,
        maxOutputTokens: 800,
      },
    });

    return response.text || "Falha na resposta do núcleo.";
  } catch (error: any) {
    console.error("Orion System Error:", error);
    if (error.message?.includes('403')) {
      return "ERRO DE ACESSO (403): Subsistema de linguagem restrito.";
    }
    return "Instabilidade nos subsistemas de resposta."; 
  }
};

