import React, { useEffect, useState } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);

  // Organic blink loop
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      if (
        state === OrionState.SLEEPING || 
        state === OrionState.SQUINTING || 
        state === OrionState.PROCESSING || 
        state === OrionState.AWAITING_PERMISSION ||
        state === OrionState.SYSTEM_ALERT ||
        state === OrionState.SYSTEM_SUCCESS ||
        state === OrionState.OBSERVING
      ) return;

      const blinkDuration = state === OrionState.PRE_SLEEP ? 400 : 150;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), blinkDuration);

      let nextBlink = 4000;
      if (state === OrionState.PRE_SLEEP) {
        nextBlink = 2000 + Math.random() * 2000;
      } else if (state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY) {
        nextBlink = 3000 + Math.random() * 5000;
      } else {
        nextBlink = 3000 + Math.random() * 4000;
      }

      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 1000);
    return () => clearTimeout(timeoutId);
  }, [state]);

  const getEyeStyles = () => {
    let baseStyle = "transition-all ease-in-out relative flex items-center justify-center overflow-hidden";
    let bgClass = "bg-zinc-800 dark:bg-white"; 

    if (state === OrionState.AWAITING_PERMISSION) {
      bgClass = "bg-amber-600 dark:bg-amber-500 shadow-[0_0_50px_rgba(245,158,11,0.4)] dark:shadow-[0_0_50px_rgba(245,158,11,0.6)]";
    } else if (state === OrionState.SYSTEM_ALERT) {
      bgClass = "bg-red-600 dark:bg-red-500 shadow-[0_0_60px_rgba(239,68,68,0.5)] dark:shadow-[0_0_60px_rgba(239,68,68,0.8)]";
    } else if (state === OrionState.SYSTEM_SUCCESS) {
      bgClass = "bg-emerald-600 dark:bg-emerald-500 shadow-[0_0_60px_rgba(16,185,129,0.5)] dark:shadow-[0_0_60px_rgba(16,185,129,0.8)]";
    }

    const eyeBase = `${baseStyle} ${bgClass}`;
    const defaultShadow = "shadow-[0_0_20px_rgba(0,0,0,0.1)] dark:shadow-[0_0_20px_rgba(255,255,255,0.4)]";
    const processingShadow = "shadow-[0_0_40px_rgba(0,0,0,0.15)] dark:shadow-[0_0_40px_rgba(255,255,255,0.9)]";

    switch (state) {
      case OrionState.PROCESSING:
        return {
          container: "gap-8 h-32", 
          eye: `${eyeBase} w-20 h-20 rounded-2xl ${processingShadow} animate-jump-spin`,
        };
      case OrionState.AWAITING_PERMISSION:
        return {
          container: "gap-8 h-32",
          eye: `${eyeBase} w-24 h-24 rounded-lg animate-pulse-slow`,
        };
      case OrionState.SYSTEM_ALERT:
        return {
          container: "gap-12 h-32",
          eye: `${eyeBase} w-20 h-20 rounded-md animate-ping-slow opacity-90`,
        };
      case OrionState.SYSTEM_SUCCESS:
        return {
          container: "gap-8 h-32",
          eye: `${eyeBase} w-20 h-20 rounded-xl animate-pulse-slow opacity-90`,
        };
      case OrionState.LOOKING_AROUND:
        return {
          container: "gap-5 h-32 animate-look-around",
          eye: `${eyeBase} w-20 h-20 rounded-2xl ${defaultShadow}`,
        };
      case OrionState.OBSERVING:
        return {
          container: "gap-20 h-full animate-deliberate-scan",
          eye: `${eyeBase} w-40 h-40 rounded-[3rem] shadow-[0_0_100px_rgba(0,0,0,0.08)] dark:shadow-[0_0_100px_rgba(255,255,255,0.2)] opacity-30 dark:opacity-50`,
        };
      case OrionState.ACTIVE: 
        return {
          container: "gap-5 h-32",
          eye: `${eyeBase} w-22 h-22 rounded-2xl shadow-[0_0_30px_rgba(0,0,0,0.1)] dark:shadow-[0_0_30px_rgba(255,255,255,0.7)]`,
        };
      case OrionState.SQUINTING: 
        return {
          container: "gap-6 h-32",
          eye: `${eyeBase} w-24 h-1 rounded-sm opacity-60 shadow-[0_0_10px_rgba(0,0,0,0.1)] dark:shadow-[0_0_10px_rgba(255,255,255,0.2)] duration-[2500ms]`,
        };
      case OrionState.SLEEPING:
        return {
          container: "gap-4 h-32",
          eye: `${eyeBase} w-20 h-0.5 opacity-10 shadow-none duration-[2000ms]`,
        };
      case OrionState.PRE_SLEEP: 
        return {
           container: "gap-5 h-32",
           eye: `${eyeBase} w-20 h-20 rounded-2xl opacity-80 shadow-[0_0_15px_rgba(0,0,0,0.1)] dark:shadow-[0_0_15px_rgba(255,255,255,0.3)] duration-1000`,
        };
      case OrionState.FOCUSED: 
      case OrionState.FOCUSED_EMPTY:
      case OrionState.IDLE:
      default:
        return {
          container: "gap-5 h-32",
          eye: `${eyeBase} w-20 h-20 rounded-2xl ${defaultShadow} duration-500`,
        };
    }
  };

  const styles = getEyeStyles();
  // Alteração crítica: Usar transform scale-y para piscar, mantendo a altura física do elemento intacta
  const blinkStyle = isBlinking ? 'scale-y-[0.05] opacity-50 duration-200' : 'scale-y-100 duration-200';

  return (
    <div className={`flex flex-col items-center justify-center w-full select-none transition-all duration-1000 ${state === OrionState.OBSERVING ? 'h-full' : 'h-32 pt-10'}`}>
      <style>{`
        @keyframes jump-spin {
          0% { transform: translateY(0) rotate(0deg); }
          20% { transform: translateY(-15px) rotate(180deg) scale(1.05); } 
          40% { transform: translateY(-5px) rotate(360deg) scale(1.0); }
          60% { transform: translateY(-2px) rotate(540deg); }
          100% { transform: translateY(0) rotate(720deg); }
        }
        @keyframes look-around {
          0% { transform: translateX(0); }
          10% { transform: translateX(-20px); } 
          30% { transform: translateX(-20px); }
          45% { transform: translateX(20px); }
          65% { transform: translateX(20px); }
          80% { transform: translateX(0); }
          100% { transform: translateX(0); }
        }
        @keyframes deliberate-scan {
          0% { transform: scale(1) translateX(0) translateY(0); }
          25% { transform: scale(1.02) translateX(-30px) translateY(-10px); }
          50% { transform: scale(1.05) translateX(30px) translateY(10px); }
          75% { transform: scale(1.02) translateX(-15px) translateY(20px); }
          100% { transform: scale(1) translateX(0) translateY(0); }
        }
        @keyframes ping-slow {
          0% { transform: scale(1); opacity: 0.9; }
          50% { transform: scale(1.1); opacity: 1; }
          100% { transform: scale(1); opacity: 0.9; }
        }
        .animate-jump-spin { animation: jump-spin 2s ease-in-out infinite; }
        .animate-look-around { animation: look-around 4s ease-in-out infinite; }
        .animate-deliberate-scan { animation: deliberate-scan 12s ease-in-out infinite; }
        .animate-pulse-slow { animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        .animate-ping-slow { animation: ping-slow 2s cubic-bezier(0, 0, 0.2, 1) infinite; }
      `}</style>

      <div className={`flex items-center justify-center transition-all ${styles.container}`}>
        <div className={`${styles.eye} ${blinkStyle}`} />
        <div className={`${styles.eye} ${blinkStyle}`} />
      </div>
    </div>
  );
};

export default OrionEyes;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory, clearHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.IDLE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [filterSystemLogs, setFilterSystemLogs] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
  const [notifications] = useState<SysNotification[]>([]);

  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inactivityTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [isUserInactive, setIsUserInactive] = useState(false);

  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(savedMessages);
    }
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      saveHistory(messages);
    }
  }, [messages]);

  const isDeepDiveMode = messages.length > 4;

  const resetInactivity = useCallback(() => {
    setIsUserInactive(false);
    if (stateRef.current === OrionState.OBSERVING) {
       setOrionState(OrionState.IDLE);
    }
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    if (isDeepDiveMode) {
      inactivityTimer.current = setTimeout(() => {
        setIsUserInactive(true);
        if (stateRef.current !== OrionState.PROCESSING && 
            stateRef.current !== OrionState.FOCUSED && 
            stateRef.current !== OrionState.FOCUSED_EMPTY &&
            stateRef.current !== OrionState.AWAITING_PERMISSION) {
            setOrionState(OrionState.OBSERVING);
        }
      }, 5000);
    }
  }, [isDeepDiveMode]);

  useEffect(() => {
    const events = ['mousemove', 'keydown', 'scroll', 'mousedown', 'touchstart'];
    events.forEach(e => window.addEventListener(e, resetInactivity));
    resetInactivity();
    return () => {
      events.forEach(e => window.removeEventListener(e, resetInactivity));
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    };
  }, [resetInactivity]);

  const startSleepSequence = useCallback(() => {
    if (isDeepDiveMode) return;
    if (stateRef.current === OrionState.AWAITING_PERMISSION || 
        stateRef.current === OrionState.PROCESSING ||
        stateRef.current === OrionState.SYSTEM_ALERT ||
        stateRef.current === OrionState.SYSTEM_SUCCESS ||
        stateRef.current === OrionState.OBSERVING) return;
    setOrionState(OrionState.PRE_SLEEP);
    if (sleepSequenceTimer.current) clearTimeout(sleepSequenceTimer.current);
    sleepSequenceTimer.current = setTimeout(() => {
      if (stateRef.current === OrionState.AWAITING_PERMISSION || 
          stateRef.current === OrionState.PROCESSING ||
          stateRef.current === OrionState.SYSTEM_ALERT ||
          stateRef.current === OrionState.SYSTEM_SUCCESS ||
          stateRef.current === OrionState.OBSERVING) return;
      setOrionState(OrionState.SQUINTING);
      sleepSequenceTimer.current = setTimeout(() => {
        if (stateRef.current === OrionState.AWAITING_PERMISSION || 
            stateRef.current === OrionState.PROCESSING ||
            stateRef.current === OrionState.SYSTEM_ALERT ||
            stateRef.current === OrionState.SYSTEM_SUCCESS ||
            stateRef.current === OrionState.OBSERVING) return;
        setOrionState(OrionState.SLEEPING);
      }, 3000); 
    }, 4000); 
  }, [isDeepDiveMode]);

  const cancelSleepSequence = useCallback(() => {
    if (sleepSequenceTimer.current) {
      clearTimeout(sleepSequenceTimer.current);
      sleepSequenceTimer.current = null;
    }
  }, []);

  const handleInputFocus = () => {
    resetInactivity();
    cancelSleepSequence();
    if (orionState === OrionState.AWAITING_PERMISSION || orionState === OrionState.SYSTEM_ALERT || orionState === OrionState.SYSTEM_SUCCESS) return;
    setOrionState(inputValue.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
  };

  const handleInputBlur = () => {
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION && orionState !== OrionState.SYSTEM_ALERT && orionState !== OrionState.SYSTEM_SUCCESS) {
        startSleepSequence();
    }
  };

  const handleInputChange = (val: string) => {
    resetInactivity();
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.AWAITING_PERMISSION && orionState !== OrionState.SYSTEM_ALERT && orionState !== OrionState.SYSTEM_SUCCESS) {
        setOrionState(val.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
    }
  };

  const processOrionResponse = (responseText: string) => {
    let cleanText = responseText;
    const memoryRegex = /\[\[MEMORY_WRITE:\s*(.*?)\]\]/g;
    let match;
    while ((match = memoryRegex.exec(cleanText)) !== null) {
      const contentToSave = match[1];
      saveMemory(contentToSave);
      setOrionState(OrionState.SYSTEM_SUCCESS);
    }
    cleanText = cleanText.replace(memoryRegex, '').trim();

    if (cleanText.includes('[[SESSION_RESET]]')) {
      cleanText = cleanText.replace('[[SESSION_RESET]]', '').trim();
      setOrionState(OrionState.SYSTEM_SUCCESS);
      setTimeout(() => {
        setMessages([]);
        clearHistory();
        setOrionState(OrionState.IDLE);
      }, 3000);
    }

    const permissionRegex = /\[\[REQUEST_PERMISSION:\s*(.*?)\]\]/;
    const permMatch = cleanText.match(permissionRegex);
    if (permMatch) {
      const actionDescription = permMatch[1];
      cleanText = cleanText.replace(permissionRegex, '').trim();
      setPendingAction({ description: actionDescription, originalResponse: cleanText });
    }
    return cleanText;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.AWAITING_PERMISSION) return;
    resetInactivity();
    const currentText = inputValue;
    setInputValue('');
    cancelSleepSequence();
    setOrionState(OrionState.PROCESSING);

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const newHistory = [...messages, userMsg];
    setMessages(newHistory);

    try {
      const rawResponse = await sendMessageToOrion(newHistory, currentText, notifications);
      const cleanResponse = processOrionResponse(rawResponse);
      const systemMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: cleanResponse, timestamp: Date.now() };
      setMessages(prev => prev.length > 0 ? [...prev, systemMsg] : [systemMsg]);

      if (rawResponse.includes('[[REQUEST_PERMISSION:')) {
         setOrionState(OrionState.AWAITING_PERMISSION);
      } else if (stateRef.current !== OrionState.SYSTEM_SUCCESS) {
         setOrionState(OrionState.ACTIVE);
         setTimeout(() => { if (stateRef.current === OrionState.ACTIVE) setOrionState(OrionState.IDLE); }, 1500);
      } else {
        setTimeout(() => { if (stateRef.current === OrionState.SYSTEM_SUCCESS) setOrionState(OrionState.IDLE); }, 2000);
      }
    } catch (error) {
      console.error(error);
      setOrionState(OrionState.IDLE);
      startSleepSequence();
    }
  };

  const handlePermissionDecision = (allowed: boolean) => {
    if (!pendingAction) return;
    resetInactivity();
    const decisionText = allowed ? `[AUTORIZADO]: ${pendingAction.description}` : `[NEGADO]: ${pendingAction.description}`;
    setPendingAction(null);
    setOrionState(OrionState.PROCESSING);
    const decisionMsg: Message = { id: Date.now().toString(), role: 'user', content: decisionText, timestamp: Date.now() };
    const newHistory = [...messages, decisionMsg];
    setMessages(newHistory);
    sendMessageToOrion(newHistory, decisionText, notifications).then(rawResponse => {
       const cleanResponse = processOrionResponse(rawResponse);
       setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: cleanResponse, timestamp: Date.now() }]);
       if (rawResponse.includes('[[REQUEST_PERMISSION:')) {
           setOrionState(OrionState.AWAITING_PERMISSION);
       } else {
           setOrionState(OrionState.ACTIVE);
           setTimeout(() => { if (stateRef.current === OrionState.ACTIVE) setOrionState(OrionState.IDLE); }, 1500);
       }
    });
  };

  const handleToggleFilter = () => setFilterSystemLogs(!filterSystemLogs);
  const visibleMessages = filterSystemLogs ? messages.filter(m => m.role !== 'system') : messages;

  return (
    <div className="h-screen w-screen bg-[#f3f4f6] dark:bg-[#050505] text-gray-800 dark:text-gray-200 flex flex-col relative overflow-hidden transition-all duration-1000 ease-in-out">
      {/* Background Observation Overlay */}
      <div className={`absolute inset-0 z-0 pointer-events-none transition-opacity duration-1000 ${orionState === OrionState.OBSERVING ? 'opacity-100' : 'opacity-0'}`}>
         <div className="absolute inset-0 bg-white/5 dark:bg-black/20 backdrop-blur-[2px]"></div>
         <div className="absolute inset-0 opacity-10 animate-scanline" style={{ backgroundImage: 'linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.5) 50%)', backgroundSize: '100% 4px' }}></div>
      </div>

      {/* Header Area (Eyes) - Fixed Height to prevent layout shift */}
      <div className={`flex-none w-full transition-all duration-1000 ease-in-out z-0 flex justify-center ${orionState === OrionState.OBSERVING ? 'fixed inset-0 items-center pointer-events-none h-screen' : 'relative h-48 pt-4'} ${isDeepDiveMode && !isUserInactive && orionState !== OrionState.OBSERVING ? 'opacity-20' : 'opacity-100'}`}>
        <OrionEyes state={orionState} />
      </div>

      {/* Chat History Area - Takes up remaining space */}
      <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden relative transition-all duration-1000 z-10 ${orionState === OrionState.OBSERVING ? 'opacity-30 blur-sm scale-[0.98]' : 'opacity-100'}`}>
        {messages.length > 0 && <TerminalOutput messages={visibleMessages} />}
      </div>

      {/* Input Area - Fixed at bottom */}
      <div className={`flex-none w-full z-20 flex justify-center pb-8 pt-4 bg-gradient-to-t from-[#f3f4f6] dark:from-[#050505] via-[#f3f4f6]/80 dark:via-[#050505]/80 to-transparent transition-all duration-700 ${orionState === OrionState.OBSERVING ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
            pendingAction={pendingAction}
            onPermissionDecide={handlePermissionDecision}
            onToggleFilter={handleToggleFilter}
            isFilterActive={filterSystemLogs}
        />
      </div>

      <style>{`
        @keyframes scanline {
          0% { transform: translateY(0); }
          100% { transform: translateY(100vh); }
        }
        .animate-scanline {
          animation: scanline 8s linear infinite;
        }
      `}</style>

      <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-[-1] invert dark:invert-0 transition-all duration-1000" 
           style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
