import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import { Message, OrionState, PendingAction, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory, clearHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.BOOTING);
  const [messages, setMessages] = useState<Message[]>([]);
  const [filterSystemLogs, setFilterSystemLogs] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
  const [notifications] = useState<SysNotification[]>([]);

  const sleepSequenceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inactivityTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [isUserInactive, setIsUserInactive] = useState(false);

  // Initial Boot Sequence
  useEffect(() => {
    const bootLogs = [
      "INICIALIZANDO KERNEL_ORION v2.5.0...",
      "MAPEANDO RECURSOS DE HARDWARE...",
      "CONEXÃO NEURAL ESTABELECIDA.",
      "SUBSISTEMAS: ONLINE."
    ];

    bootLogs.forEach((log, index) => {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          id: `boot-${index}`,
          role: 'system',
          content: log,
          timestamp: Date.now()
        }]);
      }, 500 * (index + 1));
    });

    setTimeout(() => {
      setOrionState(OrionState.IDLE);
      setMessages(prev => [...prev, {
        id: 'awake',
        role: 'model',
        content: "Fluxo estabilizado. Estou presente.",
        timestamp: Date.now()
      }]);
    }, 3000);
  }, []);

  const stateRef = useRef(orionState);
  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  useEffect(() => {
    const savedMessages = getHistory();
    if (savedMessages && savedMessages.length > 0) {
      setMessages(prev => [...prev, ...savedMessages]);
    }
  }, []);

  useEffect(() => {
    if (messages.length > 5) { // Only save after boot
      saveHistory(messages.filter(m => !m.id.startsWith('boot')));
    }
  }, [messages]);

  const isDeepDiveMode = messages.length > 8;

  const resetInactivity = useCallback(() => {
    setIsUserInactive(false);
    if (stateRef.current === OrionState.OBSERVING) setOrionState(OrionState.IDLE);
    if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
    if (isDeepDiveMode) {
      inactivityTimer.current = setTimeout(() => {
        setIsUserInactive(true);
        if (stateRef.current === OrionState.IDLE) setOrionState(OrionState.OBSERVING);
      }, 8000);
    }
  }, [isDeepDiveMode]);

  useEffect(() => {
    const events = ['mousemove', 'keydown', 'scroll', 'mousedown', 'touchstart'];
    events.forEach(e => window.addEventListener(e, resetInactivity));
    return () => events.forEach(e => window.removeEventListener(e, resetInactivity));
  }, [resetInactivity]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || orionState === OrionState.BOOTING) return;

    const currentText = inputValue;
    setInputValue('');
    setOrionState(OrionState.PROCESSING);

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);

    try {
      const rawResponse = await sendMessageToOrion([...messages, userMsg], currentText, notifications);
      const systemMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: rawResponse, timestamp: Date.now() };

      setMessages(prev => [...prev, systemMsg]);
      setOrionState(OrionState.ACTIVE);
      setTimeout(() => setOrionState(OrionState.IDLE), 1000);
    } catch (error) {
      setOrionState(OrionState.IDLE);
    }
  };

  return (
    <div className="h-screen w-screen bg-[#f3f4f6] dark:bg-[#050505] text-gray-800 dark:text-gray-200 flex flex-col relative overflow-hidden font-inter">
      {/* Background Observation Overlay */}
      <div className={`absolute inset-0 z-0 pointer-events-none transition-opacity duration-2000 ${orionState === OrionState.OBSERVING ? 'opacity-100' : 'opacity-0'}`}>
         <div className="absolute inset-0 bg-white/5 dark:bg-black/40 backdrop-blur-[4px]"></div>
         <div className="absolute inset-0 opacity-20 animate-scanline" style={{ backgroundImage: 'linear-gradient(to bottom, transparent 50%, rgba(255,255,255,0.1) 50%)', backgroundSize: '100% 2px' }}></div>
      </div>

      {/* Header Area (Eyes) */}
      <div className={`flex-none w-full transition-all duration-1000 z-0 flex justify-center ${orionState === OrionState.OBSERVING ? 'fixed inset-0 items-center h-screen' : 'relative h-48 pt-12'}`}>
        <OrionEyes state={orionState} />
      </div>

      {/* Terminal Area */}
      <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden relative z-10 transition-all duration-1000 ${orionState === OrionState.BOOTING ? 'pt-10' : ''} ${orionState === OrionState.OBSERVING ? 'opacity-10 blur-md pointer-events-none' : 'opacity-100'}`}>
        <TerminalOutput messages={messages} state={orionState} />
      </div>

      {/* Input Area */}
      <div className={`flex-none w-full z-20 flex justify-center pb-12 pt-4 transition-all duration-1000 ${orionState === OrionState.OBSERVING || orionState === OrionState.BOOTING ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={setInputValue}
            onInputSubmit={handleSendMessage}
            onInputFocus={() => {}}
            onInputBlur={() => {}}
        />
      </div>

      <style>{`
        @keyframes scanline { 0% { transform: translateY(0); } 100% { transform: translateY(100vh); } }
        .animate-scanline { animation: scanline 12s linear infinite; }
      `}</style>
    </div>
  );
};

export default App;

