              `}
            />

            <div className={`flex items-center justify-start w-full max-w-[500px] mt-4 transition-all duration-500 ${isTextVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
                <div className="font-mono text-sm tracking-widest text-zinc-300 flex-1 flex items-center overflow-hidden whitespace-nowrap">
                  <span className="text-zinc-600 mr-3 select-none">ORION_CMD:</span>
                  <span className="truncate">{inputValue}</span>
                  {state !== OrionState.PROCESSING && (
                    <span className="animate-cursor-terminal inline-block w-2 h-4 bg-white/80 ml-1"></span>
                  )}
                </div>

                {onToggleFilter && (
                  <button 
                    onClick={onToggleFilter}
                    className={`ml-4 p-1 rounded transition-all duration-300 z-30 ${isFilterActive ? 'text-emerald-500 bg-emerald-500/10' : 'text-zinc-600 hover:text-zinc-400'}`}
                    title="Logs do Sistema"
                  >
                     <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                       <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
                     </svg>
                  </button>
                )}
            </div>
          </>
        )}
      </div>
  );
};

