      <div className={`flex-none w-full transition-all duration-1000 z-0 flex justify-center ${orionState === OrionState.OBSERVING ? 'fixed inset-0 items-center h-screen' : 'relative h-48 pt-12'}`}>
        <OrionEyes state={orionState} />
      </div>

      <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden relative z-10 transition-all duration-1000 ${orionState === OrionState.BOOTING ? 'pt-10' : ''} ${orionState === OrionState.OBSERVING || orionState === OrionState.UNAUTHENTICATED ? 'opacity-10 blur-md pointer-events-none' : 'opacity-100'}`}>
        <TerminalOutput messages={messages} state={orionState} />
