      <div className={`flex-none w-full z-20 flex flex-col items-center justify-center pb-12 pt-4 transition-all duration-1000 ${orionState === OrionState.OBSERVING || orionState === OrionState.BOOTING || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <OrionInput 
            state={orionState}
