            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
        />

        {user && (
          <button 
            onClick={logout}
            className="mt-4 font-mono text-[8px] tracking-widest text-zinc-600 hover:text-zinc-400 transition-colors opacity-50 uppercase"
          >
