import React, { useRef, useEffect } from 'react';
import { OrionState, PendingAction } from '../types';

interface OrionInputProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
  onToggleFilter?: () => void;
  isFilterActive?: boolean;
}

const OrionInput: React.FC<OrionInputProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide,
  onToggleFilter,
  isFilterActive
}) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onInputSubmit();
    }
  };

  // Auto-resize textarea height based on content
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [inputValue]);

  const isTextVisible = state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY || (state === OrionState.PROCESSING && inputValue !== "");

  return (
      <div className="w-full max-w-2xl flex flex-col items-center justify-center relative group min-h-[100px] px-4 transition-all duration-500">
        <style>{`
          @keyframes cursor-blink-terminal {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
          }
          @keyframes line-think {
            0% { width: 40px; opacity: 0.3; }
            50% { width: 120px; opacity: 0.6; }
            100% { width: 40px; opacity: 0.3; }
          }
          .animate-cursor-terminal {
            animation: cursor-blink-terminal 1s steps(2, start) infinite;
          }
          .animate-line-think {
            animation: line-think 2s ease-in-out infinite;
          }
          /* Esconder scrollbar da textarea */
          .textarea-hide-scrollbar::-webkit-scrollbar { display: none; }
          .textarea-hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        `}</style>

        {state === OrionState.AWAITING_PERMISSION && pendingAction ? (
           <div className="flex flex-col items-center w-full animate-[fadeIn_0.3s_ease-out]">
              <div className="text-amber-500 font-mono text-xs tracking-widest mb-4 uppercase text-center max-w-xs">
                 Permissão Requerida: {pendingAction.description}
              </div>
              <div className="flex gap-4">
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(false)}
                   className="px-6 py-2 border border-red-500/30 text-red-500/80 hover:bg-red-500/10 font-mono text-xs tracking-wider transition-all rounded-none"
                 >
                    NEGAR
                 </button>
                 <button 
                   onClick={() => onPermissionDecide && onPermissionDecide(true)}
                   className="px-6 py-2 bg-amber-500/10 border border-amber-500/40 text-amber-500 hover:bg-amber-500/20 font-mono text-xs tracking-wider transition-all rounded-none shadow-[0_0_15px_rgba(245,158,11,0.1)]"
                 >
                    AUTORIZAR
                 </button>
              </div>
           </div>
        ) : (
          <>
            <textarea
              ref={textareaRef}
              value={inputValue}
              onChange={(e) => onInputChange(e.target.value)}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              onKeyDown={handleKeyDown}
              disabled={state === OrionState.PROCESSING || state === OrionState.BOOTING}
              rows={1}
              className="absolute inset-0 w-full opacity-0 cursor-text z-20 resize-none textarea-hide-scrollbar py-2"
              autoComplete="off"
              autoFocus
            />

            {/* Linha de status centralizada */}
            <div 
              className={`
                h-[1px] transition-all duration-700 ease-in-out relative mb-4
                ${state === OrionState.SLEEPING ? 'w-12 opacity-10 bg-zinc-700' : 'w-32 opacity-40 bg-zinc-500'}
                ${state === OrionState.FOCUSED || state === OrionState.FOCUSED_EMPTY ? 'w-full max-w-[500px] !opacity-100 bg-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' : ''}
                ${state === OrionState.PROCESSING ? 'bg-white shadow-[0_0_20px_rgba(255,255,255,0.5)] animate-line-think' : ''}
              `}
            />

            <div className={`flex items-start justify-start w-full max-w-[500px] transition-all duration-500 ${isTextVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
                <div className="font-mono text-sm tracking-widest text-zinc-300 flex-1 flex flex-wrap items-center">
                  <span className="text-zinc-600 mr-3 select-none flex-shrink-0">ORION_CMD:</span>
                  <span className="break-all whitespace-pre-wrap">{inputValue}</span>
                  {state !== OrionState.PROCESSING && (
                    <span className="animate-cursor-terminal inline-block w-2 h-4 bg-white/80 ml-1 flex-shrink-0"></span>
                  )}
                </div>

                {onToggleFilter && (
                  <button 
                    onClick={onToggleFilter}
                    className={`ml-4 p-1 rounded-none transition-all duration-300 z-30 flex-shrink-0 ${isFilterActive ? 'text-emerald-500 bg-emerald-500/10' : 'text-zinc-600 hover:text-zinc-400'}`}
                    title="Logs do Sistema"
                  >
                     <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                       <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
                     </svg>
                  </button>
                )}
            </div>
          </>
        )}
      </div>
  );
};

