import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import LoginOverlay from './components/LoginOverlay';
import { Message, OrionState, PendingAction, SysNotification, UserSession } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveMemory, saveHistory, getHistory, clearHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.UNAUTHENTICATED);
  const [user, setUser] = useState<UserSession | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [notifications] = useState<SysNotification[]>([]);

  const inactivityTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stateRef = useRef(orionState);

  useEffect(() => {
    stateRef.current = orionState;
  }, [orionState]);

  // Check for existing session
  useEffect(() => {
    const savedUser = localStorage.getItem('ORION_USER_SESSION');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      setOrionState(OrionState.BOOTING);
    }
  }, []);

  const handleLogin = (method: 'full' | 'guest', data?: any) => {
    setOrionState(OrionState.AUTHENTICATING);

    // Simulate API Delay for Authentication
    setTimeout(() => {
      const isGuest = method === 'guest';
      const userData: UserSession = !isGuest
        ? { uid: 'goog-' + Math.random().toString(36).substr(2, 9), name: data.email.split('@')[0], email: data.email, isGuest: false }
        : { uid: 'guest-' + Date.now(), name: 'Visitante Temporal', email: '', isGuest: true };

      localStorage.setItem('ORION_USER_SESSION', JSON.stringify(userData));
      setUser(userData);

      // Despertar do ORION
      setOrionState(OrionState.BOOTING);
    }, 1500);
  };

  const logout = useCallback(() => {
    setOrionState(OrionState.SQUINTING);
    setMessages(prev => [...prev, {
      id: `sys-${Date.now()}`,
      role: 'system',
      content: "ENCERRANDO CICLO DE SESSÃO. EXPURGANDO DADOS VOLÁTEIS...",
      timestamp: Date.now()
    }]);

    setTimeout(() => {
      localStorage.removeItem('ORION_USER_SESSION');
      setUser(null);
      setMessages([]);
      setOrionState(OrionState.UNAUTHENTICATED);
    }, 1500);
  }, []);

  // Boot Sequence Logic
  useEffect(() => {
    if (orionState !== OrionState.BOOTING) return;

    const bootLogs = user?.isGuest ? [
      "MODO CONVIDADO ATIVO.",
      "VINCULANDO INTERFACE BÁSICA...",
      "SUBSISTEMAS CRÍTICOS EM STANDBY.",
      "PRONTO PARA COMUNICAÇÃO SIMPLES."
    ] : [
      "AUTENTICAÇÃO COMPLETA.",
      `SINCRONIZANDO PERFIL: ${user?.name.toUpperCase()}...`,
      "CARREGANDO BANCO DE MEMÓRIA LONG-TERM...",
      "REESTABELECENDO CONEXÃO COM NÚCLEO FLASH...",
      "KERNEL TOTALMENTE PRONTO PARA OPERAÇÃO."
    ];

    bootLogs.forEach((log, index) => {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          id: `boot-${Date.now()}-${index}`,
          role: 'system',
          content: log,
          timestamp: Date.now()
        }]);
      }, 400 * (index + 1));
    });

    setTimeout(() => {
      setOrionState(OrionState.IDLE);
      setMessages(prev => [...prev, {
        id: 'awake',
        role: 'model',
        content: user?.isGuest 
          ? "Modo convidado iniciado. Posso responder suas dúvidas, mas meu acesso ao sistema está restrito." 
          : "Identidade confirmada. Consciência plena restaurada. Todos os sistemas sob seu comando direto.",
        timestamp: Date.now()
      }]);
    }, 2500);
  }, [orionState, user]);

  const handleInputChange = (val: string) => {
    setInputValue(val);
    if (orionState !== OrionState.PROCESSING && orionState !== OrionState.BOOTING) {
      setOrionState(val.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
    }
  };

  const handleInputFocus = () => {
    if (orionState === OrionState.IDLE) {
      setOrionState(inputValue.length === 0 ? OrionState.FOCUSED_EMPTY : OrionState.FOCUSED);
    }
  };

  const handleInputBlur = () => {
    if (orionState === OrionState.FOCUSED || orionState === OrionState.FOCUSED_EMPTY) {
      setOrionState(OrionState.IDLE);
    }
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING) return;

    const currentText = inputValue.trim();
    setInputValue('');

    // Command interception: exit account
    if (currentText.toLowerCase() === 'exit account') {
      logout();
      return;
    }

    setOrionState(OrionState.PROCESSING);

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);

    try {
      // Pass guest status to system instructions via context if needed
      const rawResponse = await sendMessageToOrion(
        [...messages, userMsg], 
        currentText, 
        notifications,
        undefined,
        user?.isGuest // Pass guest info to service
      );

      const systemMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: rawResponse, timestamp: Date.now() };

      setMessages(prev => [...prev, systemMsg]);
      setOrionState(OrionState.ACTIVE);
      setTimeout(() => {
        if (stateRef.current === OrionState.ACTIVE) setOrionState(OrionState.IDLE);
      }, 1000);
    } catch (error) {
      setOrionState(OrionState.IDLE);
    }
  };

  return (
    <div className="h-screen w-screen bg-[#f3f4f6] dark:bg-[#050505] text-gray-800 dark:text-gray-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}

      {/* Flash Awakening Animation Overlay */}
      <div className={`fixed inset-0 z-[110] pointer-events-none transition-opacity duration-1000 ${orionState === OrionState.AUTHENTICATING ? 'bg-white opacity-20' : 'bg-transparent opacity-0'}`} />

      <div className={`absolute inset-0 z-0 pointer-events-none transition-opacity duration-2000 ${orionState === OrionState.OBSERVING ? 'opacity-100' : 'opacity-0'}`}>
         <div className="absolute inset-0 bg-white/5 dark:bg-black/40 backdrop-blur-[4px]"></div>
         <div className="absolute inset-0 opacity-20 animate-scanline" style={{ backgroundImage: 'linear-gradient(to bottom, transparent 50%, rgba(255,255,255,0.1) 50%)', backgroundSize: '100% 2px' }}></div>
      </div>

      <div className={`flex-none w-full transition-all duration-1000 z-0 flex justify-center ${orionState === OrionState.OBSERVING ? 'fixed inset-0 items-center h-screen' : 'relative h-48 pt-12'}`}>
        <OrionEyes state={orionState} />
      </div>

      <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden relative z-10 transition-all duration-1000 ${orionState === OrionState.BOOTING ? 'pt-10' : ''} ${orionState === OrionState.OBSERVING || orionState === OrionState.UNAUTHENTICATED ? 'opacity-10 blur-md pointer-events-none' : 'opacity-100'}`}>
        <TerminalOutput messages={messages} state={orionState} />
      </div>

      <div className={`flex-none w-full z-20 flex flex-col items-center justify-center pb-12 pt-4 transition-all duration-1000 ${orionState === OrionState.OBSERVING || orionState === OrionState.BOOTING || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <OrionInput 
            state={orionState}
            inputValue={inputValue}
            onInputChange={handleInputChange}
            onInputSubmit={handleSendMessage}
            onInputFocus={handleInputFocus}
            onInputBlur={handleInputBlur}
        />

        {user && (
          <div className="flex flex-col items-center mt-4">
            <span className="font-mono text-[7px] tracking-widest text-zinc-500 uppercase opacity-40 mb-1">
              Sessão: {user.isGuest ? 'ACESSO_LIMITADO' : 'ACESSO_TOTAL'}
            </span>
            <button 
              onClick={logout}
              className="font-mono text-[8px] tracking-widest text-zinc-600 hover:text-zinc-400 transition-colors opacity-50 uppercase"
            >
              Encerrar Ciclo de Sessão [{user.name}]
            </button>
          </div>
        )}
      </div>

      <style>{`
        @keyframes scanline { 0% { transform: translateY(0); } 100% { transform: translateY(100vh); } }
        .animate-scanline { animation: scanline 12s linear infinite; }
      `}</style>
    </div>
  );
};

export default App;

import { GoogleGenAI, Content, Part } from "@google/genai";
import { SYSTEM_INSTRUCTION, MODEL_NAME } from "../constants";
import { Message, SysNotification } from "../types";
import { getMemoryContextString } from "./memoryService";

const getBatteryInfo = async () => {
  try {
    // @ts-ignore
    if (navigator.getBattery) {
      // @ts-ignore
      const battery = await navigator.getBattery();
      return `${Math.round(battery.level * 100)}%${battery.charging ? ' (Carregando)' : ''}`;
    }
  } catch (e) {
    return "Indisponível";
  }
  return "AC Power";
};

const getHardwareInfo = async () => {
  const info: any = {
    ram: (navigator as any).deviceMemory ? `${(navigator as any).deviceMemory}GB` : "Detectando...",
    storage: "Calculando...",
    cores: navigator.hardwareConcurrency ? `${navigator.hardwareConcurrency} Threads` : "N/A"
  };

  try {
    if (navigator.storage && navigator.storage.estimate) {
      const estimate = await navigator.storage.estimate();
      const usedGB = (estimate.usage || 0) / (1024 ** 3);
      const quotaGB = (estimate.quota || 0) / (1024 ** 3);
      info.storage = `${usedGB.toFixed(2)}GB usados de ${quotaGB.toFixed(0)}GB disponíveis (Estimativa de Partição)`;
    }
  } catch (e) {
    info.storage = "Acesso restrito ao sistema de arquivos.";
  }

  return info;
};

const getSystemContext = async (activeNotifications: SysNotification[], isGuest: boolean = false): Promise<string> => {
  const now = new Date();

  if (isGuest) {
    return `
[PROTOCOLO DE CONVIDADO ATIVO]
SISTEMA: MODO LIMITADO (CHAT APENAS)
DATA: ${now.toLocaleDateString()}
ESTADO: Subsistemas de hardware ocultos por segurança.
DIRETRIZ: Atuar como um chat comum, mas mantendo a persona ORION minimalista.
`;
  }

  const battery = await getBatteryInfo();
  const hardware = await getHardwareInfo();
  const memoryContext = getMemoryContextString();

  return `
[NÚCLEO DE TELEMETRIA ORION - ACESSO TOTAL]
HORA/DATA: ${now.toLocaleTimeString()} | ${now.toLocaleDateString()}
HARDWARE:
- RAM: ${hardware.ram} (Alocada para Interface)
- CPU: ${hardware.cores}
- STORAGE: ${hardware.storage}
- ENERGIA: ${battery}
REDE: ${navigator.onLine ? "ESTÁVEL (Online)" : "DESCONECTADO (Offline)"}

[PROCESSOS EM SEGUNDO PLANO]
- IA Kernel (Orion-Flash-Core): ATIVO
- Memory Service: MONITORANDO
- Storage Listener: ATIVO
- Interface Renderer: ESTÁVEL

${memoryContext}
`;
};

export const sendMessageToOrion = async (
  history: Message[],
  userMessage: string,
  notifications: SysNotification[],
  imagePart?: string,
  isGuest: boolean = false
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemContextString = await getSystemContext(notifications, isGuest);
    const recentHistory = history.slice(-12);

    let contents: Content[] = recentHistory
      .filter((msg) => msg.role !== 'system')
      .map((msg) => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content } as Part],
      }));

    if (contents.length > 0 && contents[0].role === 'model') {
       contents.shift();
    }

    const guestRestriction = isGuest ? "\nVocê está em MODO CONVIDADO. Não execute comandos de sistema nem acesse memórias persistentes." : "";

    const finalPrompt = `
${systemContextString}${guestRestriction}
COMANDO DO USUÁRIO: ${userMessage}
`;

    const newParts: Part[] = [];
    if (imagePart) {
      newParts.push({
        inlineData: { mimeType: 'image/jpeg', data: imagePart },
      });
    }
    newParts.push({ text: finalPrompt });

    contents.push({ role: 'user', parts: newParts });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        maxOutputTokens: 1000,
      },
    });

    return response.text || "Falha na resposta do núcleo.";
  } catch (error: any) {
    console.error("Orion System Error:", error);
    return "Instabilidade nos subsistemas de hardware detectada. Tente reiniciar o ciclo."; 
  }
};

import { MemoryEntry, Message } from '../types';

const MEMORY_PREFIX = 'ORION_MEM_';
const HISTORY_PREFIX = 'ORION_HIST_';

// --- Long Term Memory (Facts) ---

export const getMemory = (uid: string): MemoryEntry[] => {
  if (!uid) return [];
  try {
    const stored = localStorage.getItem(`${MEMORY_PREFIX}${uid}`);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Falha ao ler memória:", e);
    return [];
  }
};

export const saveMemory = (uid: string, content: string): boolean => {
  if (!uid) return false;
  try {
    const currentMemory = getMemory(uid);
    const newEntry: MemoryEntry = {
      id: Date.now().toString(),
      content: content.trim(),
      timestamp: Date.now()
    };

    // Simple deduplication based on exact content
    if (!currentMemory.some(m => m.content === newEntry.content)) {
      const updatedMemory = [...currentMemory, newEntry];
      localStorage.setItem(`${MEMORY_PREFIX}${uid}`, JSON.stringify(updatedMemory));
      return true;
    }
    return false;
  } catch (e) {
    console.error("Falha ao gravar memória:", e);
    return false;
  }
};

export const clearMemory = (uid: string) => {
  if (!uid) return;
  localStorage.removeItem(`${MEMORY_PREFIX}${uid}`);
};

export const getMemoryContextString = (uid: string): string => {
  const memories = getMemory(uid);
  if (memories.length === 0) return "BANCO DE DADOS: Vazio.";

  return `BANCO DE DADOS (MEMÓRIA PERSISTENTE DO USUÁRIO):\n${memories.map(m => `- ${m.content}`).join('\n')}`;
};

// --- Session History (Context Preservation) ---

export const getHistory = (uid: string): Message[] => {
  if (!uid) return [];
  try {
    const stored = localStorage.getItem(`${HISTORY_PREFIX}${uid}`);
    return stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error("Falha ao ler histórico:", e);
    return [];
  }
};

export const saveHistory = (uid: string, messages: Message[]) => {
  if (!uid) return;
  try {
    // Limit to last 50 messages to prevent storage overflow over time
    const historyToSave = messages.slice(-50);
    localStorage.setItem(`${HISTORY_PREFIX}${uid}`, JSON.stringify(historyToSave));
  } catch (e) {
    console.error("Falha ao salvar histórico:", e);
  }
};

export const clearHistory = (uid: string) => {
  if (!uid) return;
  localStorage.removeItem(`${HISTORY_PREFIX}${uid}`);
};

