// Audio Helpers
function encode(bytes: Uint8Array) {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.UNAUTHENTICATED);
  const [user, setUser] = useState<UserSession | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);

  const stateRef = useRef(orionState);
  const audioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);

  useEffect(() => { stateRef.current = orionState; }, [orionState]);

  useEffect(() => {
    const savedUser = localStorage.getItem('ORION_USER_SESSION');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      setOrionState(OrionState.BOOTING);
    }
  }, []);

  useEffect(() => {
    if (user && messages.length > 0) saveHistory(user.uid, messages);
  }, [messages, user]);

  const handleLogin = (method: 'full' | 'guest', data?: any) => {
    setOrionState(OrionState.AUTHENTICATING);
    setMessages([]);
    setTimeout(() => {
      const isGuest = method === 'guest';
      const userData: UserSession = !isGuest
        ? { uid: 'u-' + btoa(data.email).replace(/=/g, '').substr(0, 12), name: data.email.split('@')[0], email: data.email, isGuest: false }
        : { uid: 'guest-' + Date.now(), name: 'Visitante Temporal', email: '', isGuest: true };
      localStorage.setItem('ORION_USER_SESSION', JSON.stringify(userData));
      setUser(userData);
      setMessages(getHistory(userData.uid));
      setOrionState(OrionState.BOOTING);
    }, 1500);
  };

  const logout = useCallback(() => {
    setOrionState(OrionState.SQUINTING);
    setMessages(prev => [...prev, { id: `sys-${Date.now()}`, role: 'system', content: "ENCERRANDO CICLO DE SESSÃO...", timestamp: Date.now() }]);
    setTimeout(() => {
      localStorage.removeItem('ORION_USER_SESSION');
      setUser(null);
      setMessages([]);
      setOrionState(OrionState.UNAUTHENTICATED);
      setIsVoiceMode(false);
    }, 1500);
  }, []);

  // Live API Connection Logic
  const startLiveSession = async () => {
    if (!user) return;
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputCtx;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob: Blob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData.data;
            if (audioData) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onclose: () => setIsLiveActive(false),
          onerror: () => setIsLiveActive(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: 'Você é ORION. Responda de forma curta e enigmática via áudio.'
        }
      });

      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error(e);
      setIsVoiceMode(false);
    }
  };

  const toggleVoiceMode = () => {
    if (!isVoiceMode) {
      setIsVoiceMode(true);
      startLiveSession();
    } else {
      setIsVoiceMode(false);
      if (liveSessionRef.current) liveSessionRef.current.close();
      setIsLiveActive(false);
    }
  };

  // Boot logic
  useEffect(() => {
    if (orionState !== OrionState.BOOTING || !user) return;
    const hasHistory = messages.length > 0;
    const bootLogs = user.isGuest ? ["MODO CONVIDADO ATIVO.", "SUBSISTEMAS EM STANDBY."] : ["AUTENTICAÇÃO COMPLETA.", `PERFIL: ${user.name.toUpperCase()}...`, "KERNEL PRONTO."];
    bootLogs.forEach((log, i) => setTimeout(() => setMessages(prev => [...prev, { id: `boot-${Date.now()}-${i}`, role: 'system', content: log, timestamp: Date.now() }]), 300 * (i + 1)));
    setTimeout(() => {
      setOrionState(OrionState.IDLE);
      if (!hasHistory) setMessages(prev => [...prev, { id: 'awake', role: 'model', content: user.isGuest ? "Modo convidado ativo." : "Consciência plena restaurada.", timestamp: Date.now() }]);
    }, 2000);
  }, [orionState, user]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || !user) return;
    const currentText = inputValue.trim();
    setInputValue('');
    if (currentText.toLowerCase() === 'exit account') { logout(); return; }
    setOrionState(OrionState.PROCESSING);
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const updated = [...messages, userMsg];
    setMessages(updated);
    try {
      const response = await sendMessageToOrion(user.uid, updated, currentText, [], undefined, user.isGuest);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: response, timestamp: Date.now() }]);
      setOrionState(OrionState.ACTIVE);
      setTimeout(() => setOrionState(OrionState.IDLE), 1000);
    } catch { setOrionState(OrionState.IDLE); }
  };

  return (
    <div className="h-screen w-screen bg-[#f3f4f6] dark:bg-[#050505] text-zinc-800 dark:text-zinc-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}

      {isVoiceMode && <VoiceInterface onClose={toggleVoiceMode} isListening={isLiveActive} />}

      {/* Top Bar Controls */}
      {orionState !== OrionState.UNAUTHENTICATED && !isVoiceMode && (
        <div className="absolute top-6 right-8 z-40 flex items-center gap-6">
          <button 
            onClick={toggleVoiceMode}
            className="p-2 text-zinc-500 hover:text-white transition-colors group"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="group-hover:scale-110 transition-transform">
              <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/>
              <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
              <line x1="12" y1="19" x2="12" y2="22"/>
            </svg>
          </button>
          <button className="p-2 text-zinc-500 hover:text-white transition-colors">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </button>
        </div>
      )}

      {/* Main Terminal UI */}
      <div className={`flex-none w-full transition-all duration-1000 z-0 flex justify-center h-48 pt-12 ${isVoiceMode ? 'opacity-0 scale-95' : 'opacity-100'}`}>
        <OrionEyes state={orionState} />
      </div>

      <div className={`flex-1 w-full flex flex-col items-center justify-start overflow-hidden relative z-10 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 blur-xl scale-105 pointer-events-none' : 'opacity-100'}`}>
        <TerminalOutput messages={messages} state={orionState} />
      </div>

      <div className={`flex-none w-full z-20 flex flex-col items-center justify-center pb-12 pt-4 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <OrionInput state={orionState} inputValue={inputValue} onInputChange={setInputValue} onInputSubmit={handleSendMessage} onInputFocus={()=>{}} onInputBlur={()=>{}} />
        {user && (
          <div className="flex flex-col items-center mt-4">
            <span className="font-mono text-[7px] tracking-widest text-zinc-600 uppercase opacity-40 mb-1">Sessão: {user.isGuest ? 'LIMITED' : 'FULL'} | ID: {user.uid}</span>
            <button onClick={logout} className="font-mono text-[8px] tracking-widest text-zinc-700 hover:text-zinc-500 transition-colors opacity-50 uppercase">EXIT ACCOUNT [{user.name}]</button>
          </div>
        )}
      </div>
    </div>
  );
};

