  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.email || !formData.password) {
      setError('CREDENCIAIS INCOMPLETAS.');
      return;
    }
    onLogin('full', { email: formData.email });
