}

import React, { useEffect, useState } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);

  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const blink = () => {
      if (
        state === OrionState.BOOTING ||
        state === OrionState.SLEEPING || 
        state === OrionState.SQUINTING || 
        state === OrionState.UNAUTHENTICATED
      ) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 150);

      let nextBlink = 4000 + Math.random() * 3000;
      timeoutId = setTimeout(blink, nextBlink);
    };

    timeoutId = setTimeout(blink, 2000);
    return () => clearTimeout(timeoutId);
  }, [state]);

  const getStateConfig = () => {
    // Default (White)
    let config = {
      color: "bg-white",
      glow: "shadow-[0_0_50px_rgba(255,255,255,0.3)]",
      text: "",
      barColor: "bg-white/20",
      highlightColor: "bg-white/60"
    };

    switch (state) {
      case OrionState.CHARGING:
        config = {
          color: "bg-[#00e676]",
          glow: "shadow-[0_0_60px_rgba(0,230,118,0.5)]",
          text: "CHARGING",
          barColor: "bg-[#00e676]/10",
          highlightColor: "bg-[#00e676]"
        };
        break;
      case OrionState.ON_BATTERY:
        config = {
          color: "bg-[#ffa726]",
          glow: "shadow-[0_0_60px_rgba(255,167,38,0.5)]",
          text: "ON BATTERY",
          barColor: "bg-[#ffa726]/10",
          highlightColor: "bg-[#ffa726]"
        };
        break;
      case OrionState.SYSTEM_ALERT:
        config = {
          color: "bg-[#ff5252]",
          glow: "shadow-[0_0_60px_rgba(255,82,82,0.5)]",
          text: "HIGH LOAD",
          barColor: "bg-[#ff5252]/10",
          highlightColor: "bg-[#ff5252]"
        };
        break;
      case OrionState.PROCESSING:
        config = {
          color: "bg-[#00e5ff]",
          glow: "shadow-[0_0_60px_rgba(0,229,255,0.5)]",
          text: "ANALYZING",
          barColor: "bg-[#00e5ff]/10",
          highlightColor: "bg-[#00e5ff]"
        };
        break;
      case OrionState.UNAUTHENTICATED:
        config.color = "bg-white/10";
        config.glow = "shadow-none";
        break;
    }
    return config;
  };

  const config = getStateConfig();
  const blinkStyle = isBlinking ? 'scale-y-0 opacity-0' : 'scale-y-100 opacity-100';

  if (state === OrionState.AUTHENTICATING) {
    return (
      <div className="flex items-center justify-center w-full h-48">
        <div className="w-1 h-32 bg-white animate-pulse shadow-[0_0_100px_white]"></div>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center w-full select-none transition-all duration-700">
      <style>{`
        .eye-sq {
          width: 80px;
          height: 80px;
          border-radius: 20px;
          transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
        }
        @keyframes flow {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .animate-flow {
          animation: flow 3s linear infinite;
        }
      `}</style>

      {/* Eyes Container */}
      <div className={`flex gap-8 mb-16 transition-all duration-700 ${state === OrionState.SLEEPING ? 'opacity-0 scale-90' : 'opacity-100'}`}>
        <div className={`eye-sq ${config.color} ${config.glow} ${blinkStyle}`} />
        <div className={`eye-sq ${config.color} ${config.glow} ${blinkStyle}`} />
      </div>

      {/* Status Label */}
      {config.text && (
        <div className="flex flex-col items-center animate-[fadeIn_0.5s_ease-out]">
          <span className="font-mono text-[9px] tracking-[0.5em] mb-4 transition-colors duration-700" style={{ color: config.highlightColor.replace('bg-', '') }}>
            {config.text}
          </span>

          {/* Progress Bar */}
          <div className={`w-64 h-[1px] relative overflow-hidden ${config.barColor}`}>
             <div className={`absolute inset-y-0 w-1/3 blur-[2px] opacity-80 animate-flow ${config.highlightColor}`}></div>
          </div>
        </div>
      )}
    </div>
  );
};

