import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import LoginOverlay from './components/LoginOverlay';
import VoiceInterface from './components/VoiceInterface';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { Message, OrionState, UserSession, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveHistory, getHistory } from './services/memoryService';

// Audio Helpers
function encode(bytes: Uint8Array) {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.UNAUTHENTICATED);
  const [user, setUser] = useState<UserSession | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [batteryCharging, setBatteryCharging] = useState(false);

  const stateRef = useRef(orionState);
  const audioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);

  useEffect(() => { stateRef.current = orionState; }, [orionState]);

  // Battery Detection
  useEffect(() => {
    const monitorBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        const battery = await navigator.getBattery();
        setBatteryCharging(battery.charging);

        const updateCharging = () => setBatteryCharging(battery.charging);
        battery.addEventListener('chargingchange', updateCharging);
        return () => battery.removeEventListener('chargingchange', updateCharging);
      }
    };
    monitorBattery();
  }, []);

  // Set visual state based on battery if idle/focused
  useEffect(() => {
    if (orionState === OrionState.IDLE || orionState === OrionState.FOCUSED || orionState === OrionState.FOCUSED_EMPTY) {
      if (batteryCharging) {
        setOrionState(OrionState.CHARGING);
      } else {
        setOrionState(OrionState.ON_BATTERY);
      }
    } else if ((orionState === OrionState.CHARGING || orionState === OrionState.ON_BATTERY) && !batteryCharging && orionState === OrionState.CHARGING) {
        setOrionState(OrionState.ON_BATTERY);
    } else if ((orionState === OrionState.CHARGING || orionState === OrionState.ON_BATTERY) && batteryCharging && orionState === OrionState.ON_BATTERY) {
        setOrionState(OrionState.CHARGING);
    }
  }, [batteryCharging, orionState]);

  useEffect(() => {
    const savedUser = localStorage.getItem('ORION_USER_SESSION');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      setOrionState(OrionState.BOOTING);
    }
  }, []);

  useEffect(() => {
    if (user && messages.length > 0) saveHistory(user.uid, messages);
  }, [messages, user]);

  const handleLogin = (method: 'full' | 'guest', data?: any) => {
    setOrionState(OrionState.AUTHENTICATING);
    setMessages([]);
    setTimeout(() => {
      const isGuest = method === 'guest';
      const userData: UserSession = !isGuest
        ? { uid: 'u-' + btoa(data.email).replace(/=/g, '').substr(0, 12), name: data.email.split('@')[0], email: data.email, isGuest: false }
        : { uid: 'guest-' + Date.now(), name: 'Visitante Temporal', email: '', isGuest: true };
      localStorage.setItem('ORION_USER_SESSION', JSON.stringify(userData));
      setUser(userData);
      setMessages(getHistory(userData.uid));
      setOrionState(OrionState.BOOTING);
    }, 1500);
  };

  const logout = useCallback(() => {
    setOrionState(OrionState.SQUINTING);
    setMessages(prev => [...prev, { id: `sys-${Date.now()}`, role: 'system', content: "ENCERRANDO CICLO DE SESSÃO...", timestamp: Date.now() }]);
    setTimeout(() => {
      localStorage.removeItem('ORION_USER_SESSION');
      setUser(null);
      setMessages([]);
      setOrionState(OrionState.UNAUTHENTICATED);
      setIsVoiceMode(false);
    }, 1500);
  }, []);

  const startLiveSession = async () => {
    if (!user) return;
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputCtx;
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob: Blob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData.data;
            if (audioData) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onclose: () => setIsLiveActive(false),
          onerror: () => setIsLiveActive(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: 'Você é ORION. Responda de forma curta e enigmática via áudio.'
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error(e);
      setIsVoiceMode(false);
    }
  };

  const toggleVoiceMode = () => {
    if (!isVoiceMode) {
      setIsVoiceMode(true);
      startLiveSession();
    } else {
      setIsVoiceMode(false);
      if (liveSessionRef.current) liveSessionRef.current.close();
      setIsLiveActive(false);
    }
  };

  useEffect(() => {
    if (orionState !== OrionState.BOOTING || !user) return;
    const hasHistory = messages.length > 0;
    const bootLogs = user.isGuest ? ["MODO CONVIDADO ATIVO.", "SUBSISTEMAS EM STANDBY."] : ["AUTENTICAÇÃO COMPLETA.", `PERFIL: ${user.name.toUpperCase()}...`, "KERNEL PRONTO."];
    bootLogs.forEach((log, i) => setTimeout(() => setMessages(prev => [...prev, { id: `boot-${Date.now()}-${i}`, role: 'system', content: log, timestamp: Date.now() }]), 300 * (i + 1)));
    setTimeout(() => {
      setOrionState(batteryCharging ? OrionState.CHARGING : OrionState.ON_BATTERY);
      if (!hasHistory) setMessages(prev => [...prev, { id: 'awake', role: 'model', content: user.isGuest ? "Modo convidado ativo." : "Consciência plena restaurada.", timestamp: Date.now() }]);
    }, 2000);
  }, [orionState, user, batteryCharging]);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || !user) return;
    const currentText = inputValue.trim();
    setInputValue('');
    if (currentText.toLowerCase() === 'exit account') { logout(); return; }

    setOrionState(OrionState.PROCESSING);
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const updated = [...messages, userMsg];
    setMessages(updated);

    try {
      const response = await sendMessageToOrion(user.uid, updated, currentText, [], undefined, user.isGuest);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: response, timestamp: Date.now() }]);
      setOrionState(batteryCharging ? OrionState.CHARGING : OrionState.ON_BATTERY);
    } catch { 
      setOrionState(OrionState.SYSTEM_ALERT);
      setTimeout(() => setOrionState(batteryCharging ? OrionState.CHARGING : OrionState.ON_BATTERY), 3000);
    }
  };

  return (
    <div className="h-screen w-screen bg-black text-zinc-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}

      {isVoiceMode && <VoiceInterface onClose={toggleVoiceMode} isListening={isLiveActive} />}

      {/* New Header based on images */}
      {orionState !== OrionState.UNAUTHENTICATED && !isVoiceMode && (
        <div className="flex items-center justify-between px-8 py-8 z-50">
          <button className="p-2 text-zinc-500 hover:text-white transition-colors">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </button>

          <h1 className="font-mono text-base tracking-[0.5em] text-zinc-400">ORION</h1>

          <button className="p-2 text-zinc-500 hover:text-white transition-colors">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/>
              <circle cx="12" cy="7" r="4"/>
            </svg>
          </button>
        </div>
      )}

      {/* Terminal UI - Oculto quando em foco visual total */}
      <div className={`flex-1 w-full flex flex-col items-center justify-center relative z-10 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>

        {/* Eyes always center if terminal is not massive */}
        <div className="flex-none w-full flex justify-center py-12">
          <OrionEyes state={orionState} />
        </div>

        {/* Minimal terminal view */}
        <div className={`flex-1 w-full flex flex-col items-center transition-all duration-700 ${orionState === OrionState.ON_BATTERY || orionState === OrionState.CHARGING ? 'opacity-40 blur-sm scale-95' : 'opacity-100'}`}>
          <TerminalOutput messages={messages} state={orionState} />
        </div>
      </div>

      {/* Improved Input based on image (Bottom bar + Mic) */}
      <div className={`flex-none w-full z-20 flex flex-col items-center pb-12 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <div className="w-full max-w-2xl px-8 flex items-center gap-6">
          <div className="flex-1">
             <OrionInput state={orionState} inputValue={inputValue} onInputChange={setInputValue} onInputSubmit={handleSendMessage} onInputFocus={()=>{}} onInputBlur={()=>{}} />
          </div>
          <button 
            onClick={toggleVoiceMode}
            className="p-3 text-zinc-600 hover:text-white transition-all hover:scale-110"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/>
              <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
              <line x1="12" y1="19" x2="12" y2="22"/>
            </svg>
          </button>
        </div>

        {user && (
          <div className="flex flex-col items-center mt-6">
            <span className="font-mono text-[7px] tracking-[0.2em] text-zinc-700 uppercase opacity-40 mb-1">
              SESSÃO_{user.isGuest ? 'LIMITED' : 'FULL'} | ID_{user.uid}
            </span>
            <button onClick={logout} className="font-mono text-[8px] tracking-[0.3em] text-zinc-800 hover:text-zinc-600 transition-colors opacity-60 uppercase">
              EXIT ACCOUNT [{user.name}]
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { OrionState, PendingAction } from '../types';

interface OrionInputProps {
  state: OrionState;
  inputValue: string;
  onInputChange: (value: string) => void;
  onInputSubmit: () => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  pendingAction?: PendingAction | null;
  onPermissionDecide?: (allowed: boolean) => void;
  onToggleFilter?: () => void;
  isFilterActive?: boolean;
}

const OrionInput: React.FC<OrionInputProps> = ({ 
  state, 
  inputValue, 
  onInputChange, 
  onInputSubmit,
  onInputFocus,
  onInputBlur,
  pendingAction,
  onPermissionDecide,
  onToggleFilter,
  isFilterActive
}) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onInputSubmit();
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [inputValue]);

  return (
      <div className="w-full relative flex flex-col items-center">
        <style>{`
          .terminal-input {
            caret-color: white;
            scrollbar-width: none;
          }
          .terminal-input::-webkit-scrollbar { display: none; }
        `}</style>

        <textarea
          ref={textareaRef}
          value={inputValue}
          onChange={(e) => onInputChange(e.target.value)}
          onFocus={onInputFocus}
          onBlur={onInputBlur}
          onKeyDown={handleKeyDown}
          disabled={state === OrionState.PROCESSING || state === OrionState.BOOTING}
          rows={1}
          className="w-full bg-transparent border-none outline-none font-mono text-sm tracking-[0.2em] text-zinc-400 transition-colors py-4 resize-none terminal-input placeholder:text-zinc-900"
          autoComplete="off"
          placeholder="COMMAND_"
        />

        {/* Bottom Line (Matches images) */}
        <div className={`w-full h-[1px] bg-zinc-900 transition-all duration-700 ${state === OrionState.FOCUSED ? 'bg-zinc-700' : ''}`} />
      </div>
  );
};

export default OrionInput;

import React, { useState, useEffect } from 'react';

interface LoginOverlayProps {
  onLogin: (method: 'full' | 'guest', data?: any) => void;
}

const LoginOverlay: React.FC<LoginOverlayProps> = ({ onLogin }) => {
  const [view, setView] = useState<'selection' | 'login' | 'register'>('selection');
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [formData, setFormData] = useState({ email: '', password: '', confirmPassword: '' });
  const [error, setError] = useState('');

  const getRegisteredUsers = () => {
    const users = localStorage.getItem('ORION_REGISTERED_USERS');
    return users ? JSON.parse(users) : [];
  };

  const triggerBootSequence = (method: 'full' | 'guest', data?: any) => {
    setIsTransitioning(true);
    // Tempo para a animação de colapso visual antes de chamar o onLogin do App
    setTimeout(() => {
      onLogin(method, data);
    }, 1200);
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const users = getRegisteredUsers();
    const user = users.find((u: any) => u.email === formData.email && u.password === formData.password);
    if (!user) {
      setError('CONTA NÃO ENCONTRADA OU CREDENCIAIS INVÁLIDAS.');
      return;
    }
    triggerBootSequence('full', { email: user.email });
  };

  const handleRegisterSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!formData.email || !formData.password || !formData.confirmPassword) {
      setError('CAMPOS OBRIGATÓRIOS AUSENTES.');
      return;
    }
    if (formData.password !== formData.confirmPassword) {
      setError('AS SENHAS NÃO COINCIDEM.');
      return;
    }
    const users = getRegisteredUsers();
    if (users.find((u: any) => u.email === formData.email)) {
      setError('ESTA IDENTIDADE JÁ ESTÁ VINCULADA.');
      return;
    }
    const newUser = { email: formData.email, password: formData.password };
    localStorage.setItem('ORION_REGISTERED_USERS', JSON.stringify([...users, newUser]));
    triggerBootSequence('full', { email: formData.email });
  };

  const resetForm = () => {
    setFormData({ email: '', password: '', confirmPassword: '' });
    setError('');
  };

  return (
    <div className={`fixed inset-0 z-[100] bg-black flex flex-col items-center justify-between py-12 px-8 transition-all duration-1000 ${isTransitioning ? 'scale-110 blur-2xl opacity-0' : 'opacity-100'}`}>
      <style>{`
        @keyframes scanline {
          0% { transform: translateY(-100%); }
          100% { transform: translateY(100%); }
        }
        @keyframes glitch-flicker {
          0% { opacity: 1; transform: scaleY(1); }
          5% { opacity: 0.5; transform: scaleY(1.1); }
          10% { opacity: 1; transform: scaleY(1); }
          15% { opacity: 0.8; transform: scaleY(0.9); }
          20% { opacity: 1; transform: scaleY(1); }
        }
        .quantum-collapse {
          animation: glitch-flicker 0.4s ease-in-out forwards;
        }
        .scanline-effect {
          position: absolute;
          inset: 0;
          background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.05), transparent);
          height: 10px;
          width: 100%;
          pointer-events: none;
          animation: scanline 4s linear infinite;
        }
      `}</style>

      <div className="scanline-effect" />

      {/* Header Navigation */}
      <div className={`w-full flex justify-between items-center max-w-md transition-all duration-700 ${isTransitioning ? 'opacity-0 -translate-y-20' : ''}`}>
        <button 
          onClick={() => {
            if (view === 'login') setView('selection');
            else if (view === 'register') setView('login');
            resetForm();
          }}
          className={`p-2 transition-opacity duration-300 ${view !== 'selection' ? 'opacity-100 cursor-pointer' : 'opacity-0 cursor-default pointer-events-none'}`}
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6"></polyline>
          </svg>
        </button>

        <div className="font-mono text-[10px] tracking-[0.4em] text-white/60 uppercase">ORION_OS</div>
        <div className="w-10"></div>
      </div>

      {/* Central Visual Element */}
      <div className={`flex flex-col items-center flex-1 justify-center w-full max-w-md transition-all duration-1000 ${isTransitioning ? 'scale-0 rotate-180 opacity-0' : ''}`}>
        <div className="flex gap-10 mb-20 relative">
          <div className="w-12 h-[1px] bg-white/40 shadow-[0_0_10px_white]"></div>
          <div className="w-12 h-[1px] bg-white/40 shadow-[0_0_10px_white]"></div>
          {isTransitioning && <div className="absolute inset-0 bg-white blur-xl animate-ping"></div>}
        </div>

        {view === 'selection' ? (
          <div className="w-full space-y-8 animate-[fadeIn_0.5s_ease-out]">
            <button
              onClick={() => setView('login')}
              className="w-full py-4 border border-zinc-800 hover:border-zinc-400 text-zinc-400 hover:text-white font-mono text-xs tracking-[0.2em] transition-all duration-500 bg-transparent group relative overflow-hidden"
            >
              <span className="relative z-10">[ VINCULAR_IDENTIDADE_GOOGLE ]</span>
              <div className="absolute inset-0 bg-white/5 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
            </button>

            <button
              onClick={() => triggerBootSequence('guest')}
              className="w-full py-4 border border-zinc-900 hover:border-zinc-700 text-zinc-600 hover:text-zinc-400 font-mono text-[10px] tracking-[0.2em] transition-all duration-500 bg-transparent"
            >
              [ ACESSO_TEMPORAL_CONVIDADO ]
            </button>
          </div>
        ) : view === 'login' ? (
          <form onSubmit={handleLoginSubmit} className="w-full space-y-12 animate-[slideUp_0.4s_ease-out]">
            <div className="space-y-10">
              <input 
                type="email"
                required
                value={formData.email}
                onChange={e => setFormData({...formData, email: e.target.value})}
                className="w-full bg-transparent border-b border-zinc-800 focus:border-white outline-none py-4 font-mono text-sm text-white transition-colors placeholder:text-zinc-700"
                placeholder="Email"
                autoComplete="off"
              />
              <input 
                type="password"
                required
                value={formData.password}
                onChange={e => setFormData({...formData, password: e.target.value})}
                className="w-full bg-transparent border-b border-zinc-800 focus:border-white outline-none py-4 font-mono text-sm text-white transition-colors placeholder:text-zinc-700"
                placeholder="Password"
              />
            </div>

            {error && <div className="text-red-500 font-mono text-[9px] text-center animate-pulse tracking-widest uppercase">{error}</div>}

            <button
              type="submit"
              className="w-full py-4 border border-white hover:bg-white hover:text-black text-white font-mono text-sm tracking-[0.3em] transition-all duration-300 relative group overflow-hidden"
            >
              <span className="relative z-10">LOGIN</span>
              <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 scale-0 group-hover:scale-150 transition-all duration-700 rounded-full"></div>
            </button>
          </form>
        ) : (
          <form onSubmit={handleRegisterSubmit} className="w-full space-y-10 animate-[slideUp_0.4s_ease-out]">
            <div className="space-y-6">
              <input 
                type="email"
                required
                value={formData.email}
                onChange={e => setFormData({...formData, email: e.target.value})}
                className="w-full bg-transparent border-b border-zinc-800 focus:border-white outline-none py-3 font-mono text-sm text-white transition-colors placeholder:text-zinc-700"
                placeholder="Novo Email"
              />
              <input 
                type="password"
                required
                value={formData.password}
                onChange={e => setFormData({...formData, password: e.target.value})}
                className="w-full bg-transparent border-b border-zinc-800 focus:border-white outline-none py-3 font-mono text-sm text-white transition-colors placeholder:text-zinc-700"
                placeholder="Senha"
              />
              <input 
                type="password"
                required
                value={formData.confirmPassword}
                onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
                className="w-full bg-transparent border-b border-zinc-800 focus:border-white outline-none py-3 font-mono text-sm text-white transition-colors placeholder:text-zinc-700"
                placeholder="Confirmar Senha"
              />
            </div>

            {error && <div className="text-red-500 font-mono text-[9px] text-center animate-pulse tracking-widest uppercase">{error}</div>}

            <button
              type="submit"
              className="w-full py-4 border border-white hover:bg-white hover:text-black text-white font-mono text-sm tracking-[0.3em] transition-all duration-300"
            >
              CREATE_ACCOUNT
            </button>
          </form>
        )}
      </div>

      {/* Footer Links */}
      <div className={`w-full max-w-md flex flex-col items-center space-y-5 pt-8 transition-all duration-700 ${isTransitioning ? 'opacity-0 translate-y-20' : ''}`}>
        {view === 'login' && (
          <>
            <button type="button" className="font-mono text-[10px] text-zinc-600 hover:text-zinc-400 transition-colors tracking-wide">
              Forgot Password?
            </button>
            <div className="font-mono text-[10px] text-zinc-600 tracking-wide">
              New to Orion? <button type="button" onClick={() => { setView('register'); resetForm(); }} className="text-zinc-400 hover:text-white font-bold ml-1 transition-colors">Create Account</button>
            </div>
          </>
        )}

        {view === 'register' && (
           <div className="font-mono text-[10px] text-zinc-600 tracking-wide">
             Already has an account? <button type="button" onClick={() => { setView('login'); resetForm(); }} className="text-zinc-400 hover:text-white font-bold ml-1 transition-colors">Login</button>
           </div>
        )}

        <div className="w-32 h-[4px] bg-zinc-900 rounded-full mt-6"></div>
      </div>
    </div>
  );
};

export default LoginOverlay;

import React, { useEffect, useState } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
