    if (content.includes('[NÚCLEO DE TELEMETRIA') || content.includes('REPORT') || content.includes('::')) {
      return (
        <div className="bg-zinc-900/40 p-3 rounded border-l-2 border-zinc-500/30 font-mono text-[13px]">
