import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import LoginOverlay from './components/LoginOverlay';
import VoiceInterface from './components/VoiceInterface';
import { Message, OrionState, UserSession, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveHistory, getHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.UNAUTHENTICATED);
  const [user, setUser] = useState<UserSession | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [batteryCharging, setBatteryCharging] = useState(false);
  const [cpuLoad, setCpuLoad] = useState(25);

  const resetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cpuWarningStartTime = useRef<number | null>(null);

  const setTimedState = (state: OrionState, duration: number = 5000) => {
    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
    setOrionState(state);
    resetTimerRef.current = setTimeout(() => {
      setOrionState(OrionState.IDLE);
    }, duration);
  };

  // Monitoramento Simulado de CPU
  useEffect(() => {
    if (orionState === OrionState.UNAUTHENTICATED) return;

    const interval = setInterval(() => {
      // Simulação de oscilação de CPU
      const baseLoad = Math.random() * 20 + 15; // 15-35%
      const spikes = Math.random() > 0.95 ? 60 : 0; // Picos ocasionais
      const currentLoad = Math.min(100, Math.round(baseLoad + spikes));
      setCpuLoad(currentLoad);

      if (currentLoad > 80) {
        if (!cpuWarningStartTime.current) cpuWarningStartTime.current = Date.now();
        const duration = (Date.now() - cpuWarningStartTime.current) / 1000;

        if (duration > 30) {
          setTimedState(OrionState.SYSTEM_ALERT, 10000);
          setMessages(prev => [...prev, {
            id: `sys-cpu-${Date.now()}`,
            role: 'system',
            content: "ALERTA: SOBRECARGA CRÍTICA NOS NÚCLEOS (CPU > 80% POR 30S). DISSIPAÇÃO TÉRMICA REQUERIDA.",
            timestamp: Date.now()
          }]);
          cpuWarningStartTime.current = null; // Reset após o alerta
        }
      } else {
        cpuWarningStartTime.current = null;
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [orionState]);

  // Battery Detection
  useEffect(() => {
    const monitorBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        const battery = await navigator.getBattery();
        setBatteryCharging(battery.charging);
        const updateCharging = () => {
          setBatteryCharging(battery.charging);
          setTimedState(battery.charging ? OrionState.CHARGING : OrionState.ON_BATTERY, 8000);
        };
        battery.addEventListener('chargingchange', updateCharging);
        return () => battery.removeEventListener('chargingchange', updateCharging);
      }
    };
    monitorBattery();
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('ORION_USER_SESSION');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      setOrionState(OrionState.BOOTING);
    }
  }, []);

  useEffect(() => {
    if (user && messages.length > 0) saveHistory(user.uid, messages);
  }, [messages, user]);

  const handleLogin = (method: 'full' | 'guest', data?: any) => {
    setOrionState(OrionState.AUTHENTICATING);
    setMessages([]);
    setTimeout(() => {
      const isGuest = method === 'guest';
      const userData: UserSession = !isGuest
        ? { uid: 'u-' + btoa(data.email).replace(/=/g, '').substr(0, 12), name: data.email.split('@')[0], email: data.email, isGuest: false }
        : { uid: 'guest-' + Date.now(), name: 'Visitante Temporal', email: '', isGuest: true };
      localStorage.setItem('ORION_USER_SESSION', JSON.stringify(userData));
      setUser(userData);
      setMessages(getHistory(userData.uid));
      setOrionState(OrionState.BOOTING);
    }, 1500);
  };

  const logout = useCallback(() => {
    setOrionState(OrionState.SQUINTING);
    setMessages(prev => [...prev, { id: `sys-${Date.now()}`, role: 'system', content: "ENCERRANDO CICLO DE SESSÃO...", timestamp: Date.now() }]);
    setTimeout(() => {
      localStorage.removeItem('ORION_USER_SESSION');
      setUser(null);
      setMessages([]);
      setOrionState(OrionState.UNAUTHENTICATED);
      setIsVoiceMode(false);
    }, 1500);
  }, []);

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || !user) return;
    const currentText = inputValue.trim();
    setInputValue('');
    if (currentText.toLowerCase() === 'exit account') { logout(); return; }

    setOrionState(OrionState.PROCESSING);
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const updated = [...messages, userMsg];
    setMessages(updated);

    try {
      const response = await sendMessageToOrion(user.uid, updated, currentText, [], undefined, user.isGuest);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: response, timestamp: Date.now() }]);
      setTimedState(OrionState.ACTIVE, 3000);
    } catch { 
      setTimedState(OrionState.SYSTEM_ALERT, 6000);
    }
  };

  useEffect(() => {
    if (orionState !== OrionState.BOOTING || !user) return;
    const hasHistory = messages.length > 0;
    const bootLogs = user.isGuest ? ["MODO CONVIDADO ATIVO.", "SUBSISTEMAS EM STANDBY."] : ["AUTENTICAÇÃO COMPLETA.", `PERFIL: ${user.name.toUpperCase()}...`, "KERNEL PRONTO."];
    bootLogs.forEach((log, i) => setTimeout(() => setMessages(prev => [...prev, { id: `boot-${Date.now()}-${i}`, role: 'system', content: log, timestamp: Date.now() }]), 300 * (i + 1)));
    setTimeout(() => {
      setOrionState(OrionState.IDLE);
      if (!hasHistory) setMessages(prev => [...prev, { id: 'awake', role: 'model', content: user.isGuest ? "Modo convidado ativo." : "Consciência plena restaurada.", timestamp: Date.now() }]);
    }, 2000);
  }, [orionState, user]);

  return (
    <div className="h-screen w-screen bg-black text-zinc-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}

      {isVoiceMode && <VoiceInterface onClose={() => setIsVoiceMode(false)} isListening={true} />}

      {/* Header Fixo */}
      {orionState !== OrionState.UNAUTHENTICATED && !isVoiceMode && (
        <div className="flex-none flex items-center justify-center py-6 z-50">
          <h1 className="font-mono text-base tracking-[0.5em] text-zinc-500">ORION</h1>
        </div>
      )}

      {/* Área Central: Olhos e Terminal */}
      <div className={`flex-1 w-full flex flex-col relative z-10 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>

        {/* Olhos: Altura fixa para não empurrar o terminal */}
        <div className="flex-none h-[220px] flex items-center justify-center">
          <OrionEyes state={orionState} />
        </div>

        {/* Terminal: Ocupa o espaço restante e tem scroll interno */}
        <div className="flex-1 w-full overflow-hidden flex flex-col items-center">
          <TerminalOutput messages={messages} state={orionState} />
        </div>
      </div>

      {/* Área de Entrada: Fixa na base */}
      <div className={`flex-none w-full z-20 flex flex-col items-center pb-8 pt-4 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <div className="w-full max-w-2xl px-8 flex items-center gap-6">
          <div className="flex-1">
             <OrionInput 
               state={orionState} 
               inputValue={inputValue} 
               onInputChange={setInputValue} 
               onInputSubmit={handleSendMessage} 
               onInputFocus={() => { if(orionState === OrionState.IDLE) setOrionState(OrionState.FOCUSED); }} 
               onInputBlur={() => { if(orionState === OrionState.FOCUSED) setOrionState(OrionState.IDLE); }} 
             />
          </div>
          <button 
            onClick={() => setIsVoiceMode(true)}
            className="p-3 text-zinc-600 hover:text-white transition-all hover:scale-110"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/>
              <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
              <line x1="12" y1="19" x2="12" y2="22"/>
            </svg>
          </button>
        </div>

        {user && (
          <div className="flex flex-col items-center mt-4 h-6">
            <span className="font-mono text-[7px] tracking-[0.2em] text-zinc-700 uppercase opacity-40">
              SESSÃO_{user.isGuest ? 'LIMITED' : 'FULL'} | ID_{user.uid} | LOAD_{cpuLoad}%
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

