import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const [bootProgress, setBootProgress] = useState(0);
  const blinkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const blink = () => {
      if (
        state === OrionState.BOOTING ||
        state === OrionState.SLEEPING || 
        state === OrionState.UNAUTHENTICATED ||
        state === OrionState.AUTHENTICATING
      ) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 120);

      // Blink frequency varies by state to feel natural
      let nextBlink = 4000 + Math.random() * 4000;

      if (state === OrionState.FOCUSED || state === OrionState.LISTENING) {
        nextBlink = 2000 + Math.random() * 2000; 
      } else if (state === OrionState.PROCESSING) {
        nextBlink = 8000 + Math.random() * 4000; // Focused deep thought
      } else if (state === OrionState.IDLE) {
        nextBlink = 5000 + Math.random() * 5000;
      }

      blinkTimeoutRef.current = setTimeout(blink, nextBlink);
    };

    blinkTimeoutRef.current = setTimeout(blink, 2000);
    return () => {
      if (blinkTimeoutRef.current) clearTimeout(blinkTimeoutRef.current);
    };
  }, [state]);

  const getStateConfig = () => {
    let config = {
      color: "bg-white",
      glow: "shadow-[0_0_50px_rgba(255,255,255,0.3)]",
      text: "",
      barColor: "bg-white/10",
      highlightColor: "bg-white/70",
      animation: "animate-idle-wander" // Default subtle wander
    };

    switch (state) {
      case OrionState.IDLE:
        config = {
          ...config,
          text: "SISTEMA_ESTÁVEL",
          animation: "animate-idle-wander"
        };
        break;
      case OrionState.ACTIVE:
        config = {
          color: "bg-white",
          glow: "shadow-[0_0_60px_rgba(255,255,255,0.5)]",
          text: "INTERAÇÃO_ATIVA",
          barColor: "bg-white/10",
          highlightColor: "bg-white",
          animation: "animate-active-react"
        };
        break;
      case OrionState.LISTENING:
        config = {
          color: "bg-white",
          glow: "shadow-[0_0_70px_rgba(255,255,255,0.6)]",
          text: "PERCEBENDO_ÁUDIO",
          barColor: "bg-white/20",
          highlightColor: "bg-white",
          animation: "animate-listening-pulse"
        };
        break;
      case OrionState.CHARGING:
        config = {
          color: "bg-[#00e676]",
          glow: "shadow-[0_0_60px_rgba(0,230,118,0.5)]",
          text: "ENERGIA_ESTÁVEL",
          barColor: "bg-[#00e676]/10",
          highlightColor: "bg-[#00e676]",
          animation: "animate-pulse-soft"
        };
        break;
      case OrionState.ON_BATTERY:
        config = {
          color: "bg-[#ffa726]",
          glow: "shadow-[0_0_60px_rgba(255,167,38,0.4)]",
          text: "FLUXO_DISSIPANDO",
          barColor: "bg-[#ffa726]/10",
          highlightColor: "bg-[#ffa726]",
          animation: "animate-idle-wander"
        };
        break;
      case OrionState.SYSTEM_ALERT:
        config = {
          color: "bg-[#ff5252]",
          glow: "shadow-[0_0_70px_rgba(255,82,82,0.6)]",
          text: "ALERTA_DE_SISTEMA",
          barColor: "bg-[#ff5252]/10",
          highlightColor: "bg-[#ff5252]",
          animation: "animate-shake-system"
        };
        break;
      case OrionState.PROCESSING:
        config = {
          color: "bg-[#00e5ff]",
          glow: "shadow-[0_0_60px_rgba(0,229,255,0.5)]",
          text: "CONSOLIDANDO_DADOS",
          barColor: "bg-[#00e5ff]/10",
          highlightColor: "bg-[#00e5ff]",
          animation: "animate-think-square"
        };
        break;
      case OrionState.FOCUSED:
        config = {
          color: "bg-white",
          glow: "shadow-[0_0_50px_rgba(255,255,255,0.6)]",
          text: "ATENÇÃO_SUTIL",
          barColor: "bg-white/10",
          highlightColor: "bg-white",
          animation: "animate-attention"
        };
        break;
      case OrionState.UNAUTHENTICATED:
        config.color = "bg-white/5";
        config.glow = "shadow-none";
        config.animation = "";
        break;
    }
    return config;
  };

  const config = getStateConfig();
  const blinkStyle = isBlinking ? 'scale-y-[0.05] opacity-0' : 'scale-y-100 opacity-100';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none transition-all duration-700">
      <style>{`
        .eye-sq {
          width: 80px;
          height: 80px;
          border-radius: 18px;
          transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.1s ease-out, opacity 0.1s ease-out;
        }

        /* Subtle human-like wander for IDLE */
        @keyframes idle-wander {
          0%, 100% { transform: translate(0, 0); }
          25% { transform: translate(2px, -1px); }
          50% { transform: translate(-1px, 2px); }
          75% { transform: translate(-2px, -1px); }
        }
        .animate-idle-wander { animation: idle-wander 8s ease-in-out infinite; }

        /* Reactive expansion for ACTIVE */
        @keyframes active-react {
          0%, 100% { transform: scale(1); filter: brightness(1); }
          50% { transform: scale(1.04); filter: brightness(1.15); }
        }
        .animate-active-react { animation: active-react 3s ease-in-out infinite; }

        /* Rhythmic attention for LISTENING */
        @keyframes listening-pulse {
          0%, 100% { transform: scale(1) translateY(0); box-shadow: 0 0 40px rgba(255,255,255,0.3); }
          50% { transform: scale(1.02) translateY(-2px); box-shadow: 0 0 70px rgba(255,255,255,0.6); }
        }
        .animate-listening-pulse { animation: listening-pulse 1s ease-in-out infinite; }

        @keyframes shake-system {
          0%, 100% { transform: translate(0, 0); }
          20% { transform: translate(-3px, 3px); }
          40% { transform: translate(-3px, -3px); }
          60% { transform: translate(3px, 3px); }
          80% { transform: translate(3px, -3px); }
        }
        .animate-shake-system { animation: shake-system 0.15s ease-in-out infinite; }

        @keyframes think-square {
          0% { transform: scale(1) rotate(0deg); opacity: 0.85; }
          50% { transform: scale(0.96) rotate(3deg); opacity: 1; }
          100% { transform: scale(1) rotate(0deg); opacity: 0.85; }
        }
        .animate-think-square { animation: think-square 2.5s cubic-bezier(0.45, 0, 0.55, 1) infinite; }

        @keyframes pulse-soft {
          0% { opacity: 0.7; transform: scale(1); }
          100% { opacity: 1; transform: scale(1.03); }
        }
        .animate-pulse-soft { animation: pulse-soft 2s ease-in-out infinite alternate; }

        @keyframes attention {
          0% { transform: scale(1); filter: brightness(1); }
          100% { transform: scale(1.05); filter: brightness(1.2); }
        }
        .animate-attention { animation: attention 2s ease-in-out infinite alternate; }

        @keyframes flow {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .animate-flow { animation: flow 2.5s ease-in-out infinite; }
      `}</style>

      {/* Eyes Container */}
      <div className="flex gap-8 mb-16">
        <div className={`eye-sq ${config.color} ${config.glow} ${blinkStyle} ${config.animation}`} />
        <div className={`eye-sq ${config.color} ${config.glow} ${blinkStyle} ${config.animation}`} />
      </div>

      {/* Status Label */}
      {config.text && (
        <div className="flex flex-col items-center animate-[fadeIn_0.5s_ease-out] h-12">
          <span className="font-mono text-[9px] tracking-[0.5em] mb-4 uppercase" style={{ color: config.highlightColor.replace('bg-', '') }}>
            {config.text}
          </span>

          <div className={`w-64 h-[1px] relative overflow-hidden ${config.barColor}`}>
             <div className={`absolute inset-y-0 w-1/3 blur-[2px] opacity-80 animate-flow ${config.highlightColor}`}></div>
          </div>
        </div>
      )}
    </div>
  );
