      setTimedState(OrionState.ACTIVE, 3000);
    } catch { 
      setTimedState(OrionState.SYSTEM_ALERT, 6000);
    }
  };

  const toggleVoiceMode = () => {
    const nextMode = !isVoiceMode;
    setIsVoiceMode(nextMode);
    setOrionState(nextMode ? OrionState.LISTENING : OrionState.IDLE);
  };

  useEffect(() => {
    if (orionState !== OrionState.BOOTING || !user) return;
    const bootLogs = user.isGuest ? ["MODO CONVIDADO ATIVO.", "SUBSISTEMAS EM STANDBY."] : ["AUTENTICAÇÃO COMPLETA.", `PERFIL: ${user.name.toUpperCase()}...`, "KERNEL PRONTO."];
    bootLogs.forEach((log, i) => setTimeout(() => setMessages(prev => [...prev, { id: `boot-${Date.now()}-${i}`, role: 'system', content: log, timestamp: Date.now() }]), 300 * (i + 1)));
    setTimeout(() => setOrionState(OrionState.IDLE), 2000);
  }, [orionState, user]);

  return (
    <div className="h-screen w-screen bg-black text-zinc-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}

      {isVoiceMode && <VoiceInterface onClose={toggleVoiceMode} isListening={true} />}

      {/* Header (Fixo) */}
      {orionState !== OrionState.UNAUTHENTICATED && !isVoiceMode && (
        <div className="flex-none flex items-center justify-center py-6 z-50">
          <h1 className="font-mono text-base tracking-[0.5em] text-zinc-500">ORION</h1>
        </div>
      )}

      {/* Área Central (Ajustável) */}
      <div className={`flex-1 w-full flex flex-col min-h-0 relative z-10 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>

        {/* Olhos (Fixo) */}
        <div className="flex-none h-[180px] flex items-center justify-center">
          <OrionEyes state={orionState} />
        </div>

        {/* Terminal (Rolável - O segredo está no min-h-0 e flex-1) */}
        <div className="flex-1 w-full min-h-0 overflow-hidden flex flex-col items-center">
          <TerminalOutput messages={messages} state={orionState} />
        </div>
      </div>

      {/* Base de Entrada (Ancorada) */}
      <div className={`flex-none w-full z-20 flex flex-col items-center pb-8 pt-4 transition-all duration-1000 ${isVoiceMode || orionState === OrionState.UNAUTHENTICATED ? 'opacity-0 translate-y-10' : 'opacity-100'}`}>
        <div className="w-full max-w-2xl px-8 flex items-center gap-6">
          <div className="flex-1">
             <OrionInput 
               state={orionState} 
               inputValue={inputValue} 
               onInputChange={setInputValue} 
               onInputSubmit={handleSendMessage} 
               onInputFocus={() => { if(orionState === OrionState.IDLE) setOrionState(OrionState.FOCUSED); }} 
               onInputBlur={() => { if(orionState === OrionState.FOCUSED) setOrionState(OrionState.IDLE); }} 
             />
          </div>
          <button 
            onClick={toggleVoiceMode}
            className="p-3 text-zinc-600 hover:text-white transition-all hover:scale-110"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/>
              <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
              <line x1="12" y1="19" x2="12" y2="22"/>
            </svg>
          </button>
        </div>

        {user && (
          <div className="flex flex-col items-center mt-4">
            <span className="font-mono text-[7px] tracking-[0.2em] text-zinc-700 uppercase opacity-40">
              SESSÃO_{user.isGuest ? 'LIMITED' : 'FULL'} | ID_{user.uid} | LOAD_{cpuLoad}%
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const blinkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const blink = () => {
      if (
        state === OrionState.BOOTING ||
        state === OrionState.SLEEPING || 
        state === OrionState.UNAUTHENTICATED ||
        state === OrionState.AUTHENTICATING
      ) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 100);

      // Ritmo rítmico e humano
      let nextBlink = 4000 + Math.random() * 5000;

      if (state === OrionState.FOCUSED) {
        // Atenção cadenciada: mais frequente e intencional
        nextBlink = 2200 + Math.random() * 800; 
      } else if (state === OrionState.LISTENING) {
        nextBlink = 1500; // Alerta máximo
      } else if (state === OrionState.PROCESSING) {
        nextBlink = 10000; // Concentração profunda
      }

      blinkTimeoutRef.current = setTimeout(blink, nextBlink);
    };

    blinkTimeoutRef.current = setTimeout(blink, 2000);
    return () => {
      if (blinkTimeoutRef.current) clearTimeout(blinkTimeoutRef.current);
    };
  }, [state]);

