              {line}
            </div>
          ))}
        </div>
      );
    }
    return content;
  };

  return (
    <div 
      ref={containerRef}
      className="h-full w-full max-w-2xl overflow-y-auto px-6 py-4 space-y-6 scroll-smooth scrollbar-hide"
