import React, { useState, useEffect, useCallback, useRef } from 'react';
import OrionEyes from './components/OrionEyes';
import OrionInput from './components/OrionInput';
import TerminalOutput from './components/TerminalOutput';
import LoginOverlay from './components/LoginOverlay';
import VoiceInterface from './components/VoiceInterface';
import { Message, OrionState, UserSession, SysNotification } from './types';
import { sendMessageToOrion } from './services/geminiService';
import { saveHistory, getHistory } from './services/memoryService';

const App: React.FC = () => {
  const [orionState, setOrionState] = useState<OrionState>(OrionState.UNAUTHENTICATED);
  const [user, setUser] = useState<UserSession | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [batteryCharging, setBatteryCharging] = useState(false);
  const [cpuLoad, setCpuLoad] = useState(25);

  const [notifFilter, setNotifFilter] = useState<'ALL' | 'CRITICAL_ONLY' | 'SILENT'>('ALL');

  const resetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const setTimedState = (state: OrionState, duration: number = 5000) => {
    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
    setOrionState(state);
    resetTimerRef.current = setTimeout(() => {
      setOrionState(OrionState.IDLE);
    }, duration);
  };

  // Monitor de Bateria
  useEffect(() => {
    const monitorBattery = async () => {
      // @ts-ignore
      if (navigator.getBattery) {
        // @ts-ignore
        const battery = await navigator.getBattery();
        const updateStatus = () => {
          setBatteryCharging(battery.charging);
          if (orionState !== OrionState.AUTHENTICATING && orionState !== OrionState.BOOTING) {
            setOrionState(battery.charging ? OrionState.CHARGING : OrionState.ON_BATTERY);
          }
        };
        updateStatus();
        battery.addEventListener('chargingchange', updateStatus);
        return () => battery.removeEventListener('chargingchange', updateStatus);
      }
    };
    monitorBattery();
  }, [orionState]);

  // Lógica de Foco Dinâmico (Busca vs Atenção)
  useEffect(() => {
    if (orionState === OrionState.FOCUSED || orionState === OrionState.FOCUSED_EMPTY) {
      setOrionState(inputValue.length > 0 ? OrionState.FOCUSED : OrionState.FOCUSED_EMPTY);
    }
  }, [inputValue]);

  useEffect(() => {
    const savedUser = localStorage.getItem('ORION_USER_SESSION');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      setOrionState(OrionState.BOOTING);
    }
  }, []);

  const handleLogin = (method: 'full' | 'guest', data?: any) => {
    setOrionState(OrionState.AUTHENTICATING);
    setTimeout(() => {
      const isGuest = method === 'guest';
      const userData: UserSession = !isGuest
        ? { uid: 'u-' + btoa(data.email).substr(0, 10), name: data.email.split('@')[0], email: data.email, isGuest: false }
        : { uid: 'guest-' + Date.now(), name: 'Visitante', email: '', isGuest: true };
      localStorage.setItem('ORION_USER_SESSION', JSON.stringify(userData));
      setUser(userData);
      setMessages(getHistory(userData.uid));
      setOrionState(OrionState.BOOTING);
    }, 1500);
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || orionState === OrionState.PROCESSING || !user) return;
    const currentText = inputValue.trim();
    setInputValue('');

    setOrionState(OrionState.PROCESSING);
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: currentText, timestamp: Date.now() };
    const updated = [...messages, userMsg];
    setMessages(updated);

    try {
      const response = await sendMessageToOrion(user.uid, updated, currentText, [], undefined, user.isGuest);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: response, timestamp: Date.now() }]);
      setTimedState(OrionState.ACTIVE, 3000);
    } catch { 
      setTimedState(OrionState.SYSTEM_ALERT, 6000);
    }
  };

  useEffect(() => {
    if (orionState !== OrionState.BOOTING || !user) return;
    setTimeout(() => setOrionState(batteryCharging ? OrionState.CHARGING : OrionState.IDLE), 2000);
  }, [orionState, user, batteryCharging]);

  return (
    <div className="h-screen w-screen bg-black text-zinc-200 flex flex-col relative overflow-hidden font-inter">
      {orionState === OrionState.UNAUTHENTICATED && <LoginOverlay onLogin={handleLogin} />}
      {isVoiceMode && <VoiceInterface onClose={() => setIsVoiceMode(false)} isListening={true} />}

      {/* Header Fixo */}
      <div className="flex-none flex items-center justify-center py-4 z-50">
        <h1 className="font-mono text-xs tracking-[0.8em] text-zinc-600 opacity-50">ORION_CORE</h1>
      </div>

      {/* Olhos Fixos */}
      <div className="flex-none h-[160px] flex items-center justify-center relative z-20">
        <OrionEyes state={orionState} />
      </div>

      {/* Terminal - Única parte que rola */}
      <div className="flex-1 min-h-0 w-full overflow-hidden flex flex-col items-center relative z-10">
        <TerminalOutput messages={messages} state={orionState} />
      </div>

      {/* Input Base Fixo */}
      <div className="flex-none w-full z-30 bg-black/80 backdrop-blur-md border-t border-zinc-900/50 pb-8 pt-4">
        <div className="w-full max-w-2xl mx-auto px-8 flex items-center gap-6">
          <div className="flex-1">
             <OrionInput 
               state={orionState} 
               inputValue={inputValue} 
               onInputChange={setInputValue} 
               onInputSubmit={handleSendMessage} 
               onInputFocus={() => setOrionState(inputValue.length > 0 ? OrionState.FOCUSED : OrionState.FOCUSED_EMPTY)} 
               onInputBlur={() => setOrionState(batteryCharging ? OrionState.CHARGING : OrionState.IDLE)} 
             />
          </div>
          <button onClick={() => setIsVoiceMode(true)} className="p-3 text-zinc-700 hover:text-white transition-all">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" y1="19" x2="12" y2="22"/></svg>
          </button>
        </div>
        {user && (
          <div className="text-center mt-3">
             <span className="font-mono text-[8px] tracking-[0.3em] text-zinc-800 uppercase">
               SYSTEM_STATUS: {orionState} | {batteryCharging ? 'PWR_AC' : 'PWR_BATT'}
             </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const blinkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const blink = () => {
      if (state === OrionState.BOOTING || state === OrionState.AUTHENTICATING) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 180); // Piscada mais longa e suave

      // Intervalo mais humano: entre 5 e 10 segundos
      const nextBlink = 5000 + Math.random() * 5000;
      blinkTimeoutRef.current = setTimeout(blink, nextBlink);
    };

    blinkTimeoutRef.current = setTimeout(blink, 3000);
    return () => { if (blinkTimeoutRef.current) clearTimeout(blinkTimeoutRef.current); };
  }, [state]);

  const getStateConfig = () => {
    let config = {
      color: "bg-zinc-100",
      glow: "shadow-[0_0_40px_rgba(255,255,255,0.2)]",
      text: "NÚCLEO_ESTÁVEL",
      animation: "animate-look-around", // Busca padrão
      eyeScale: "scale-100",
      opacity: "opacity-100"
    };

    switch (state) {
      case OrionState.IDLE:
        config.animation = "animate-look-around";
        break;
      case OrionState.FOCUSED_EMPTY:
        config.text = "BUSCANDO_INTENTOS";
        config.animation = "animate-search-intense";
        config.glow = "shadow-[0_0_50px_rgba(255,255,255,0.4)]";
        break;
      case OrionState.FOCUSED:
        config.text = "ATENÇÃO_PLENA";
        config.animation = "animate-pulse-fast";
        config.glow = "shadow-[0_0_60px_rgba(255,255,255,0.6)]";
        break;
      case OrionState.CHARGING:
        config.color = "bg-emerald-400";
        config.glow = "shadow-[0_0_70px_rgba(52,211,153,0.7)]";
