import React, { useEffect, useState, useRef } from 'react';
import { OrionState } from '../types';

interface OrionEyesProps {
  state: OrionState;
}

const OrionEyes: React.FC<OrionEyesProps> = ({ state }) => {
  const [isBlinking, setIsBlinking] = useState(false);
  const blinkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const blink = () => {
      if (state === OrionState.BOOTING || state === OrionState.AUTHENTICATING || state === OrionState.UNAUTHENTICATED) return;

      setIsBlinking(true);
      setTimeout(() => setIsBlinking(false), 250); 

      const nextBlink = 6000 + Math.random() * 8000;
      blinkTimeoutRef.current = setTimeout(blink, nextBlink);
    };

    blinkTimeoutRef.current = setTimeout(blink, 4000);
    return () => { if (blinkTimeoutRef.current) clearTimeout(blinkTimeoutRef.current); };
  }, [state]);

  const getStateConfig = () => {
    let config = {
      color: "bg-zinc-200",
      glow: "shadow-[0_0_40px_rgba(255,255,255,0.2)]",
      text: "SISTEMA_ESTÁVEL",
      animation: "animate-look-around",
      eyeScale: "scale-100",
      opacity: "opacity-100",
      brightness: "brightness-100"
    };

    switch (state) {
      case OrionState.IDLE:
        config.animation = "animate-look-around";
        break;
      case OrionState.FOCUSED_EMPTY:
        config.text = "BUSCANDO_INTENTOS";
        config.animation = "animate-search-intense";
        config.glow = "shadow-[0_0_50px_rgba(255,255,255,0.35)]";
        break;
      case OrionState.FOCUSED:
        config.text = "ATENÇÃO_PLENA";
        config.animation = "animate-attention-pulse";
        config.glow = "shadow-[0_0_60px_rgba(255,255,255,0.5)]";
        config.brightness = "brightness-125";
        break;
      case OrionState.SYSTEM_SEARCHING:
        config.color = "bg-cyan-200";
        config.text = "ESCANEANDO_HARDWARE";
        config.animation = "animate-system-scan";
        config.glow = "shadow-[0_0_70px_rgba(165,243,252,0.6)]";
        break;
      case OrionState.CHARGING:
        config.color = "bg-emerald-400";
        config.glow = "shadow-[0_0_80px_rgba(52,211,153,0.8)]";
        config.text = "ENERGIA_RESTAURADA";
        config.animation = "animate-energy-surge";
        config.eyeScale = "scale-115";
        break;
      case OrionState.ON_BATTERY:
        config.color = "bg-amber-600";
        config.glow = "shadow-[0_0_30px_rgba(217,119,6,0.3)]";
        config.text = "MODO_ECONOMIA_ATIVO";
        config.animation = "animate-tired-look";
        config.eyeScale = "scale-y-[0.82] scale-x-[0.98]";
        config.opacity = "opacity-50";
        break;
      case OrionState.PROCESSING:
        config.color = "bg-cyan-400";
        config.text = "PROCESSANDO_DADOS";
        config.animation = "animate-think-square";
        break;
      case OrionState.SYSTEM_ALERT:
        config.color = "bg-red-600";
        config.text = "ANOMALIA_DETECTADA";
        config.animation = "animate-shake-critical";
        config.glow = "shadow-[0_0_60px_rgba(220,38,38,0.7)]";
        config.brightness = "brightness-150";
        break;
      default:
        config.opacity = "opacity-40";
        break;
    }
    return config;
  };

  const config = getStateConfig();
  const blinkStyle = isBlinking ? 'scale-y-[0.01] opacity-0' : 'scale-y-100 opacity-100';

  return (
    <div className="flex flex-col items-center justify-center w-full select-none pointer-events-none">
      <style>{`
        .eye-core {
          width: 75px;
          height: 75px;
          border-radius: 22px;
          transition: all 0.7s cubic-bezier(0.16, 1, 0.3, 1);
        }

        @keyframes look-around {
          0%, 100% { transform: translate(0, 0); }
          25% { transform: translate(3px, -2px); }
          50% { transform: translate(-2px, 2px); }
          75% { transform: translate(-3px, -1px); }
        }
        .animate-look-around { animation: look-around 15s ease-in-out infinite; }

        @keyframes system-scan {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(15px); }
          40% { transform: translateX(-15px); }
          60% { transform: translateX(10px); }
          80% { transform: translateX(-10px); }
        }
        .animate-system-scan { animation: system-scan 0.8s ease-in-out infinite; }

        @keyframes search-intense {
          0%, 100% { transform: translate(0, 0); }
          20% { transform: translate(6px, 3px); }
          40% { transform: translate(-7px, -3px); }
          60% { transform: translate(5px, -5px); }
          80% { transform: translate(-3px, 6px); }
        }
        .animate-search-intense { animation: search-intense 4s ease-in-out infinite; }

        @keyframes energy-surge {
          0%, 100% { transform: scale(1.15); filter: brightness(1); }
          50% { transform: scale(1.22); filter: brightness(1.4); }
        }
        .animate-energy-surge { animation: energy-surge 1.5s ease-in-out infinite; }

        @keyframes shake-critical {
          0%, 100% { transform: translate(0, 0); }
          10%, 30%, 50%, 70%, 90% { transform: translate(-4px, 2px); }
          20%, 40%, 60%, 80% { transform: translate(4px, -2px); }
        }
        .animate-shake-critical { animation: shake-critical 0.3s cubic-bezier(.36,.07,.19,.97) both infinite; }

        @keyframes think-square {
          0% { transform: rotate(0deg) scale(0.95); }
